INSERT INTO bible_versions (version_id, code, title, language, source_path) VALUES
('grc_f35', 'GRC_F35', 'Greek NT — Family 35', 'grc', 'resources/biblias/GRC_F35.xml')
INSERT INTO bible_verses (version_id, ref, book, chapter, verse, text) VALUES
('grc_f35', 'Mateo 1:1', 'Mateo', 1, 1, 'βιβλος γενεσεως ιησου χριστου υιου δαυιδ υιου αβρααμ'),
('grc_f35', 'Mateo 1:2', 'Mateo', 1, 2, 'αβρααμ εγεννησεν τον ισαακ ισαακ δε εγεννησεν τον ιακωβ ιακωβ δε εγεννησεν τον ιουδαν και τους αδελφους αυτου'),
('grc_f35', 'Mateo 1:3', 'Mateo', 1, 3, 'ιουδας δε εγεννησεν τον φαρες και τον ζαρα εκ της θαμαρ φαρες δε εγεννησεν τον εσρωμ εσρωμ δε εγεννησεν τον αραμ'),
('grc_f35', 'Mateo 1:4', 'Mateo', 1, 4, 'αραμ δε εγεννησεν τον αμιναδαβ αμιναδαβ δε εγεννησεν τον ναασσων ναασσων δε εγεννησεν τον σαλμων'),
('grc_f35', 'Mateo 1:5', 'Mateo', 1, 5, 'σαλμων δε εγεννησεν τον βοοζ εκ της ραχαβ βοοζ δε εγεννησεν τον ωβηδ εκ της ρουθ ωβηδ δε εγεννησεν τον ιεσσαι'),
('grc_f35', 'Mateo 1:6', 'Mateo', 1, 6, 'ιεσσαι δε εγεννησεν τον δαυιδ τον βασιλεα δαυιδ δε ο βασιλευς εγεννησεν τον σολομωνα εκ της του ουριου'),
('grc_f35', 'Mateo 1:7', 'Mateo', 1, 7, 'σολομων δε εγεννησεν τον ροβοαμ ροβοαμ δε εγεννησεν τον αβια αβια δε εγεννησεν τον ασα'),
('grc_f35', 'Mateo 1:8', 'Mateo', 1, 8, 'ασα δε εγεννησεν τον ιωσαφατ ιωσαφατ δε εγεννησεν τον ιωραμ ιωραμ δε εγεννησεν τον οζιαν'),
('grc_f35', 'Mateo 1:9', 'Mateo', 1, 9, 'οζιας δε εγεννησεν τον ιωαθαμ ιωαθαμ δε εγεννησεν τον αχαζ αχαζ δε εγεννησεν τον εζεκιαν'),
('grc_f35', 'Mateo 1:10', 'Mateo', 1, 10, 'εζεκιας δε εγεννησεν τον μανασσην μανασσης δε εγεννησεν τον αμων αμων δε εγεννησεν τον ιωσιαν'),
('grc_f35', 'Mateo 1:11', 'Mateo', 1, 11, 'ιωσιας δε εγεννησεν τον ιεχονιαν και τους αδελφους αυτου επι της μετοικεσιας βαβυλωνος'),
('grc_f35', 'Mateo 1:12', 'Mateo', 1, 12, 'μετα δε την μετοικεσιαν βαβυλωνος ιεχονιας εγεννησεν τον σαλαθιηλ σαλαθιηλ δε εγεννησεν τον ζοροβαβελ'),
('grc_f35', 'Mateo 1:13', 'Mateo', 1, 13, 'ζοροβαβελ δε εγεννησεν τον αβιουδ αβιουδ δε εγεννησεν τον ελιακειμ ελιακειμ δε εγεννησεν τον αζωρ'),
('grc_f35', 'Mateo 1:14', 'Mateo', 1, 14, 'αζωρ δε εγεννησεν τον σαδωκ σαδωκ δε εγεννησεν τον αχειμ αχειμ δε εγεννησεν τον ελιουδ'),
('grc_f35', 'Mateo 1:15', 'Mateo', 1, 15, 'ελιουδ δε εγεννησεν τον ελεαζαρ ελεαζαρ δε εγεννησεν τον ματθαν ματθαν δε εγεννησεν τον ιακωβ'),
('grc_f35', 'Mateo 1:16', 'Mateo', 1, 16, 'ιακωβ δε εγεννησεν τον ιωσηφ τον ανδρα μαριας εξ ης εγεννηθη ιησους ο λεγομενος χριστος'),
('grc_f35', 'Mateo 1:17', 'Mateo', 1, 17, 'πασαι ουν αι γενεαι απο αβρααμ εως δαυιδ γενεαι δεκατεσσαρες και απο δαυιδ εως της μετοικεσιας βαβυλωνος γενεαι δεκατεσσαρες και απο της μετοικεσιας βαβυλωνος εως του χριστου γενεαι δεκατεσσαρες'),
('grc_f35', 'Mateo 1:18', 'Mateo', 1, 18, 'του δε ιησου χριστου η γεννησις ουτως ην μνηστευθεισης γαρ της μητρος αυτου μαριας τω ιωσηφ πριν η συνελθειν αυτους ευρεθη εν γαστρι εχουσα εκ πνευματος αγιου'),
('grc_f35', 'Mateo 1:19', 'Mateo', 1, 19, 'ιωσηφ δε ο ανηρ αυτης δικαιος ων και μη θελων αυτην παραδειγματισαι εβουληθη λαθρα απολυσαι αυτην'),
('grc_f35', 'Mateo 1:20', 'Mateo', 1, 20, 'ταυτα δε αυτου ενθυμηθεντος ιδου αγγελος κυριου κατ οναρ εφανη αυτω λεγων ιωσηφ υιος δαυιδ μη φοβηθης παραλαβειν μαριαμ την γυναικα σου το γαρ εν αυτη γεννηθεν εκ πνευματος εστιν αγιου'),
('grc_f35', 'Mateo 1:21', 'Mateo', 1, 21, 'τεξεται δε υιον και καλεσεις το ονομα αυτου ιησουν αυτος γαρ σωσει τον λαον αυτου απο των αμαρτιων αυτων'),
('grc_f35', 'Mateo 1:22', 'Mateo', 1, 22, 'τουτο δε ολον γεγονεν ινα πληρωθη το ρηθεν υπο του κυριου δια του προφητου λεγοντος'),
('grc_f35', 'Mateo 1:23', 'Mateo', 1, 23, 'ιδου η παρθενος εν γαστρι εξει και τεξεται υιον και καλεσουσιν το ονομα αυτου εμμανουηλ ο εστιν μεθερμηνευομενον μεθ ημων ο θεος'),
('grc_f35', 'Mateo 1:24', 'Mateo', 1, 24, 'διεγερθεις δε ο ιωσηφ απο του υπνου εποιησεν ως προσεταξεν αυτω ο αγγελος κυριου και παρελαβεν την γυναικα αυτου'),
('grc_f35', 'Mateo 1:25', 'Mateo', 1, 25, 'και ουκ εγινωσκεν αυτην εως ου ετεκεν τον υιον αυτης τον πρωτοτοκον και εκαλεσεν το ονομα αυτου ιησουν'),
('grc_f35', 'Mateo 2:1', 'Mateo', 2, 1, 'του δε ιησου γεννηθεντος εν βηθλεεμ της ιουδαιας εν ημεραις ηρωδου του βασιλεως ιδου μαγοι απο ανατολων παρεγενοντο εις ιεροσολυμα'),
('grc_f35', 'Mateo 2:2', 'Mateo', 2, 2, 'λεγοντες που εστιν ο τεχθεις βασιλευς των ιουδαιων ειδομεν γαρ αυτου τον αστερα εν τη ανατολη και ηλθομεν προσκυνησαι αυτω'),
('grc_f35', 'Mateo 2:3', 'Mateo', 2, 3, 'ακουσας δε ηρωδης ο βασιλευς εταραχθη και πασα ιεροσολυμα μετ αυτου'),
('grc_f35', 'Mateo 2:4', 'Mateo', 2, 4, 'και συναγαγων παντας τους αρχιερεις και γραμματεις του λαου επυνθανετο παρ αυτων που ο χριστος γενναται'),
('grc_f35', 'Mateo 2:5', 'Mateo', 2, 5, 'οι δε ειπον αυτω εν βηθλεεμ της ιουδαιας ουτως γαρ γεγραπται δια του προφητου'),
('grc_f35', 'Mateo 2:6', 'Mateo', 2, 6, 'και συ βηθλεεμ γη ιουδα ουδαμως ελαχιστη ει εν τοις ηγεμοσιν ιουδα εκ σου γαρ εξελευσεται ηγουμενος οστις ποιμανει τον λαον μου τον ισραηλ'),
('grc_f35', 'Mateo 2:7', 'Mateo', 2, 7, 'τοτε ηρωδης λαθρα καλεσας τους μαγους ηκριβωσεν παρ αυτων τον χρονον του φαινομενου αστερος'),
('grc_f35', 'Mateo 2:8', 'Mateo', 2, 8, 'και πεμψας αυτους εις βηθλεεμ ειπεν πορευθεντες ακριβως εξετασατε περι του παιδιου επαν δε ευρητε απαγγειλατε μοι οπως καγω ελθων προσκυνησω αυτω'),
('grc_f35', 'Mateo 2:9', 'Mateo', 2, 9, 'οι δε ακουσαντες του βασιλεως επορευθησαν και ιδου ο αστηρ ον ειδον εν τη ανατολη προηγεν αυτους εως ελθων εστη επανω ου ην το παιδιον'),
('grc_f35', 'Mateo 2:10', 'Mateo', 2, 10, 'ιδοντες δε τον αστερα εχαρησαν χαραν μεγαλην σφοδρα'),
('grc_f35', 'Mateo 2:11', 'Mateo', 2, 11, 'και ελθοντες εις την οικιαν ειδον το παιδιον μετα μαριας της μητρος αυτου και πεσοντες προσεκυνησαν αυτω και ανοιξαντες τους θησαυρους αυτων προσηνεγκαν αυτω δωρα χρυσον και λιβανον και σμυρναν'),
('grc_f35', 'Mateo 2:12', 'Mateo', 2, 12, 'και χρηματισθεντες κατ οναρ μη ανακαμψαι προς ηρωδην δι αλλης οδου ανεχωρησαν εις την χωραν αυτων'),
('grc_f35', 'Mateo 2:13', 'Mateo', 2, 13, 'αναχωρησαντων δε αυτων ιδου αγγελος κυριου φαινεται κατ οναρ τω ιωσηφ λεγων εγερθεις παραλαβε το παιδιον και την μητερα αυτου και φευγε εις αιγυπτον και ισθι εκει εως αν ειπω σοι μελλει γαρ ηρωδης ζητειν το παιδιον του απολεσαι αυτο'),
('grc_f35', 'Mateo 2:14', 'Mateo', 2, 14, 'ο δε εγερθεις παρελαβεν το παιδιον και την μητερα αυτου νυκτος και ανεχωρησεν εις αιγυπτον'),
('grc_f35', 'Mateo 2:15', 'Mateo', 2, 15, 'και ην εκει εως της τελευτης ηρωδου ινα πληρωθη το ρηθεν υπο του κυριου δια του προφητου λεγοντος εξ αιγυπτου εκαλεσα τον υιον μου'),
('grc_f35', 'Mateo 2:16', 'Mateo', 2, 16, 'τοτε ηρωδης ιδων οτι ενεπαιχθη υπο των μαγων εθυμωθη λιαν και αποστειλας ανειλεν παντας τους παιδας τους εν βηθλεεμ και εν πασιν τοις οριοις αυτης απο διετους και κατωτερω κατα τον χρονον ον ηκριβωσεν παρα των μαγων'),
('grc_f35', 'Mateo 2:17', 'Mateo', 2, 17, 'τοτε επληρωθη το ρηθεν υπο ιερεμιου του προφητου λεγοντος'),
('grc_f35', 'Mateo 2:18', 'Mateo', 2, 18, 'φωνη εν ραμα ηκουσθη θρηνος και κλαυθμος και οδυρμος πολυς ραχηλ κλαιουσα τα τεκνα αυτης και ουκ ηθελεν παρακληθηναι οτι ουκ εισιν'),
('grc_f35', 'Mateo 2:19', 'Mateo', 2, 19, 'τελευτησαντος δε του ηρωδου ιδου αγγελος κυριου κατ οναρ φαινεται τω ιωσηφ εν αιγυπτω'),
('grc_f35', 'Mateo 2:20', 'Mateo', 2, 20, 'λεγων εγερθεις παραλαβε το παιδιον και την μητερα αυτου και πορευου εις γην ισραηλ τεθνηκασιν γαρ οι ζητουντες την ψυχην του παιδιου'),
('grc_f35', 'Mateo 2:21', 'Mateo', 2, 21, 'ο δε εγερθεις παρελαβεν το παιδιον και την μητερα αυτου και ηλθεν εις γην ισραηλ'),
('grc_f35', 'Mateo 2:22', 'Mateo', 2, 22, 'ακουσας δε οτι αρχελαος βασιλευει επι της ιουδαιας αντι ηρωδου του πατρος αυτου εφοβηθη εκει απελθειν χρηματισθεις δε κατ οναρ ανεχωρησεν εις τα μερη της γαλιλαιας'),
('grc_f35', 'Mateo 2:23', 'Mateo', 2, 23, 'και ελθων κατωκησεν εις πολιν λεγομενην ναζαρετ οπως πληρωθη το ρηθεν δια των προφητων οτι ναζωραιος κληθησεται'),
('grc_f35', 'Mateo 3:1', 'Mateo', 3, 1, 'εν δε ταις ημεραις εκειναις παραγινεται ιωαννης ο βαπτιστης κηρυσσων εν τη ερημω της ιουδαιας'),
('grc_f35', 'Mateo 3:2', 'Mateo', 3, 2, 'και λεγων μετανοειτε ηγγικεν γαρ η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 3:3', 'Mateo', 3, 3, 'ουτος γαρ εστιν ο ρηθεις υπο ησαιου του προφητου λεγοντος φωνη βοωντος εν τη ερημω ετοιμασατε την οδον κυριου ευθειας ποιειτε τας τριβους αυτου'),
('grc_f35', 'Mateo 3:4', 'Mateo', 3, 4, 'αυτος δε ο ιωαννης ειχεν το ενδυμα αυτου απο τριχων καμηλου και ζωνην δερματινην περι την οσφυν αυτου η δε τροφη αυτου ην ακριδες και μελι αγριον'),
('grc_f35', 'Mateo 3:5', 'Mateo', 3, 5, 'τοτε εξεπορευετο προς αυτον ιεροσολυμα και πασα η ιουδαια και πασα η περιχωρος του ιορδανου'),
('grc_f35', 'Mateo 3:6', 'Mateo', 3, 6, 'και εβαπτιζοντο εν τω ιορδανη υπ αυτου εξομολογουμενοι τας αμαρτιας αυτων'),
('grc_f35', 'Mateo 3:7', 'Mateo', 3, 7, 'ιδων δε πολλους των φαρισαιων και σαδδουκαιων ερχομενους επι το βαπτισμα αυτου ειπεν αυτοις γεννηματα εχιδνων τις υπεδειξεν υμιν φυγειν απο της μελλουσης οργης'),
('grc_f35', 'Mateo 3:8', 'Mateo', 3, 8, 'ποιησατε ουν καρπον αξιον της μετανοιας'),
('grc_f35', 'Mateo 3:9', 'Mateo', 3, 9, 'και μη δοξητε λεγειν εν εαυτοις πατερα εχομεν τον αβρααμ λεγω γαρ υμιν οτι δυναται ο θεος εκ των λιθων τουτων εγειραι τεκνα τω αβρααμ'),
('grc_f35', 'Mateo 3:10', 'Mateo', 3, 10, 'ηδη δε και η αξινη προς την ριζαν των δενδρων κειται παν ουν δενδρον μη ποιουν καρπον καλον εκκοπτεται και εις πυρ βαλλεται'),
('grc_f35', 'Mateo 3:11', 'Mateo', 3, 11, 'εγω μεν βαπτιζω υμας εν υδατι εις μετανοιαν ο δε οπισω μου ερχομενος ισχυροτερος μου εστιν ου ουκ ειμι ικανος τα υποδηματα βαστασαι αυτος υμας βαπτισει εν πνευματι αγιω'),
('grc_f35', 'Mateo 3:12', 'Mateo', 3, 12, 'ου το πτυον εν τη χειρι αυτου και διακαθαριει την αλωνα αυτου και συναξει τον σιτον αυτου εις την αποθηκην το δε αχυρον κατακαυσει πυρι ασβεστω'),
('grc_f35', 'Mateo 3:13', 'Mateo', 3, 13, 'τοτε παραγινεται ο ιησους απο της γαλιλαιας επι τον ιορδανην προς τον ιωαννην του βαπτισθηναι υπ αυτου'),
('grc_f35', 'Mateo 3:14', 'Mateo', 3, 14, 'ο δε ιωαννης διεκωλυεν αυτον λεγων εγω χρειαν εχω υπο σου βαπτισθηναι και συ ερχη προς με'),
('grc_f35', 'Mateo 3:15', 'Mateo', 3, 15, 'αποκριθεις δε ο ιησους ειπεν προς αυτον αφες αρτι ουτως γαρ πρεπον εστιν ημιν πληρωσαι πασαν δικαιοσυνην τοτε αφιησιν αυτον'),
('grc_f35', 'Mateo 3:16', 'Mateo', 3, 16, 'και βαπτισθεις ο ιησους ανεβη ευθυς απο του υδατος και ιδου ανεωχθησαν αυτω οι ουρανοι και ειδεν το πνευμα του θεου καταβαινον ωσει περιστεραν και ερχομενον επ αυτον'),
('grc_f35', 'Mateo 3:17', 'Mateo', 3, 17, 'και ιδου φωνη εκ των ουρανων λεγουσα ουτος εστιν ο υιος μου ο αγαπητος εν ω ευδοκησα'),
('grc_f35', 'Mateo 4:1', 'Mateo', 4, 1, 'τοτε ο ιησους ανηχθη εις την ερημον υπο του πνευματος πειρασθηναι υπο του διαβολου'),
('grc_f35', 'Mateo 4:2', 'Mateo', 4, 2, 'και νηστευσας ημερας τεσσαρακοντα και νυκτας τεσσαρακοντα υστερον επεινασεν'),
('grc_f35', 'Mateo 4:3', 'Mateo', 4, 3, 'και προσελθων αυτω ο πειραζων ειπεν ει υιος ει του θεου ειπε ινα οι λιθοι ουτοι αρτοι γενωνται'),
('grc_f35', 'Mateo 4:4', 'Mateo', 4, 4, 'ο δε αποκριθεις ειπεν γεγραπται ουκ επ αρτω μονω ζησεται ανθρωπος αλλ επι παντι ρηματι εκπορευομενω δια στοματος θεου'),
('grc_f35', 'Mateo 4:5', 'Mateo', 4, 5, 'τοτε παραλαμβανει αυτον ο διαβολος εις την αγιαν πολιν και ιστησιν αυτον επι το πτερυγιον του ιερου'),
('grc_f35', 'Mateo 4:6', 'Mateo', 4, 6, 'και λεγει αυτω ει υιος ει του θεου βαλε σεαυτον κατω γεγραπται γαρ οτι τοις αγγελοις αυτου εντελειται περι σου και επι χειρων αρουσιν σε μηποτε προσκοψης προς λιθον τον ποδα σου'),
('grc_f35', 'Mateo 4:7', 'Mateo', 4, 7, 'εφη αυτω ο ιησους παλιν γεγραπται ουκ εκπειρασεις κυριον τον θεον σου'),
('grc_f35', 'Mateo 4:8', 'Mateo', 4, 8, 'παλιν παραλαμβανει αυτον ο διαβολος εις ορος υψηλον λιαν και δεικνυσιν αυτω πασας τας βασιλειας του κοσμου και την δοξαν αυτων'),
('grc_f35', 'Mateo 4:9', 'Mateo', 4, 9, 'και λεγει αυτω ταυτα παντα σοι δωσω εαν πεσων προσκυνησης μοι'),
('grc_f35', 'Mateo 4:10', 'Mateo', 4, 10, 'τοτε λεγει αυτω ο ιησους υπαγε οπισω μου σατανα γεγραπται γαρ κυριον τον θεον σου προσκυνησεις και αυτω μονω λατρευσεις'),
('grc_f35', 'Mateo 4:11', 'Mateo', 4, 11, 'τοτε αφιησιν αυτον ο διαβολος και ιδου αγγελοι προσηλθον και διηκονουν αυτω'),
('grc_f35', 'Mateo 4:12', 'Mateo', 4, 12, 'ακουσας δε ο ιησους οτι ιωαννης παρεδοθη ανεχωρησεν εις την γαλιλαιαν'),
('grc_f35', 'Mateo 4:13', 'Mateo', 4, 13, 'και καταλιπων την ναζαρετ ελθων κατωκησεν εις καπερναουμ την παραθαλασσιαν εν οριοις ζαβουλων και νεφθαλειμ'),
('grc_f35', 'Mateo 4:14', 'Mateo', 4, 14, 'ινα πληρωθη το ρηθεν δια ησαιου του προφητου λεγοντος'),
('grc_f35', 'Mateo 4:15', 'Mateo', 4, 15, 'γη ζαβουλων και γη νεφθαλειμ οδον θαλασσης περαν του ιορδανου γαλιλαια των εθνων'),
('grc_f35', 'Mateo 4:16', 'Mateo', 4, 16, 'ο λαος ο καθημενος εν σκοτει ειδεν φως μεγα και τοις καθημενοις εν χωρα και σκια θανατου φως ανετειλεν αυτοις'),
('grc_f35', 'Mateo 4:17', 'Mateo', 4, 17, 'απο τοτε ηρξατο ο ιησους κηρυσσειν και λεγειν μετανοειτε ηγγικεν γαρ η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 4:18', 'Mateo', 4, 18, 'περιπατων δε παρα την θαλασσαν της γαλιλαιας ειδεν δυο αδελφους σιμωνα τον λεγομενον πετρον και ανδρεαν τον αδελφον αυτου βαλλοντας αμφιβληστρον εις την θαλασσαν ησαν γαρ αλιεις'),
('grc_f35', 'Mateo 4:19', 'Mateo', 4, 19, 'και λεγει αυτοις δευτε οπισω μου και ποιησω υμας αλιεις ανθρωπων'),
('grc_f35', 'Mateo 4:20', 'Mateo', 4, 20, 'οι δε ευθεως αφεντες τα δικτυα ηκολουθησαν αυτω'),
('grc_f35', 'Mateo 4:21', 'Mateo', 4, 21, 'και προβας εκειθεν ειδεν αλλους δυο αδελφους ιακωβον τον του ζεβεδαιου και ιωαννην τον αδελφον αυτου εν τω πλοιω μετα ζεβεδαιου του πατρος αυτων καταρτιζοντας τα δικτυα αυτων και εκαλεσεν αυτους'),
('grc_f35', 'Mateo 4:22', 'Mateo', 4, 22, 'οι δε ευθεως αφεντες το πλοιον και τον πατερα αυτων ηκολουθησαν αυτω'),
('grc_f35', 'Mateo 4:23', 'Mateo', 4, 23, 'και περιηγεν ολην την γαλιλαιαν ο ιησους διδασκων εν ταις συναγωγαις αυτων και κηρυσσων το ευαγγελιον της βασιλειας και θεραπευων πασαν νοσον και πασαν μαλακιαν εν τω λαω'),
('grc_f35', 'Mateo 4:24', 'Mateo', 4, 24, 'και απηλθεν η ακοη αυτου εις ολην την συριαν και προσηνεγκαν αυτω παντας τους κακως εχοντας ποικιλαις νοσοις και βασανοις συνεχομενους και δαιμονιζομενους και σεληνιαζομενους και παραλυτικους και εθεραπευσεν αυτους'),
('grc_f35', 'Mateo 4:25', 'Mateo', 4, 25, 'και ηκολουθησαν αυτω οχλοι πολλοι απο της γαλιλαιας και δεκαπολεως και ιεροσολυμων και ιουδαιας και περαν του ιορδανου'),
('grc_f35', 'Mateo 5:1', 'Mateo', 5, 1, 'ιδων δε τους οχλους ανεβη εις το ορος και καθισαντος αυτου προσηλθον αυτω οι μαθηται αυτου'),
('grc_f35', 'Mateo 5:2', 'Mateo', 5, 2, 'και ανοιξας το στομα αυτου εδιδασκεν αυτους λεγων'),
('grc_f35', 'Mateo 5:3', 'Mateo', 5, 3, 'μακαριοι οι πτωχοι τω πνευματι οτι αυτων εστιν η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 5:4', 'Mateo', 5, 4, 'μακαριοι οι πενθουντες οτι αυτοι παρακληθησονται'),
('grc_f35', 'Mateo 5:5', 'Mateo', 5, 5, 'μακαριοι οι πραεις οτι αυτοι κληρονομησουσιν την γην'),
('grc_f35', 'Mateo 5:6', 'Mateo', 5, 6, 'μακαριοι οι πεινωντες και διψωντες την δικαιοσυνην οτι αυτοι χορτασθησονται'),
('grc_f35', 'Mateo 5:7', 'Mateo', 5, 7, 'μακαριοι οι ελεημονες οτι αυτοι ελεηθησονται'),
('grc_f35', 'Mateo 5:8', 'Mateo', 5, 8, 'μακαριοι οι καθαροι τη καρδια οτι αυτοι τον θεον οψονται'),
('grc_f35', 'Mateo 5:9', 'Mateo', 5, 9, 'μακαριοι οι ειρηνοποιοι οτι αυτοι υιοι θεου κληθησονται'),
('grc_f35', 'Mateo 5:10', 'Mateo', 5, 10, 'μακαριοι οι δεδιωγμενοι ενεκεν δικαιοσυνης οτι αυτων εστιν η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 5:11', 'Mateo', 5, 11, 'μακαριοι εστε οταν ονειδισωσιν υμας και διωξωσιν και ειπωσιν παν πονηρον ρημα καθ υμων ψευδομενοι ενεκεν εμου'),
('grc_f35', 'Mateo 5:12', 'Mateo', 5, 12, 'χαιρετε και αγαλλιασθε οτι ο μισθος υμων πολυς εν τοις ουρανοις ουτως γαρ εδιωξαν τους προφητας τους προ υμων'),
('grc_f35', 'Mateo 5:13', 'Mateo', 5, 13, 'υμεις εστε το αλας της γης εαν δε το αλας μωρανθη εν τινι αλισθησεται εις ουδεν ισχυει ετι ει μη βληθηναι εξω και καταπατεισθαι υπο των ανθρωπων'),
('grc_f35', 'Mateo 5:14', 'Mateo', 5, 14, 'υμεις εστε το φως του κοσμου ου δυναται πολις κρυβηναι επανω ορους κειμενη'),
('grc_f35', 'Mateo 5:15', 'Mateo', 5, 15, 'ουδε καιουσιν λυχνον και τιθεασιν αυτον υπο τον μοδιον αλλ επι την λυχνιαν και λαμπει πασιν τοις εν τη οικια'),
('grc_f35', 'Mateo 5:16', 'Mateo', 5, 16, 'ουτως λαμψατω το φως υμων εμπροσθεν των ανθρωπων οπως ιδωσιν υμων τα καλα εργα και δοξασωσιν τον πατερα υμων τον εν τοις ουρανοις'),
('grc_f35', 'Mateo 5:17', 'Mateo', 5, 17, 'μη νομισητε οτι ηλθον καταλυσαι τον νομον η τους προφητας ουκ ηλθον καταλυσαι αλλα πληρωσαι'),
('grc_f35', 'Mateo 5:18', 'Mateo', 5, 18, 'αμην γαρ λεγω υμιν εως αν παρελθη ο ουρανος και η γη ιωτα εν η μια κεραια ου μη παρελθη απο του νομου εως αν παντα γενηται'),
('grc_f35', 'Mateo 5:19', 'Mateo', 5, 19, 'ος εαν ουν λυση μιαν των εντολων τουτων των ελαχιστων και διδαξη ουτως τους ανθρωπους ελαχιστος κληθησεται εν τη βασιλεια των ουρανων ος δ αν ποιηση και διδαξη ουτος μεγας κληθησεται εν τη βασιλεια των ουρανων'),
('grc_f35', 'Mateo 5:20', 'Mateo', 5, 20, 'λεγω γαρ υμιν οτι εαν μη περισσευση η δικαιοσυνη υμων πλειον των γραμματεων και φαρισαιων ου μη εισελθητε εις την βασιλειαν των ουρανων'),
('grc_f35', 'Mateo 5:21', 'Mateo', 5, 21, 'ηκουσατε οτι ερρεθη τοις αρχαιοις ου φονευσεις ος δ αν φονευση ενοχος εσται τη κρισει'),
('grc_f35', 'Mateo 5:22', 'Mateo', 5, 22, 'εγω δε λεγω υμιν οτι πας ο οργιζομενος τω αδελφω αυτου εικη ενοχος εσται τη κρισει ος δ αν ειπη τω αδελφω αυτου ρακα ενοχος εσται τω συνεδριω ος δ αν ειπη μωρε ενοχος εσται εις την γεενναν του πυρος'),
('grc_f35', 'Mateo 5:23', 'Mateo', 5, 23, 'εαν ουν προσφερης το δωρον σου επι το θυσιαστηριον και εκει μνησθης οτι ο αδελφος σου εχει τι κατα σου'),
('grc_f35', 'Mateo 5:24', 'Mateo', 5, 24, 'αφες εκει το δωρον σου εμπροσθεν του θυσιαστηριου και υπαγε πρωτον διαλλαγηθι τω αδελφω σου και τοτε ελθων προσφερε το δωρον σου'),
('grc_f35', 'Mateo 5:25', 'Mateo', 5, 25, 'ισθι ευνοων τω αντιδικω σου ταχυ εως οτου ει εν τη οδω μετ αυτου μηποτε σε παραδω ο αντιδικος τω κριτη και ο κριτης σε παραδω τω υπηρετη και εις φυλακην βληθηση'),
('grc_f35', 'Mateo 5:26', 'Mateo', 5, 26, 'αμην λεγω σοι ου μη εξελθης εκειθεν εως αν αποδως τον εσχατον κοδραντην'),
('grc_f35', 'Mateo 5:27', 'Mateo', 5, 27, 'ηκουσατε οτι ερρεθη ου μοιχευσεις'),
('grc_f35', 'Mateo 5:28', 'Mateo', 5, 28, 'εγω δε λεγω υμιν οτι πας ο βλεπων γυναικα προς το επιθυμησαι αυτην ηδη εμοιχευσεν αυτην εν τη καρδια αυτου'),
('grc_f35', 'Mateo 5:29', 'Mateo', 5, 29, 'ει δε ο οφθαλμος σου ο δεξιος σκανδαλιζει σε εξελε αυτον και βαλε απο σου συμφερει γαρ σοι ινα αποληται εν των μελων σου και μη ολον το σωμα σου βληθη εις γεενναν'),
('grc_f35', 'Mateo 5:30', 'Mateo', 5, 30, 'και ει η δεξια σου χειρ σκανδαλιζει σε εκκοψον αυτην και βαλε απο σου συμφερει γαρ σοι ινα αποληται εν των μελων σου και μη ολον το σωμα σου βληθη εις γεενναν'),
('grc_f35', 'Mateo 5:31', 'Mateo', 5, 31, 'ερρεθη οτι ος αν απολυση την γυναικα αυτου δοτω αυτη αποστασιον'),
('grc_f35', 'Mateo 5:32', 'Mateo', 5, 32, 'εγω δε λεγω υμιν οτι ος αν απολυση την γυναικα αυτου παρεκτος λογου πορνειας ποιει αυτην μοιχασθαι και ος εαν απολελυμενην γαμηση μοιχαται'),
('grc_f35', 'Mateo 5:33', 'Mateo', 5, 33, 'παλιν ηκουσατε οτι ερρεθη τοις αρχαιοις ουκ επιορκησεις αποδωσεις δε τω κυριω τους ορκους σου'),
('grc_f35', 'Mateo 5:34', 'Mateo', 5, 34, 'εγω δε λεγω υμιν μη ομοσαι ολως μητε εν τω ουρανω οτι θρονος εστιν του θεου'),
('grc_f35', 'Mateo 5:35', 'Mateo', 5, 35, 'μητε εν τη γη οτι υποποδιον εστιν των ποδων αυτου μητε εις ιεροσολυμα οτι πολις εστιν του μεγαλου βασιλεως'),
('grc_f35', 'Mateo 5:36', 'Mateo', 5, 36, 'μητε εν τη κεφαλη σου ομοσης οτι ου δυνασαι μιαν τριχα λευκην η μελαιναν ποιησαι'),
('grc_f35', 'Mateo 5:37', 'Mateo', 5, 37, 'εστω δε ο λογος υμων ναι ναι ου ου το δε περισσον τουτων εκ του πονηρου εστιν'),
('grc_f35', 'Mateo 5:38', 'Mateo', 5, 38, 'ηκουσατε οτι ερρεθη οφθαλμον αντι οφθαλμου και οδοντα αντι οδοντος'),
('grc_f35', 'Mateo 5:39', 'Mateo', 5, 39, 'εγω δε λεγω υμιν μη αντιστηναι τω πονηρω αλλ οστις σε ραπισει επι την δεξιαν σιαγονα στρεψον αυτω και την αλλην'),
('grc_f35', 'Mateo 5:40', 'Mateo', 5, 40, 'και τω θελοντι σοι κριθηναι και τον χιτωνα σου λαβειν αφες αυτω και το ιματιον'),
('grc_f35', 'Mateo 5:41', 'Mateo', 5, 41, 'και οστις σε αγγαρευσει μιλιον εν υπαγε μετ αυτου δυο'),
('grc_f35', 'Mateo 5:42', 'Mateo', 5, 42, 'τω αιτουντι σε διδου και τον θελοντα απο σου δανεισασθαι μη αποστραφης'),
('grc_f35', 'Mateo 5:43', 'Mateo', 5, 43, 'ηκουσατε οτι ερρεθη αγαπησεις τον πλησιον σου και μισησεις τον εχθρον σου'),
('grc_f35', 'Mateo 5:44', 'Mateo', 5, 44, 'εγω δε λεγω υμιν αγαπατε τους εχθρους υμων ευλογειτε τους καταρωμενους υμας καλως ποιειτε τοις μισουσιν υμας και προσευχεσθε υπερ των επηρεαζοντων υμας και διωκοντων υμας'),
('grc_f35', 'Mateo 5:45', 'Mateo', 5, 45, 'οπως γενησθε υιοι του πατρος υμων του εν τοις ουρανοις οτι τον ηλιον αυτου ανατελλει επι πονηρους και αγαθους και βρεχει επι δικαιους και αδικους'),
('grc_f35', 'Mateo 5:46', 'Mateo', 5, 46, 'εαν γαρ αγαπησητε τους αγαπωντας υμας τινα μισθον εχετε ουχι και οι τελωναι το αυτο ποιουσιν'),
('grc_f35', 'Mateo 5:47', 'Mateo', 5, 47, 'και εαν ασπασησθε τους φιλους υμων μονον τι περισσον ποιειτε ουχι και οι τελωναι ουτως ποιουσιν'),
('grc_f35', 'Mateo 5:48', 'Mateo', 5, 48, 'εσεσθε ουν υμεις τελειοι ωσπερ ο πατηρ υμων ο εν τοις ουρανοις τελειος εστιν'),
('grc_f35', 'Mateo 6:1', 'Mateo', 6, 1, 'προσεχετε την ελεημοσυνην υμων μη ποιειν εμπροσθεν των ανθρωπων προς το θεαθηναι αυτοις ει δε μη γε μισθον ουκ εχετε παρα τω πατρι υμων τω εν τοις ουρανοις'),
('grc_f35', 'Mateo 6:2', 'Mateo', 6, 2, 'οταν ουν ποιης ελεημοσυνην μη σαλπισης εμπροσθεν σου ωσπερ οι υποκριται ποιουσιν εν ταις συναγωγαις και εν ταις ρυμαις οπως δοξασθωσιν υπο των ανθρωπων αμην λεγω υμιν απεχουσιν τον μισθον αυτων'),
('grc_f35', 'Mateo 6:3', 'Mateo', 6, 3, 'σου δε ποιουντος ελεημοσυνην μη γνωτω η αριστερα σου τι ποιει η δεξια σου'),
('grc_f35', 'Mateo 6:4', 'Mateo', 6, 4, 'οπως η σου η ελεημοσυνη εν τω κρυπτω και ο πατηρ σου ο βλεπων εν τω κρυπτω αυτος αποδωσει σοι εν τω φανερω'),
('grc_f35', 'Mateo 6:5', 'Mateo', 6, 5, 'και οταν προσευχη ουκ εση ωσπερ οι υποκριται οτι φιλουσιν εν ταις συναγωγαις και εν ταις γωνιαις των πλατειων εστωτες προσευχεσθαι οπως αν φανωσιν τοις ανθρωποις αμην λεγω υμιν οτι απεχουσιν τον μισθον αυτων'),
('grc_f35', 'Mateo 6:6', 'Mateo', 6, 6, 'συ δε οταν προσευχη εισελθε εις το ταμειον σου και κλεισας την θυραν σου προσευξαι τω πατρι σου τω εν τω κρυπτω και ο πατηρ σου ο βλεπων εν τω κρυπτω αποδωσει σοι εν τω φανερω'),
('grc_f35', 'Mateo 6:7', 'Mateo', 6, 7, 'προσευχομενοι δε μη βαττολογησητε ωσπερ οι εθνικοι δοκουσιν γαρ οτι εν τη πολυλογια αυτων εισακουσθησονται'),
('grc_f35', 'Mateo 6:8', 'Mateo', 6, 8, 'μη ουν ομοιωθητε αυτοις οιδεν γαρ ο πατηρ υμων ων χρειαν εχετε προ του υμας αιτησαι αυτον'),
('grc_f35', 'Mateo 6:9', 'Mateo', 6, 9, 'ουτως ουν προσευχεσθε υμεις πατερ ημων ο εν τοις ουρανοις αγιασθητω το ονομα σου'),
('grc_f35', 'Mateo 6:10', 'Mateo', 6, 10, 'ελθετω η βασιλεια σου γενηθητω το θελημα σου ως εν ουρανω και επι της γης'),
('grc_f35', 'Mateo 6:11', 'Mateo', 6, 11, 'τον αρτον ημων τον επιουσιον δος ημιν σημερον'),
('grc_f35', 'Mateo 6:12', 'Mateo', 6, 12, 'και αφες ημιν τα οφειληματα ημων ως και ημεις αφιεμεν τοις οφειλεταις ημων'),
('grc_f35', 'Mateo 6:13', 'Mateo', 6, 13, 'και μη εισενεγκης ημας εις πειρασμον αλλα ρυσαι ημας απο του πονηρου οτι σου εστιν η βασιλεια και η δυναμις και η δοξα εις τους αιωνας αμην'),
('grc_f35', 'Mateo 6:14', 'Mateo', 6, 14, 'εαν γαρ αφητε τοις ανθρωποις τα παραπτωματα αυτων αφησει και υμιν ο πατηρ υμων ο ουρανιος'),
('grc_f35', 'Mateo 6:15', 'Mateo', 6, 15, 'εαν δε μη αφητε τοις ανθρωποις τα παραπτωματα αυτων ουδε ο πατηρ υμων αφησει τα παραπτωματα υμων'),
('grc_f35', 'Mateo 6:16', 'Mateo', 6, 16, 'οταν δε νηστευητε μη γινεσθε ωσπερ οι υποκριται σκυθρωποι αφανιζουσιν γαρ τα προσωπα αυτων οπως φανωσιν τοις ανθρωποις νηστευοντες αμην λεγω υμιν οτι απεχουσιν τον μισθον αυτων'),
('grc_f35', 'Mateo 6:17', 'Mateo', 6, 17, 'συ δε νηστευων αλειψαι σου την κεφαλην και το προσωπον σου νιψαι'),
('grc_f35', 'Mateo 6:18', 'Mateo', 6, 18, 'οπως μη φανης τοις ανθρωποις νηστευων αλλα τω πατρι σου τω εν τω κρυπτω και ο πατηρ σου ο βλεπων εν τω κρυπτω αποδωσει σοι'),
('grc_f35', 'Mateo 6:19', 'Mateo', 6, 19, 'μη θησαυριζετε υμιν θησαυρους επι της γης οπου σης και βρωσις αφανιζει και οπου κλεπται διορυσσουσιν και κλεπτουσιν'),
('grc_f35', 'Mateo 6:20', 'Mateo', 6, 20, 'θησαυριζετε δε υμιν θησαυρους εν ουρανω οπου ουτε σης ουτε βρωσις αφανιζει και οπου κλεπται ου διορυσσουσιν ουδε κλεπτουσιν'),
('grc_f35', 'Mateo 6:21', 'Mateo', 6, 21, 'οπου γαρ εστιν ο θησαυρος υμων εκει εσται και η καρδια υμων'),
('grc_f35', 'Mateo 6:22', 'Mateo', 6, 22, 'ο λυχνος του σωματος εστιν ο οφθαλμος εαν ουν ο οφθαλμος σου απλους η ολον το σωμα σου φωτεινον εσται'),
('grc_f35', 'Mateo 6:23', 'Mateo', 6, 23, 'εαν δε ο οφθαλμος σου πονηρος η ολον το σωμα σου σκοτεινον εσται ει ουν το φως το εν σοι σκοτος εστιν το σκοτος ποσον'),
('grc_f35', 'Mateo 6:24', 'Mateo', 6, 24, 'ουδεις δυναται δυσιν κυριοις δουλευειν η γαρ τον ενα μισησει και τον ετερον αγαπησει η ενος ανθεξεται και του ετερου καταφρονησει ου δυνασθε θεω δουλευειν και μαμωνα'),
('grc_f35', 'Mateo 6:25', 'Mateo', 6, 25, 'δια τουτο λεγω υμιν μη μεριμνατε τη ψυχη υμων τι φαγητε και τι πιητε μηδε τω σωματι υμων τι ενδυσεσθε ουχι η ψυχη πλειων εστιν της τροφης και το σωμα του ενδυματος'),
('grc_f35', 'Mateo 6:26', 'Mateo', 6, 26, 'εμβλεψατε εις τα πετεινα του ουρανου οτι ου σπειρουσιν ουδε θεριζουσιν ουδε συναγουσιν εις αποθηκας και ο πατηρ υμων ο ουρανιος τρεφει αυτα ουχ υμεις μαλλον διαφερετε αυτων'),
('grc_f35', 'Mateo 6:27', 'Mateo', 6, 27, 'τις δε εξ υμων μεριμνων δυναται προσθειναι επι την ηλικιαν αυτου πηχυν ενα'),
('grc_f35', 'Mateo 6:28', 'Mateo', 6, 28, 'και περι ενδυματος τι μεριμνατε καταμαθετε τα κρινα του αγρου πως αυξανει ου κοπια ουδε νηθει'),
('grc_f35', 'Mateo 6:29', 'Mateo', 6, 29, 'λεγω δε υμιν οτι ουδε σολομων εν παση τη δοξη αυτου περιεβαλετο ως εν τουτων'),
('grc_f35', 'Mateo 6:30', 'Mateo', 6, 30, 'ει δε τον χορτον του αγρου σημερον οντα και αυριον εις κλιβανον βαλλομενον ο θεος ουτως αμφιεννυσιν ου πολλω μαλλον υμας ολιγοπιστοι'),
('grc_f35', 'Mateo 6:31', 'Mateo', 6, 31, 'μη ουν μεριμνησητε λεγοντες τι φαγωμεν η τι πιωμεν η τι περιβαλωμεθα'),
('grc_f35', 'Mateo 6:32', 'Mateo', 6, 32, 'παντα γαρ ταυτα τα εθνη επιζητει οιδεν γαρ ο πατηρ υμων ο ουρανιος οτι χρηζετε τουτων απαντων'),
('grc_f35', 'Mateo 6:33', 'Mateo', 6, 33, 'ζητειτε δε πρωτον την βασιλειαν του θεου και την δικαιοσυνην αυτου και ταυτα παντα προστεθησεται υμιν'),
('grc_f35', 'Mateo 6:34', 'Mateo', 6, 34, 'μη ουν μεριμνησητε εις την αυριον η γαρ αυριον μεριμνησει τα εαυτης αρκετον τη ημερα η κακια αυτης'),
('grc_f35', 'Mateo 7:1', 'Mateo', 7, 1, 'μη κρινετε ινα μη κριθητε'),
('grc_f35', 'Mateo 7:2', 'Mateo', 7, 2, 'εν ω γαρ κριματι κρινετε κριθησεσθε και εν ω μετρω μετρειτε μετρηθησεται υμιν'),
('grc_f35', 'Mateo 7:3', 'Mateo', 7, 3, 'τι δε βλεπεις το καρφος το εν τω οφθαλμω του αδελφου σου την δε εν τω σω οφθαλμω δοκον ου κατανοεις'),
('grc_f35', 'Mateo 7:4', 'Mateo', 7, 4, 'η πως ερεις τω αδελφω σου αφες εκβαλω το καρφος απο του οφθαλμου σου και ιδου η δοκος εν τω οφθαλμω σου'),
('grc_f35', 'Mateo 7:5', 'Mateo', 7, 5, 'υποκριτα εκβαλε πρωτον την δοκον εκ του οφθαλμου σου και τοτε διαβλεψεις εκβαλειν το καρφος εκ του οφθαλμου του αδελφου σου'),
('grc_f35', 'Mateo 7:6', 'Mateo', 7, 6, 'μη δωτε το αγιον τοις κυσιν μηδε βαλητε τους μαργαριτας υμων εμπροσθεν των χοιρων μηποτε καταπατησωσιν αυτους εν τοις ποσιν αυτων και στραφεντες ρηξωσιν υμας'),
('grc_f35', 'Mateo 7:7', 'Mateo', 7, 7, 'αιτειτε και δοθησεται υμιν ζητειτε και ευρησετε κρουετε και ανοιγησεται υμιν'),
('grc_f35', 'Mateo 7:8', 'Mateo', 7, 8, 'πας γαρ ο αιτων λαμβανει και ο ζητων ευρισκει και τω κρουοντι ανοιγησεται'),
('grc_f35', 'Mateo 7:9', 'Mateo', 7, 9, 'η τις εστιν εξ υμων ανθρωπος ον εαν αιτηση ο υιος αυτου αρτον μη λιθον επιδωσει αυτω'),
('grc_f35', 'Mateo 7:10', 'Mateo', 7, 10, 'και εαν ιχθυν αιτηση μη οφιν επιδωσει αυτω'),
('grc_f35', 'Mateo 7:11', 'Mateo', 7, 11, 'ει ουν υμεις πονηροι οντες οιδατε δοματα αγαθα διδοναι τοις τεκνοις υμων ποσω μαλλον ο πατηρ υμων ο εν τοις ουρανοις δωσει αγαθα τοις αιτουσιν αυτον'),
('grc_f35', 'Mateo 7:12', 'Mateo', 7, 12, 'παντα ουν οσα αν θελητε ινα ποιωσιν υμιν οι ανθρωποι ουτως και υμεις ποιειτε αυτοις ουτος γαρ εστιν ο νομος και οι προφηται'),
('grc_f35', 'Mateo 7:13', 'Mateo', 7, 13, 'εισελθετε δια της στενης πυλης οτι πλατεια η πυλη και ευρυχωρος η οδος η απαγουσα εις την απωλειαν και πολλοι εισιν οι εισερχομενοι δι αυτης'),
('grc_f35', 'Mateo 7:14', 'Mateo', 7, 14, 'τι στενη η πυλη και τεθλιμμενη η οδος η απαγουσα εις την ζωην και ολιγοι εισιν οι ευρισκοντες αυτην'),
('grc_f35', 'Mateo 7:15', 'Mateo', 7, 15, 'προσεχετε δε απο των ψευδοπροφητων οιτινες ερχονται προς υμας εν ενδυμασιν προβατων εσωθεν δε εισιν λυκοι αρπαγες'),
('grc_f35', 'Mateo 7:16', 'Mateo', 7, 16, 'απο των καρπων αυτων επιγνωσεσθε αυτους μητι συλλεγουσιν απο ακανθων σταφυλην η απο τριβολων συκα'),
('grc_f35', 'Mateo 7:17', 'Mateo', 7, 17, 'ουτως παν δενδρον αγαθον καρπους καλους ποιει το δε σαπρον δενδρον καρπους πονηρους ποιει'),
('grc_f35', 'Mateo 7:18', 'Mateo', 7, 18, 'ου δυναται δενδρον αγαθον καρπους πονηρους ποιειν ουδε δενδρον σαπρον καρπους καλους ποιειν'),
('grc_f35', 'Mateo 7:19', 'Mateo', 7, 19, 'παν ουν δενδρον μη ποιουν καρπον καλον εκκοπτεται και εις πυρ βαλλεται'),
('grc_f35', 'Mateo 7:20', 'Mateo', 7, 20, 'αρα γε απο των καρπων αυτων επιγνωσεσθε αυτους'),
('grc_f35', 'Mateo 7:21', 'Mateo', 7, 21, 'ου πας ο λεγων μοι κυριε κυριε εισελευσεται εις την βασιλειαν των ουρανων αλλ ο ποιων το θελημα του πατρος μου του εν ουρανοις'),
('grc_f35', 'Mateo 7:22', 'Mateo', 7, 22, 'πολλοι ερουσιν μοι εν εκεινη τη ημερα κυριε κυριε ου τω σω ονοματι προεφητευσαμεν και τω σω ονοματι δαιμονια εξεβαλομεν και τω σω ονοματι δυναμεις πολλας εποιησαμεν'),
('grc_f35', 'Mateo 7:23', 'Mateo', 7, 23, 'και τοτε ομολογησω αυτοις οτι ουδεποτε εγνων υμας αποχωρειτε απ εμου οι εργαζομενοι την ανομιαν'),
('grc_f35', 'Mateo 7:24', 'Mateo', 7, 24, 'πας ουν οστις ακουει μου τους λογους τουτους και ποιει αυτους ομοιωσω αυτον ανδρι φρονιμω οστις ωκοδομησεν την οικιαν αυτου επι την πετραν'),
('grc_f35', 'Mateo 7:25', 'Mateo', 7, 25, 'και κατεβη η βροχη και ηλθον οι ποταμοι και επνευσαν οι ανεμοι και προσεπεσον τη οικια εκεινη και ουκ επεσεν τεθεμελιωτο γαρ επι την πετραν'),
('grc_f35', 'Mateo 7:26', 'Mateo', 7, 26, 'και πας ο ακουων μου τους λογους τουτους και μη ποιων αυτους ομοιωθησεται ανδρι μωρω οστις ωκοδομησεν την οικιαν αυτου επι την αμμον'),
('grc_f35', 'Mateo 7:27', 'Mateo', 7, 27, 'και κατεβη η βροχη και ηλθον οι ποταμοι και επνευσαν οι ανεμοι και προσεκοψαν τη οικια εκεινη και επεσεν και ην η πτωσις αυτης μεγαλη'),
('grc_f35', 'Mateo 7:28', 'Mateo', 7, 28, 'και εγενετο οτε συνετελεσεν ο ιησους τους λογους τουτους εξεπλησσοντο οι οχλοι επι τη διδαχη αυτου'),
('grc_f35', 'Mateo 7:29', 'Mateo', 7, 29, 'ην γαρ διδασκων αυτους ως εξουσιαν εχων και ουχ ως οι γραμματεις'),
('grc_f35', 'Mateo 8:1', 'Mateo', 8, 1, 'καταβαντι δε αυτω απο του ορους ηκολουθησαν αυτω οχλοι πολλοι'),
('grc_f35', 'Mateo 8:2', 'Mateo', 8, 2, 'και ιδου λεπρος ελθων προσεκυνει αυτω λεγων κυριε εαν θελης δυνασαι με καθαρισαι'),
('grc_f35', 'Mateo 8:3', 'Mateo', 8, 3, 'και εκτεινας την χειρα ηψατο αυτου ο ιησους λεγων θελω καθαρισθητι και ευθεως εκαθαρισθη αυτου η λεπρα'),
('grc_f35', 'Mateo 8:4', 'Mateo', 8, 4, 'και λεγει αυτω ο ιησους ορα μηδενι ειπης αλλ υπαγε σεαυτον δειξον τω ιερει και προσενεγκαι το δωρον ο προσεταξεν μωσης εις μαρτυριον αυτοις'),
('grc_f35', 'Mateo 8:5', 'Mateo', 8, 5, 'εισελθοντι δε αυτω εις καπερναουμ προσηλθεν αυτω εκατονταρχος παρακαλων αυτον'),
('grc_f35', 'Mateo 8:6', 'Mateo', 8, 6, 'και λεγων κυριε ο παις μου βεβληται εν τη οικια παραλυτικος δεινως βασανιζομενος'),
('grc_f35', 'Mateo 8:7', 'Mateo', 8, 7, 'και λεγει αυτω ο ιησους εγω ελθων θεραπευσω αυτον'),
('grc_f35', 'Mateo 8:8', 'Mateo', 8, 8, 'και αποκριθεις ο εκατονταρχος εφη κυριε ουκ ειμι ικανος ινα μου υπο την στεγην εισελθης αλλα μονον ειπε λογω και ιαθησεται ο παις μου'),
('grc_f35', 'Mateo 8:9', 'Mateo', 8, 9, 'και γαρ εγω ανθρωπος ειμι υπο εξουσιαν εχων υπ εμαυτον στρατιωτας και λεγω τουτω πορευθητι και πορευεται και αλλω ερχου και ερχεται και τω δουλω μου ποιησον τουτο και ποιει'),
('grc_f35', 'Mateo 8:10', 'Mateo', 8, 10, 'ακουσας δε ο ιησους εθαυμασεν και ειπεν τοις ακολουθουσιν αμην λεγω υμιν ουδε εν τω ισραηλ τοσαυτην πιστιν ευρον'),
('grc_f35', 'Mateo 8:11', 'Mateo', 8, 11, 'λεγω δε υμιν οτι πολλοι απο ανατολων και δυσμων ηξουσιν και ανακλιθησονται μετα αβρααμ και ισαακ και ιακωβ εν τη βασιλεια των ουρανων'),
('grc_f35', 'Mateo 8:12', 'Mateo', 8, 12, 'οι δε υιοι της βασιλειας εκβληθησονται εις το σκοτος το εξωτερον εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 8:13', 'Mateo', 8, 13, 'και ειπεν ο ιησους τω εκατονταρχω υπαγε και ως επιστευσας γενηθητω σοι και ιαθη ο παις αυτου εν τη ωρα εκεινη'),
('grc_f35', 'Mateo 8:14', 'Mateo', 8, 14, 'και ελθων ο ιησους εις την οικιαν πετρου ειδεν την πενθεραν αυτου βεβλημενην και πυρεσσουσαν'),
('grc_f35', 'Mateo 8:15', 'Mateo', 8, 15, 'και ηψατο της χειρος αυτης και αφηκεν αυτην ο πυρετος και ηγερθη και διηκονει αυτω'),
('grc_f35', 'Mateo 8:16', 'Mateo', 8, 16, 'οψιας δε γενομενης προσηνεγκαν αυτω δαιμονιζομενους πολλους και εξεβαλεν τα πνευματα λογω και παντας τους κακως εχοντας εθεραπευσεν'),
('grc_f35', 'Mateo 8:17', 'Mateo', 8, 17, 'οπως πληρωθη το ρηθεν δια ησαιου του προφητου λεγοντος αυτος τας ασθενειας ημων ελαβεν και τας νοσους εβαστασεν'),
('grc_f35', 'Mateo 8:18', 'Mateo', 8, 18, 'ιδων δε ο ιησους πολλους οχλους περι αυτον εκελευσεν απελθειν εις το περαν'),
('grc_f35', 'Mateo 8:19', 'Mateo', 8, 19, 'και προσελθων εις γραμματευς ειπεν αυτω διδασκαλε ακολουθησω σοι οπου εαν απερχη'),
('grc_f35', 'Mateo 8:20', 'Mateo', 8, 20, 'λεγει αυτω ο ιησους αι αλωπεκες φωλεους εχουσιν και τα πετεινα του ουρανου κατασκηνωσεις ο δε υιος του ανθρωπου ουκ εχει που την κεφαλην κλινη'),
('grc_f35', 'Mateo 8:21', 'Mateo', 8, 21, 'ετερος δε των μαθητων ειπεν αυτω κυριε επιτρεψον μοι πρωτον απελθειν και θαψαι τον πατερα μου'),
('grc_f35', 'Mateo 8:22', 'Mateo', 8, 22, 'ο δε ιησους ειπεν αυτω ακολουθει μοι και αφες τους νεκρους θαψαι τους εαυτων νεκρους'),
('grc_f35', 'Mateo 8:23', 'Mateo', 8, 23, 'και εμβαντι αυτω εις το πλοιον ηκολουθησαν αυτω οι μαθηται αυτου'),
('grc_f35', 'Mateo 8:24', 'Mateo', 8, 24, 'και ιδου σεισμος μεγας εγενετο εν τη θαλασση ωστε το πλοιον καλυπτεσθαι υπο των κυματων αυτος δε εκαθευδεν'),
('grc_f35', 'Mateo 8:25', 'Mateo', 8, 25, 'και προσελθοντες οι μαθηται ηγειραν αυτον λεγοντες κυριε σωσον ημας απολλυμεθα'),
('grc_f35', 'Mateo 8:26', 'Mateo', 8, 26, 'και λεγει αυτοις τι δειλοι εστε ολιγοπιστοι τοτε εγερθεις επετιμησεν τοις ανεμοις και τη θαλασση και εγενετο γαληνη μεγαλη'),
('grc_f35', 'Mateo 8:27', 'Mateo', 8, 27, 'οι δε ανθρωποι εθαυμασαν λεγοντες ποταπος εστιν ουτος οτι και οι ανεμοι και η θαλασσα υπακουουσιν αυτω'),
('grc_f35', 'Mateo 8:28', 'Mateo', 8, 28, 'και ελθοντι αυτω εις το περαν εις την χωραν των γεργεσηνων υπηντησαν αυτω δυο δαιμονιζομενοι εκ των μνημειων εξερχομενοι χαλεποι λιαν ωστε μη ισχυειν τινα παρελθειν δια της οδου εκεινης'),
('grc_f35', 'Mateo 8:29', 'Mateo', 8, 29, 'και ιδου εκραξαν λεγοντες τι ημιν και σοι ιησου υιε του θεου ηλθες ωδε προ καιρου βασανισαι ημας'),
('grc_f35', 'Mateo 8:30', 'Mateo', 8, 30, 'ην δε μακραν απ αυτων αγελη χοιρων πολλων βοσκομενη'),
('grc_f35', 'Mateo 8:31', 'Mateo', 8, 31, 'οι δε δαιμονες παρεκαλουν αυτον λεγοντες ει εκβαλλεις ημας επιτρεψον ημιν απελθειν εις την αγελην των χοιρων'),
('grc_f35', 'Mateo 8:32', 'Mateo', 8, 32, 'και ειπεν αυτοις υπαγετε οι δε εξελθοντες απηλθον εις την αγελην των χοιρων και ιδου ωρμησεν πασα η αγελη των χοιρων κατα του κρημνου εις την θαλασσαν και απεθανον εν τοις υδασιν'),
('grc_f35', 'Mateo 8:33', 'Mateo', 8, 33, 'οι δε βοσκοντες εφυγον και απελθοντες εις την πολιν απηγγειλαν παντα και τα των δαιμονιζομενων'),
('grc_f35', 'Mateo 8:34', 'Mateo', 8, 34, 'και ιδου πασα η πολις εξηλθεν εις συναντησιν τω ιησου και ιδοντες αυτον παρεκαλεσαν οπως μεταβη απο των οριων αυτων'),
('grc_f35', 'Mateo 9:1', 'Mateo', 9, 1, 'και εμβας εις το πλοιον διεπερασεν και ηλθεν εις την ιδιαν πολιν'),
('grc_f35', 'Mateo 9:2', 'Mateo', 9, 2, 'και ιδου προσεφερον αυτω παραλυτικον επι κλινης βεβλημενον και ιδων ο ιησους την πιστιν αυτων ειπεν τω παραλυτικω θαρσει τεκνον αφεωνται σοι αι αμαρτιαι σου'),
('grc_f35', 'Mateo 9:3', 'Mateo', 9, 3, 'και ιδου τινες των γραμματεων ειπον εν εαυτοις ουτος βλασφημει'),
('grc_f35', 'Mateo 9:4', 'Mateo', 9, 4, 'και ειδως ο ιησους τας ενθυμησεις αυτων ειπεν ινατι υμεις ενθυμεισθε πονηρα εν ταις καρδιαις υμων'),
('grc_f35', 'Mateo 9:5', 'Mateo', 9, 5, 'τι γαρ εστιν ευκοπωτερον ειπειν αφεωνται σου αι αμαρτιαι η ειπειν εγειραι και περιπατει'),
('grc_f35', 'Mateo 9:6', 'Mateo', 9, 6, 'ινα δε ειδητε οτι εξουσιαν εχει ο υιος του ανθρωπου επι της γης αφιεναι αμαρτιας τοτε λεγει τω παραλυτικω εγερθεις αρον σου την κλινην και υπαγε εις τον οικον σου'),
('grc_f35', 'Mateo 9:7', 'Mateo', 9, 7, 'και εγερθεις απηλθεν εις τον οικον αυτου'),
('grc_f35', 'Mateo 9:8', 'Mateo', 9, 8, 'ιδοντες δε οι οχλοι εθαυμασαν και εδοξασαν τον θεον τον δοντα εξουσιαν τοιαυτην τοις ανθρωποις'),
('grc_f35', 'Mateo 9:9', 'Mateo', 9, 9, 'και παραγων ο ιησους εκειθεν ειδεν ανθρωπον καθημενον επι το τελωνιον ματθαιον λεγομενον και λεγει αυτω ακολουθει μοι και αναστας ηκολουθησεν αυτω'),
('grc_f35', 'Mateo 9:10', 'Mateo', 9, 10, 'και εγενετο αυτου ανακειμενου εν τη οικια και ιδου πολλοι τελωναι και αμαρτωλοι ελθοντες συνανεκειντο τω ιησου και τοις μαθηταις αυτου'),
('grc_f35', 'Mateo 9:11', 'Mateo', 9, 11, 'και ιδοντες οι φαρισαιοι ειπον τοις μαθηταις αυτου δια τι μετα των τελωνων και αμαρτωλων εσθιει και πινει ο διδασκαλος υμων'),
('grc_f35', 'Mateo 9:12', 'Mateo', 9, 12, 'ο δε ιησους ακουσας ειπεν αυτοις ου χρειαν εχουσιν οι ισχυοντες ιατρου αλλ οι κακως εχοντες'),
('grc_f35', 'Mateo 9:13', 'Mateo', 9, 13, 'πορευθεντες δε μαθετε τι εστιν ελεον θελω και ου θυσιαν ου γαρ ηλθον καλεσαι δικαιους αλλα αμαρτωλους εις μετανοιαν'),
('grc_f35', 'Mateo 9:14', 'Mateo', 9, 14, 'τοτε προσερχονται αυτω οι μαθηται ιωαννου λεγοντες δια τι ημεις και οι φαρισαιοι νηστευομεν πολλα οι δε μαθηται σου ου νηστευουσιν'),
('grc_f35', 'Mateo 9:15', 'Mateo', 9, 15, 'και ειπεν αυτοις ο ιησους μη δυνανται οι υιοι του νυμφωνος πενθειν εφ οσον χρονον μετ αυτων εστιν ο νυμφιος ελευσονται δε ημεραι οταν απαρθη απ αυτων ο νυμφιος και τοτε νηστευσουσιν'),
('grc_f35', 'Mateo 9:16', 'Mateo', 9, 16, 'ουδεις δε επιβαλλει επιβλημα ρακους αγναφου επι ιματιω παλαιω αιρει γαρ το πληρωμα αυτου απο του ιματιου και χειρον σχισμα γινεται'),
('grc_f35', 'Mateo 9:17', 'Mateo', 9, 17, 'ουδε βαλλουσιν οινον νεον εις ασκους παλαιους ει δε μη γε ρηγνυνται οι ασκοι και ο οινος εκχειται και οι ασκοι απολουνται αλλα βαλλουσιν οινον νεον εις ασκους καινους και αμφοτεροι συντηρουνται'),
('grc_f35', 'Mateo 9:18', 'Mateo', 9, 18, 'ταυτα αυτου λαλουντος αυτοις ιδου αρχων τις ελθων προσεκυνει αυτω λεγων οτι η θυγατηρ μου αρτι ετελευτησεν αλλα ελθων επιθες την χειρα σου επ αυτην και ζησεται'),
('grc_f35', 'Mateo 9:19', 'Mateo', 9, 19, 'και εγερθεις ο ιησους ηκολουθησεν αυτω και οι μαθηται αυτου'),
('grc_f35', 'Mateo 9:20', 'Mateo', 9, 20, 'και ιδου γυνη αιμορροουσα δωδεκα ετη προσελθουσα οπισθεν ηψατο του κρασπεδου του ιματιου αυτου'),
('grc_f35', 'Mateo 9:21', 'Mateo', 9, 21, 'ελεγεν γαρ εν εαυτη εαν μονον αψωμαι του ιματιου αυτου σωθησομαι'),
('grc_f35', 'Mateo 9:22', 'Mateo', 9, 22, 'ο δε ιησους επιστραφεις και ιδων αυτην ειπεν θαρσει θυγατερ η πιστις σου σεσωκεν σε και εσωθη η γυνη απο της ωρας εκεινης'),
('grc_f35', 'Mateo 9:23', 'Mateo', 9, 23, 'και ελθων ο ιησους εις την οικιαν του αρχοντος και ιδων τους αυλητας και τον οχλον θορυβουμενον'),
('grc_f35', 'Mateo 9:24', 'Mateo', 9, 24, 'λεγει αυτοις αναχωρειτε ου γαρ απεθανεν το κορασιον αλλα καθευδει και κατεγελων αυτου'),
('grc_f35', 'Mateo 9:25', 'Mateo', 9, 25, 'οτε δε εξεβληθη ο οχλος εισελθων εκρατησεν της χειρος αυτης και ηγερθη το κορασιον'),
('grc_f35', 'Mateo 9:26', 'Mateo', 9, 26, 'και εξηλθεν η φημη αυτη εις ολην την γην εκεινην'),
('grc_f35', 'Mateo 9:27', 'Mateo', 9, 27, 'και παραγοντι εκειθεν τω ιησου ηκολουθησαν αυτω δυο τυφλοι κραζοντες και λεγοντες ελεησον ημας υιος δαυιδ'),
('grc_f35', 'Mateo 9:28', 'Mateo', 9, 28, 'ελθοντι δε εις την οικιαν προσηλθον αυτω οι τυφλοι και λεγει αυτοις πιστευετε οτι δυναμαι τουτο ποιησαι λεγουσιν αυτω ναι κυριε'),
('grc_f35', 'Mateo 9:29', 'Mateo', 9, 29, 'τοτε ηψατο των οφθαλμων αυτων λεγων κατα την πιστιν υμων γενηθητω υμιν'),
('grc_f35', 'Mateo 9:30', 'Mateo', 9, 30, 'και ανεωχθησαν αυτων οι οφθαλμοι και ενεβριμησατο αυτοις ο ιησους λεγων ορατε μηδεις γινωσκετω'),
('grc_f35', 'Mateo 9:31', 'Mateo', 9, 31, 'οι δε εξελθοντες διεφημισαν αυτον εν ολη τη γη εκεινη'),
('grc_f35', 'Mateo 9:32', 'Mateo', 9, 32, 'αυτων δε εξερχομενων ιδου προσηνεγκαν αυτω ανθρωπον κωφον δαιμονιζομενον'),
('grc_f35', 'Mateo 9:33', 'Mateo', 9, 33, 'και εκβληθεντος του δαιμονιου ελαλησεν ο κωφος και εθαυμασαν οι οχλοι λεγοντες οτι ουδεποτε εφανη ουτως εν τω ισραηλ'),
('grc_f35', 'Mateo 9:34', 'Mateo', 9, 34, 'οι δε φαρισαιοι ελεγον εν τω αρχοντι των δαιμονιων εκβαλλει τα δαιμονια'),
('grc_f35', 'Mateo 9:35', 'Mateo', 9, 35, 'και περιηγεν ο ιησους τας πολεις πασας και τας κωμας διδασκων εν ταις συναγωγαις αυτων και κηρυσσων το ευαγγελιον της βασιλειας και θεραπευων πασαν νοσον και πασαν μαλακιαν εν τω λαω'),
('grc_f35', 'Mateo 9:36', 'Mateo', 9, 36, 'ιδων δε τους οχλους εσπλαγχνισθη περι αυτων οτι ησαν εσκυλμενοι και ερριμμενοι ως προβατα μη εχοντα ποιμενα'),
('grc_f35', 'Mateo 9:37', 'Mateo', 9, 37, 'τοτε λεγει τοις μαθηταις αυτου ο μεν θερισμος πολυς οι δε εργαται ολιγοι'),
('grc_f35', 'Mateo 9:38', 'Mateo', 9, 38, 'δεηθητε ουν του κυριου του θερισμου οπως εκβαλη εργατας εις τον θερισμον αυτου'),
('grc_f35', 'Mateo 10:1', 'Mateo', 10, 1, 'και προσκαλεσαμενος τους δωδεκα μαθητας αυτου εδωκεν αυτοις εξουσιαν πνευματων ακαθαρτων ωστε εκβαλλειν αυτα και θεραπευειν πασαν νοσον και πασαν μαλακιαν'),
('grc_f35', 'Mateo 10:2', 'Mateo', 10, 2, 'των δε δωδεκα αποστολων τα ονοματα εισιν ταυτα πρωτος σιμων ο λεγομενος πετρος και ανδρεας ο αδελφος αυτου ιακωβος ο του ζεβεδαιου και ιωαννης ο αδελφος αυτου'),
('grc_f35', 'Mateo 10:3', 'Mateo', 10, 3, 'φιλιππος και βαρθολομαιος θωμας και ματθαιος ο τελωνης ιακωβος ο του αλφαιου και λεββαιος ο επικληθεις θαδδαιος'),
('grc_f35', 'Mateo 10:4', 'Mateo', 10, 4, 'σιμων ο κανανιτης και ιουδας ισκαριωτης ο και παραδους αυτον'),
('grc_f35', 'Mateo 10:5', 'Mateo', 10, 5, 'τουτους τους δωδεκα απεστειλεν ο ιησους παραγγειλας αυτοις λεγων εις οδον εθνων μη απελθητε και εις πολιν σαμαρειτων μη εισελθητε'),
('grc_f35', 'Mateo 10:6', 'Mateo', 10, 6, 'πορευεσθε δε μαλλον προς τα προβατα τα απολωλοτα οικου ισραηλ'),
('grc_f35', 'Mateo 10:7', 'Mateo', 10, 7, 'πορευομενοι δε κηρυσσετε λεγοντες οτι ηγγικεν η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 10:8', 'Mateo', 10, 8, 'ασθενουντας θεραπευετε λεπρους καθαριζετε δαιμονια εκβαλλετε δωρεαν ελαβετε δωρεαν δοτε'),
('grc_f35', 'Mateo 10:9', 'Mateo', 10, 9, 'μη κτησησθε χρυσον μηδε αργυρον μηδε χαλκον εις τας ζωνας υμων'),
('grc_f35', 'Mateo 10:10', 'Mateo', 10, 10, 'μη πηραν εις οδον μηδε δυο χιτωνας μηδε υποδηματα μηδε ραβδους αξιος γαρ ο εργατης της τροφης αυτου εστιν'),
('grc_f35', 'Mateo 10:11', 'Mateo', 10, 11, 'εις ην δ αν πολιν η κωμην εισελθητε εξετασατε τις εν αυτη αξιος εστιν κακει μεινατε εως αν εξελθητε'),
('grc_f35', 'Mateo 10:12', 'Mateo', 10, 12, 'εισερχομενοι δε εις την οικιαν ασπασασθε αυτην'),
('grc_f35', 'Mateo 10:13', 'Mateo', 10, 13, 'και εαν μεν η η οικια αξια ελθετω η ειρηνη υμων επ αυτην εαν δε μη η αξια η ειρηνη υμων προς υμας επιστραφητω'),
('grc_f35', 'Mateo 10:14', 'Mateo', 10, 14, 'και ος εαν μη δεξηται υμας μηδε ακουση τους λογους υμων εξερχομενοι της οικιας η της πολεως εκεινης εκτιναξατε τον κονιορτον των ποδων υμων'),
('grc_f35', 'Mateo 10:15', 'Mateo', 10, 15, 'αμην λεγω υμιν ανεκτοτερον εσται γη σοδομων και γομορρων εν ημερα κρισεως η τη πολει εκεινη'),
('grc_f35', 'Mateo 10:16', 'Mateo', 10, 16, 'ιδου εγω αποστελλω υμας ως προβατα εν μεσω λυκων γινεσθε ουν φρονιμοι ως οι οφεις και ακεραιοι ως αι περιστεραι'),
('grc_f35', 'Mateo 10:17', 'Mateo', 10, 17, 'προσεχετε δε απο των ανθρωπων παραδωσουσιν γαρ υμας εις συνεδρια και εν ταις συναγωγαις αυτων μαστιγωσουσιν υμας'),
('grc_f35', 'Mateo 10:18', 'Mateo', 10, 18, 'και επι ηγεμονας δε και βασιλεις αχθησεσθε ενεκεν εμου εις μαρτυριον αυτοις και τοις εθνεσιν'),
('grc_f35', 'Mateo 10:19', 'Mateo', 10, 19, 'οταν δε παραδιδωσιν υμας μη μεριμνησητε πως η τι λαλησετε δοθησεται γαρ υμιν εν εκεινη τη ωρα τι λαλησετε'),
('grc_f35', 'Mateo 10:20', 'Mateo', 10, 20, 'ου γαρ υμεις εστε οι λαλουντες αλλα το πνευμα του πατρος υμων το λαλουν εν υμιν'),
('grc_f35', 'Mateo 10:21', 'Mateo', 10, 21, 'παραδωσει δε αδελφος αδελφον εις θανατον και πατηρ τεκνον και επαναστησονται τεκνα επι γονεις και θανατωσουσιν αυτους'),
('grc_f35', 'Mateo 10:22', 'Mateo', 10, 22, 'και εσεσθε μισουμενοι υπο παντων δια το ονομα μου ο δε υπομεινας εις τελος ουτος σωθησεται'),
('grc_f35', 'Mateo 10:23', 'Mateo', 10, 23, 'οταν δε διωκωσιν υμας εν τη πολει ταυτη φευγετε εις την αλλην αμην γαρ λεγω υμιν ου μη τελεσητε τας πολεις του ισραηλ εως αν ελθη ο υιος του ανθρωπου'),
('grc_f35', 'Mateo 10:24', 'Mateo', 10, 24, 'ουκ εστιν μαθητης υπερ τον διδασκαλον ουδε δουλος υπερ τον κυριον αυτου'),
('grc_f35', 'Mateo 10:25', 'Mateo', 10, 25, 'αρκετον τω μαθητη ινα γενηται ως ο διδασκαλος αυτου και ο δουλος ως ο κυριος αυτου ει τον οικοδεσποτην βεελζεβουλ απεκαλεσαν ποσω μαλλον τους οικειακους αυτου'),
('grc_f35', 'Mateo 10:26', 'Mateo', 10, 26, 'μη ουν φοβηθητε αυτους ουδεν γαρ εστιν κεκαλυμμενον ο ουκ αποκαλυφθησεται και κρυπτον ο ου γνωσθησεται'),
('grc_f35', 'Mateo 10:27', 'Mateo', 10, 27, 'ο λεγω υμιν εν τη σκοτια ειπατε εν τω φωτι και ο εις το ους ακουετε κηρυξατε επι των δωματων'),
('grc_f35', 'Mateo 10:28', 'Mateo', 10, 28, 'και μη φοβεισθε απο των αποκτενοντων το σωμα την δε ψυχην μη δυναμενων αποκτειναι φοβηθητε δε μαλλον τον δυναμενον και ψυχην και σωμα απολεσαι εν γεεννη'),
('grc_f35', 'Mateo 10:29', 'Mateo', 10, 29, 'ουχι δυο στρουθια ασσαριου πωλειται και εν εξ αυτων ου πεσειται επι την γην ανευ του πατρος υμων'),
('grc_f35', 'Mateo 10:30', 'Mateo', 10, 30, 'υμων δε και αι τριχες της κεφαλης πασαι ηριθμημεναι εισιν'),
('grc_f35', 'Mateo 10:31', 'Mateo', 10, 31, 'μη ουν φοβηθητε πολλω στρουθιων διαφερετε υμεις'),
('grc_f35', 'Mateo 10:32', 'Mateo', 10, 32, 'πας ουν οστις ομολογησει εν εμοι εμπροσθεν των ανθρωπων ομολογησω καγω εν αυτω εμπροσθεν του πατρος μου του εν ουρανοις'),
('grc_f35', 'Mateo 10:33', 'Mateo', 10, 33, 'οστις δ αν αρνησηται με εμπροσθεν των ανθρωπων αρνησομαι αυτον καγω εμπροσθεν του πατρος μου του εν ουρανοις'),
('grc_f35', 'Mateo 10:34', 'Mateo', 10, 34, 'μη νομισητε οτι ηλθον βαλειν ειρηνην επι την γην ουκ ηλθον βαλειν ειρηνην αλλα μαχαιραν'),
('grc_f35', 'Mateo 10:35', 'Mateo', 10, 35, 'ηλθον γαρ διχασαι ανθρωπον κατα του πατρος αυτου και θυγατερα κατα της μητρος αυτης και νυμφην κατα της πενθερας αυτης'),
('grc_f35', 'Mateo 10:36', 'Mateo', 10, 36, 'και εχθροι του ανθρωπου οι οικειακοι αυτου'),
('grc_f35', 'Mateo 10:37', 'Mateo', 10, 37, 'ο φιλων πατερα η μητερα υπερ εμε ουκ εστιν μου αξιος και ο φιλων υιον η θυγατερα υπερ εμε ουκ εστιν μου αξιος'),
('grc_f35', 'Mateo 10:38', 'Mateo', 10, 38, 'και ος ου λαμβανει τον σταυρον αυτου και ακολουθει οπισω μου ουκ εστιν μου αξιος'),
('grc_f35', 'Mateo 10:39', 'Mateo', 10, 39, 'ο ευρων την ψυχην αυτου απολεσει αυτην και ο απολεσας την ψυχην αυτου ενεκεν εμου ευρησει αυτην'),
('grc_f35', 'Mateo 10:40', 'Mateo', 10, 40, 'ο δεχομενος υμας εμε δεχεται και ο εμε δεχομενος δεχεται τον αποστειλαντα με'),
('grc_f35', 'Mateo 10:41', 'Mateo', 10, 41, 'ο δεχομενος προφητην εις ονομα προφητου μισθον προφητου ληψεται και ο δεχομενος δικαιον εις ονομα δικαιου μισθον δικαιου ληψεται'),
('grc_f35', 'Mateo 10:42', 'Mateo', 10, 42, 'και ος εαν ποτιση ενα των μικρων τουτων ποτηριον ψυχρου μονον εις ονομα μαθητου αμην λεγω υμιν ου μη απολεση τον μισθον αυτου'),
('grc_f35', 'Mateo 11:1', 'Mateo', 11, 1, 'και εγενετο οτε ετελεσεν ο ιησους διατασσων τοις δωδεκα μαθηταις αυτου μετεβη εκειθεν του διδασκειν και κηρυσσειν εν ταις πολεσιν αυτων'),
('grc_f35', 'Mateo 11:2', 'Mateo', 11, 2, 'ο δε ιωαννης ακουσας εν τω δεσμωτηριω τα εργα του χριστου πεμψας δυο των μαθητων αυτου'),
('grc_f35', 'Mateo 11:3', 'Mateo', 11, 3, 'ειπεν αυτω συ ει ο ερχομενος η ετερον προσδοκωμεν'),
('grc_f35', 'Mateo 11:4', 'Mateo', 11, 4, 'και αποκριθεις ο ιησους ειπεν αυτοις πορευθεντες απαγγειλατε ιωαννη α ακουετε και βλεπετε'),
('grc_f35', 'Mateo 11:5', 'Mateo', 11, 5, 'τυφλοι αναβλεπουσιν και χωλοι περιπατουσιν λεπροι καθαριζονται και κωφοι ακουουσιν νεκροι εγειρονται και πτωχοι ευαγγελιζονται'),
('grc_f35', 'Mateo 11:6', 'Mateo', 11, 6, 'και μακαριος εστιν ος εαν μη σκανδαλισθη εν εμοι'),
('grc_f35', 'Mateo 11:7', 'Mateo', 11, 7, 'τουτων δε πορευομενων ηρξατο ο ιησους λεγειν τοις οχλοις περι ιωαννου τι εξηλθετε εις την ερημον θεασασθαι καλαμον υπο ανεμου σαλευομενον'),
('grc_f35', 'Mateo 11:8', 'Mateo', 11, 8, 'αλλα τι εξηλθετε ιδειν ανθρωπον εν μαλακοις ιματιοις ημφιεσμενον ιδου οι τα μαλακα φορουντες εν τοις οικοις των βασιλειων εισιν'),
('grc_f35', 'Mateo 11:9', 'Mateo', 11, 9, 'αλλα τι εξηλθετε ιδειν προφητην ναι λεγω υμιν και περισσοτερον προφητου'),
('grc_f35', 'Mateo 11:10', 'Mateo', 11, 10, 'ουτος γαρ εστιν περι ου γεγραπται ιδου εγω αποστελλω τον αγγελον μου προ προσωπου σου ος κατασκευασει την οδον σου εμπροσθεν σου'),
('grc_f35', 'Mateo 11:11', 'Mateo', 11, 11, 'αμην λεγω υμιν ουκ εγηγερται εν γεννητοις γυναικων μειζων ιωαννου του βαπτιστου ο δε μικροτερος εν τη βασιλεια των ουρανων μειζων αυτου εστιν'),
('grc_f35', 'Mateo 11:12', 'Mateo', 11, 12, 'απο δε των ημερων ιωαννου του βαπτιστου εως αρτι η βασιλεια των ουρανων βιαζεται και βιασται αρπαζουσιν αυτην'),
('grc_f35', 'Mateo 11:13', 'Mateo', 11, 13, 'παντες γαρ οι προφηται και ο νομος εως ιωαννου προεφητευσαν'),
('grc_f35', 'Mateo 11:14', 'Mateo', 11, 14, 'και ει θελετε δεξασθαι αυτος εστιν ηλιας ο μελλων ερχεσθαι'),
('grc_f35', 'Mateo 11:15', 'Mateo', 11, 15, 'ο εχων ωτα ακουειν ακουετω'),
('grc_f35', 'Mateo 11:16', 'Mateo', 11, 16, 'τινι δε ομοιωσω την γενεαν ταυτην ομοια εστιν παιδιοις εν αγορα καθημενοις και προσφωνουσιν τοις εταιροις αυτων'),
('grc_f35', 'Mateo 11:17', 'Mateo', 11, 17, 'και λεγουσιν ηυλησαμεν υμιν και ουκ ωρχησασθε εθρηνησαμεν υμιν και ουκ εκοψασθε'),
('grc_f35', 'Mateo 11:18', 'Mateo', 11, 18, 'ηλθεν γαρ ιωαννης μητε εσθιων μητε πινων και λεγουσιν δαιμονιον εχει'),
('grc_f35', 'Mateo 11:19', 'Mateo', 11, 19, 'ηλθεν ο υιος του ανθρωπου εσθιων και πινων και λεγουσιν ιδου ανθρωπος φαγος και οινοποτης τελωνων φιλος και αμαρτωλων και εδικαιωθη η σοφια απο των τεκνων αυτης'),
('grc_f35', 'Mateo 11:20', 'Mateo', 11, 20, 'τοτε ηρξατο ο ιησους ονειδιζειν τας πολεις εν αις εγενοντο αι πλεισται δυναμεις αυτου οτι ου μετενοησαν'),
('grc_f35', 'Mateo 11:21', 'Mateo', 11, 21, 'ουαι σοι χωραζιν ουαι σοι βηθσαιδα οτι ει εν τυρω και σιδωνι εγενοντο αι δυναμεις αι γενομεναι εν υμιν παλαι αν εν σακκω και σποδω μετενοησαν'),
('grc_f35', 'Mateo 11:22', 'Mateo', 11, 22, 'πλην λεγω υμιν τυρω και σιδωνι ανεκτοτερον εσται εν ημερα κρισεως η υμιν'),
('grc_f35', 'Mateo 11:23', 'Mateo', 11, 23, 'και συ καπερναουμ η εως του ουρανου υψωθης εως αδου καταβιβασθηση οτι ει εν σοδομοις εγενοντο αι δυναμεις αι γενομεναι εν σοι εμειναν αν μεχρι της σημερον'),
('grc_f35', 'Mateo 11:24', 'Mateo', 11, 24, 'πλην λεγω υμιν οτι γη σοδομων ανεκτοτερον εσται εν ημερα κρισεως η σοι'),
('grc_f35', 'Mateo 11:25', 'Mateo', 11, 25, 'εν εκεινω τω καιρω αποκριθεις ο ιησους ειπεν εξομολογουμαι σοι πατερ κυριε του ουρανου και της γης οτι απεκρυψας ταυτα απο σοφων και συνετων και απεκαλυψας αυτα νηπιοις'),
('grc_f35', 'Mateo 11:26', 'Mateo', 11, 26, 'ναι ο πατηρ οτι ουτως εγενετο ευδοκια εμπροσθεν σου'),
('grc_f35', 'Mateo 11:27', 'Mateo', 11, 27, 'παντα μοι παρεδοθη υπο του πατρος μου και ουδεις επιγινωσκει τον υιον ει μη ο πατηρ ουδε τον πατερα τις επιγινωσκει ει μη ο υιος και ω εαν βουληται ο υιος αποκαλυψαι'),
('grc_f35', 'Mateo 11:28', 'Mateo', 11, 28, 'δευτε προς με παντες οι κοπιωντες και πεφορτισμενοι καγω αναπαυσω υμας'),
('grc_f35', 'Mateo 11:29', 'Mateo', 11, 29, 'αρατε τον ζυγον μου εφ υμας και μαθετε απ εμου οτι πραος ειμι και ταπεινος τη καρδια και ευρησετε αναπαυσιν ταις ψυχαις υμων'),
('grc_f35', 'Mateo 11:30', 'Mateo', 11, 30, 'ο γαρ ζυγος μου χρηστος και το φορτιον μου ελαφρον εστιν'),
('grc_f35', 'Mateo 12:1', 'Mateo', 12, 1, 'εν εκεινω τω καιρω επορευθη ο ιησους τοις σαββασιν δια των σποριμων οι δε μαθηται αυτου επεινασαν και ηρξαντο τιλλειν σταχυας και εσθιειν'),
('grc_f35', 'Mateo 12:2', 'Mateo', 12, 2, 'οι δε φαρισαιοι ιδοντες ειπον αυτω ιδου οι μαθηται σου ποιουσιν ο ουκ εξεστιν ποιειν εν σαββατω'),
('grc_f35', 'Mateo 12:3', 'Mateo', 12, 3, 'ο δε ειπεν αυτοις ουκ ανεγνωτε τι εποιησεν δαυιδ οτε επεινασεν αυτος και οι μετ αυτου'),
('grc_f35', 'Mateo 12:4', 'Mateo', 12, 4, 'πως εισηλθεν εις τον οικον του θεου και τους αρτους της προθεσεως εφαγεν ους ουκ εξον ην αυτω φαγειν ουδε τοις μετ αυτου ει μη τοις ιερευσιν μονοις'),
('grc_f35', 'Mateo 12:5', 'Mateo', 12, 5, 'η ουκ ανεγνωτε εν τω νομω οτι τοις σαββασιν οι ιερεις εν τω ιερω το σαββατον βεβηλουσιν και αναιτιοι εισιν'),
('grc_f35', 'Mateo 12:6', 'Mateo', 12, 6, 'λεγω δε υμιν οτι του ιερου μειζον εστιν ωδε'),
('grc_f35', 'Mateo 12:7', 'Mateo', 12, 7, 'ει δε εγνωκειτε τι εστιν ελεον θελω και ου θυσιαν ουκ αν κατεδικασατε τους αναιτιους'),
('grc_f35', 'Mateo 12:8', 'Mateo', 12, 8, 'κυριος γαρ εστιν του σαββατου ο υιος του ανθρωπου'),
('grc_f35', 'Mateo 12:9', 'Mateo', 12, 9, 'και μεταβας εκειθεν ηλθεν εις την συναγωγην αυτων'),
('grc_f35', 'Mateo 12:10', 'Mateo', 12, 10, 'και ιδου ανθρωπος ην την χειρα εχων ξηραν και επηρωτησαν αυτον λεγοντες ει εξεστιν τοις σαββασιν θεραπευειν ινα κατηγορησωσιν αυτου'),
('grc_f35', 'Mateo 12:11', 'Mateo', 12, 11, 'ο δε ειπεν αυτοις τις εσται εξ υμων ανθρωπος ος εξει προβατον εν και εαν εμπεση τουτο τοις σαββασιν εις βοθυνον ουχι κρατησει αυτο και εγερει'),
('grc_f35', 'Mateo 12:12', 'Mateo', 12, 12, 'ποσω ουν διαφερει ανθρωπος προβατου ωστε εξεστιν τοις σαββασιν καλως ποιειν'),
('grc_f35', 'Mateo 12:13', 'Mateo', 12, 13, 'τοτε λεγει τω ανθρωπω εκτεινον την χειρα σου και εξετεινεν και αποκατεσταθη υγιης ως η αλλη'),
('grc_f35', 'Mateo 12:14', 'Mateo', 12, 14, 'οι δε φαρισαιοι συμβουλιον ελαβον κατ αυτου εξελθοντες οπως αυτον απολεσωσιν'),
('grc_f35', 'Mateo 12:15', 'Mateo', 12, 15, 'ο δε ιησους γνους ανεχωρησεν εκειθεν και ηκολουθησαν αυτω οχλοι πολλοι και εθεραπευσεν αυτους απαντας'),
('grc_f35', 'Mateo 12:16', 'Mateo', 12, 16, 'και επετιμησεν αυτοις ινα μη φανερον αυτον ποιησωσιν'),
('grc_f35', 'Mateo 12:17', 'Mateo', 12, 17, 'οπως πληρωθη το ρηθεν δια ησαιου του προφητου λεγοντος'),
('grc_f35', 'Mateo 12:18', 'Mateo', 12, 18, 'ιδου ο παις μου ον ηρετισα ο αγαπητος μου εις ον ευδοκησεν η ψυχη μου θησω το πνευμα μου επ αυτον και κρισιν τοις εθνεσιν απαγγελει'),
('grc_f35', 'Mateo 12:19', 'Mateo', 12, 19, 'ουκ ερισει ουδε κραυγασει ουδε ακουσει τις εν ταις πλατειαις την φωνην αυτου'),
('grc_f35', 'Mateo 12:20', 'Mateo', 12, 20, 'καλαμον συντετριμμενον ου κατεαξει και λινον τυφομενον ου σβεσει εως αν εκβαλη εις νικος την κρισιν'),
('grc_f35', 'Mateo 12:21', 'Mateo', 12, 21, 'και τω ονοματι αυτου εθνη ελπιουσιν'),
('grc_f35', 'Mateo 12:22', 'Mateo', 12, 22, 'τοτε προσηνεχθη αυτω δαιμονιζομενος τυφλος και κωφος και εθεραπευσεν αυτον ωστε τον τυφλον και κωφον λαλειν και βλεπειν'),
('grc_f35', 'Mateo 12:23', 'Mateo', 12, 23, 'και εξισταντο παντες οι οχλοι και ελεγον μητι ουτος εστιν ο χριστος ο υιος δαυιδ'),
('grc_f35', 'Mateo 12:24', 'Mateo', 12, 24, 'οι δε φαρισαιοι ακουσαντες ειπον ουτος ουκ εκβαλλει τα δαιμονια ει μη εν βεελζεβουλ αρχοντι των δαιμονιων'),
('grc_f35', 'Mateo 12:25', 'Mateo', 12, 25, 'ειδως δε ο ιησους τας ενθυμησεις αυτων ειπεν αυτοις πασα βασιλεια μερισθεισα καθ εαυτης ερημουται και πασα πολις η οικια μερισθεισα καθ εαυτης ου σταθησεται'),
('grc_f35', 'Mateo 12:26', 'Mateo', 12, 26, 'και ει ο σατανας τον σαταναν εκβαλλει εφ εαυτον εμερισθη πως ουν σταθησεται η βασιλεια αυτου'),
('grc_f35', 'Mateo 12:27', 'Mateo', 12, 27, 'και ει εγω εν βεελζεβουλ εκβαλλω τα δαιμονια οι υιοι υμων εν τινι εκβαλλουσιν δια τουτο αυτοι υμων εσονται κριται'),
('grc_f35', 'Mateo 12:28', 'Mateo', 12, 28, 'ει δε εγω εν πνευματι θεου εκβαλλω τα δαιμονια αρα εφθασεν εφ υμας η βασιλεια του θεου'),
('grc_f35', 'Mateo 12:29', 'Mateo', 12, 29, 'η πως δυναται τις εισελθειν εις την οικιαν του ισχυρου και τα σκευη αυτου διαρπασαι εαν μη πρωτον δηση τον ισχυρον και τοτε την οικιαν αυτου διαρπαση'),
('grc_f35', 'Mateo 12:30', 'Mateo', 12, 30, 'ο μη ων μετ εμου κατ εμου εστιν και ο μη συναγων μετ εμου σκορπιζει'),
('grc_f35', 'Mateo 12:31', 'Mateo', 12, 31, 'δια τουτο λεγω υμιν πασα αμαρτια και βλασφημια αφεθησεται τοις ανθρωποις η δε του πνευματος βλασφημια ουκ αφεθησεται τοις ανθρωποις'),
('grc_f35', 'Mateo 12:32', 'Mateo', 12, 32, 'και ος εαν ειπη λογον κατα του υιου του ανθρωπου αφεθησεται αυτω ος δ αν ειπη κατα του πνευματος του αγιου ουκ αφεθησεται αυτω ουτε εν τω νυν αιωνι ουτε εν τω μελλοντι'),
('grc_f35', 'Mateo 12:33', 'Mateo', 12, 33, 'η ποιησατε το δενδρον καλον και τον καρπον αυτου καλον η ποιησατε το δενδρον σαπρον και τον καρπον αυτου σαπρον εκ γαρ του καρπου το δενδρον γινωσκεται'),
('grc_f35', 'Mateo 12:34', 'Mateo', 12, 34, 'γεννηματα εχιδνων πως δυνασθε αγαθα λαλειν πονηροι οντες εκ γαρ του περισσευματος της καρδιας το στομα λαλει'),
('grc_f35', 'Mateo 12:35', 'Mateo', 12, 35, 'ο αγαθος ανθρωπος εκ του αγαθου θησαυρου εκβαλλει αγαθα και ο πονηρος ανθρωπος εκ του πονηρου θησαυρου εκβαλλει πονηρα'),
('grc_f35', 'Mateo 12:36', 'Mateo', 12, 36, 'λεγω δε υμιν οτι παν ρημα αργον ο εαν λαλησωσιν οι ανθρωποι αποδωσουσιν περι αυτου λογον εν ημερα κρισεως'),
('grc_f35', 'Mateo 12:37', 'Mateo', 12, 37, 'εκ γαρ των λογων σου δικαιωθηση και εκ των λογων σου καταδικασθηση'),
('grc_f35', 'Mateo 12:38', 'Mateo', 12, 38, 'τοτε απεκριθησαν τινες των γραμματεων και φαρισαιων λεγοντες διδασκαλε θελομεν απο σου σημειον ιδειν'),
('grc_f35', 'Mateo 12:39', 'Mateo', 12, 39, 'ο δε αποκριθεις ειπεν αυτοις γενεα πονηρα και μοιχαλις σημειον επιζητει και σημειον ου δοθησεται αυτη ει μη το σημειον ιωνα του προφητου'),
('grc_f35', 'Mateo 12:40', 'Mateo', 12, 40, 'ωσπερ γαρ ην ιωνας εν τη κοιλια του κητους τρεις ημερας και τρεις νυκτας ουτως εσται ο υιος του ανθρωπου εν τη καρδια της γης τρεις ημερας και τρεις νυκτας'),
('grc_f35', 'Mateo 12:41', 'Mateo', 12, 41, 'ανδρες νινευιται αναστησονται εν τη κρισει μετα της γενεας ταυτης και κατακρινουσιν αυτην οτι μετενοησαν εις το κηρυγμα ιωνα και ιδου πλειον ιωνα ωδε'),
('grc_f35', 'Mateo 12:42', 'Mateo', 12, 42, 'βασιλισσα νοτου εγερθησεται εν τη κρισει μετα της γενεας ταυτης και κατακρινει αυτην οτι ηλθεν εκ των περατων της γης ακουσαι την σοφιαν σολομωνος και ιδου πλειον σολομωνος ωδε'),
('grc_f35', 'Mateo 12:43', 'Mateo', 12, 43, 'οταν δε το ακαθαρτον πνευμα εξελθη απο του ανθρωπου διερχεται δι ανυδρων τοπων ζητουν αναπαυσιν και ουχ ευρισκει'),
('grc_f35', 'Mateo 12:44', 'Mateo', 12, 44, 'τοτε λεγει επιστρεψω εις τον οικον μου οθεν εξηλθον και ελθον ευρισκει σχολαζοντα σεσαρωμενον και κεκοσμημενον'),
('grc_f35', 'Mateo 12:45', 'Mateo', 12, 45, 'τοτε πορευεται και παραλαμβανει μεθ εαυτου επτα ετερα πνευματα πονηροτερα εαυτου και εισελθοντα κατοικει εκει και γινεται τα εσχατα του ανθρωπου εκεινου χειρονα των πρωτων ουτως εσται και τη γενεα ταυτη τη πονηρα'),
('grc_f35', 'Mateo 12:46', 'Mateo', 12, 46, 'ετι δε αυτου λαλουντος τοις οχλοις ιδου η μητηρ και οι αδελφοι αυτου ειστηκεισαν εξω ζητουντες αυτω λαλησαι'),
('grc_f35', 'Mateo 12:47', 'Mateo', 12, 47, 'ειπεν δε τις αυτω ιδου η μητηρ σου και οι αδελφοι σου εξω εστηκασιν ζητουντες σοι λαλησαι'),
('grc_f35', 'Mateo 12:48', 'Mateo', 12, 48, 'ο δε αποκριθεις ειπεν τω ειποντι αυτω τις εστιν η μητηρ μου και τινες εισιν οι αδελφοι μου'),
('grc_f35', 'Mateo 12:49', 'Mateo', 12, 49, 'και εκτεινας την χειρα αυτου επι τους μαθητας αυτου ειπεν ιδου η μητηρ μου και οι αδελφοι μου'),
('grc_f35', 'Mateo 12:50', 'Mateo', 12, 50, 'οστις γαρ αν ποιηση το θελημα του πατρος μου του εν ουρανοις αυτος μου αδελφος και αδελφη και μητηρ εστιν'),
('grc_f35', 'Mateo 13:1', 'Mateo', 13, 1, 'εν δε τη ημερα εκεινη εξελθων ο ιησους απο της οικιας εκαθητο παρα την θαλασσαν'),
('grc_f35', 'Mateo 13:2', 'Mateo', 13, 2, 'και συνηχθησαν προς αυτον οχλοι πολλοι ωστε αυτον εις πλοιον εμβαντα καθησθαι και πας ο οχλος επι τον αιγιαλον ειστηκει'),
('grc_f35', 'Mateo 13:3', 'Mateo', 13, 3, 'και ελαλησεν αυτοις εν παραβολαις πολλα λεγων ιδου εξηλθεν ο σπειρων του σπειραι'),
('grc_f35', 'Mateo 13:4', 'Mateo', 13, 4, 'και εν τω σπειρειν αυτον α μεν επεσεν παρα την οδον και ηλθεν τα πετεινα και κατεφαγεν αυτα'),
('grc_f35', 'Mateo 13:5', 'Mateo', 13, 5, 'αλλα δε επεσεν επι τα πετρωδη οπου ουκ ειχεν γην πολλην και ευθεως εξανετειλεν δια το μη εχειν βαθος γης'),
('grc_f35', 'Mateo 13:6', 'Mateo', 13, 6, 'ηλιου δε ανατειλαντος εκαυματισθη και δια το μη εχειν ριζαν εξηρανθη'),
('grc_f35', 'Mateo 13:7', 'Mateo', 13, 7, 'αλλα δε επεσεν επι τας ακανθας και ανεβησαν αι ακανθαι και απεπνιξαν αυτα'),
('grc_f35', 'Mateo 13:8', 'Mateo', 13, 8, 'αλλα δε επεσεν επι την γην την καλην και εδιδου καρπον ο μεν εκατον ο δε εξηκοντα ο δε τριακοντα'),
('grc_f35', 'Mateo 13:9', 'Mateo', 13, 9, 'ο εχων ωτα ακουειν ακουετω'),
('grc_f35', 'Mateo 13:10', 'Mateo', 13, 10, 'και προσελθοντες οι μαθηται ειπον αυτω δια τι εν παραβολαις λαλεις αυτοις'),
('grc_f35', 'Mateo 13:11', 'Mateo', 13, 11, 'ο δε αποκριθεις ειπεν αυτοις οτι υμιν δεδοται γνωναι τα μυστηρια της βασιλειας των ουρανων εκεινοις δε ου δεδοται'),
('grc_f35', 'Mateo 13:12', 'Mateo', 13, 12, 'οστις γαρ εχει δοθησεται αυτω και περισσευθησεται οστις δε ουκ εχει και ο εχει αρθησεται απ αυτου'),
('grc_f35', 'Mateo 13:13', 'Mateo', 13, 13, 'δια τουτο εν παραβολαις αυτοις λαλω οτι βλεποντες ου βλεπουσιν και ακουοντες ουκ ακουουσιν ουδε συνιουσιν'),
('grc_f35', 'Mateo 13:14', 'Mateo', 13, 14, 'και αναπληρουται αυτοις η προφητεια ησαιου η λεγουσα ακοη ακουσετε και ου μη συνητε και βλεποντες βλεψετε και ου μη ιδητε'),
('grc_f35', 'Mateo 13:15', 'Mateo', 13, 15, 'επαχυνθη γαρ η καρδια του λαου τουτου και τοις ωσιν βαρεως ηκουσαν και τους οφθαλμους αυτων εκαμμυσαν μηποτε ιδωσιν τοις οφθαλμοις και τοις ωσιν ακουσωσιν και τη καρδια συνωσιν και επιστρεψωσιν και ιασωμαι αυτους'),
('grc_f35', 'Mateo 13:16', 'Mateo', 13, 16, 'υμων δε μακαριοι οι οφθαλμοι οτι βλεπουσιν και τα ωτα υμων οτι ακουει'),
('grc_f35', 'Mateo 13:17', 'Mateo', 13, 17, 'αμην γαρ λεγω υμιν οτι πολλοι προφηται και δικαιοι επεθυμησαν ιδειν α βλεπετε και ουκ ειδον και ακουσαι α ακουετε και ουκ ηκουσαν'),
('grc_f35', 'Mateo 13:18', 'Mateo', 13, 18, 'υμεις ουν ακουσατε την παραβολην του σπειροντος'),
('grc_f35', 'Mateo 13:19', 'Mateo', 13, 19, 'παντος ακουοντος τον λογον της βασιλειας και μη συνιεντος ερχεται ο πονηρος και αρπαζει το εσπαρμενον εν τη καρδια αυτου ουτος εστιν ο παρα την οδον σπαρεις'),
('grc_f35', 'Mateo 13:20', 'Mateo', 13, 20, 'ο δε επι τα πετρωδη σπαρεις ουτος εστιν ο τον λογον ακουων και ευθυς μετα χαρας λαμβανων αυτον'),
('grc_f35', 'Mateo 13:21', 'Mateo', 13, 21, 'ουκ εχει δε ριζαν εν εαυτω αλλα προσκαιρος εστιν γενομενης δε θλιψεως η διωγμου δια τον λογον ευθυς σκανδαλιζεται'),
('grc_f35', 'Mateo 13:22', 'Mateo', 13, 22, 'ο δε εις τας ακανθας σπαρεις ουτος εστιν ο τον λογον ακουων και η μεριμνα του αιωνος τουτου και η απατη του πλουτου συμπνιγει τον λογον και ακαρπος γινεται'),
('grc_f35', 'Mateo 13:23', 'Mateo', 13, 23, 'ο δε επι την γην την καλην σπαρεις ουτος εστιν ο τον λογον ακουων και συνιων ος δη καρποφορει και ποιει ο μεν εκατον ο δε εξηκοντα ο δε τριακοντα'),
('grc_f35', 'Mateo 13:24', 'Mateo', 13, 24, 'αλλην παραβολην παρεθηκεν αυτοις λεγων ωμοιωθη η βασιλεια των ουρανων ανθρωπω σπειραντι καλον σπερμα εν τω αγρω αυτου'),
('grc_f35', 'Mateo 13:25', 'Mateo', 13, 25, 'εν δε τω καθευδειν τους ανθρωπους ηλθεν αυτου ο εχθρος και εσπειρεν ζιζανια ανα μεσον του σιτου και απηλθεν'),
('grc_f35', 'Mateo 13:26', 'Mateo', 13, 26, 'οτε δε εβλαστησεν ο χορτος και καρπον εποιησεν τοτε εφανη και τα ζιζανια'),
('grc_f35', 'Mateo 13:27', 'Mateo', 13, 27, 'προσελθοντες δε οι δουλοι του οικοδεσποτου ειπον αυτω κυριε ουχι καλον σπερμα εσπειρας εν τω σω αγρω ποθεν ουν εχει ζιζανια'),
('grc_f35', 'Mateo 13:28', 'Mateo', 13, 28, 'ο δε εφη αυτοις εχθρος ανθρωπος τουτο εποιησεν οι δε δουλοι ειπον αυτω θελεις ουν απελθοντες συλλεξομεν αυτα'),
('grc_f35', 'Mateo 13:29', 'Mateo', 13, 29, 'ο δε εφη ου μηποτε συλλεγοντες τα ζιζανια εκριζωσητε αμα αυτοις τον σιτον'),
('grc_f35', 'Mateo 13:30', 'Mateo', 13, 30, 'αφετε συναυξανεσθαι αμφοτερα μεχρι του θερισμου και εν καιρω του θερισμου ερω τοις θερισταις συλλεξατε πρωτον τα ζιζανια και δησατε αυτα εις δεσμας προς το κατακαυσαι αυτα τον δε σιτον συναγαγετε εις την αποθηκην μου'),
('grc_f35', 'Mateo 13:31', 'Mateo', 13, 31, 'αλλην παραβολην παρεθηκεν αυτοις λεγων ομοια εστιν η βασιλεια των ουρανων κοκκω σιναπεως ον λαβων ανθρωπος εσπειρεν εν τω αγρω αυτου'),
('grc_f35', 'Mateo 13:32', 'Mateo', 13, 32, 'ο μικροτερον μεν εστιν παντων των σπερματων οταν δε αυξηθη μειζον παντων των λαχανων εστιν και γινεται δενδρον ωστε ελθειν τα πετεινα του ουρανου και κατασκηνουν εν τοις κλαδοις αυτου'),
('grc_f35', 'Mateo 13:33', 'Mateo', 13, 33, 'αλλην παραβολην ελαλησεν αυτοις ομοια εστιν η βασιλεια των ουρανων ζυμη ην λαβουσα γυνη εκρυψεν εις αλευρου σατα τρια εως ου εζυμωθη ολον'),
('grc_f35', 'Mateo 13:34', 'Mateo', 13, 34, 'ταυτα παντα ελαλησεν ο ιησους εν παραβολαις τοις οχλοις και χωρις παραβολης ουκ ελαλει αυτοις'),
('grc_f35', 'Mateo 13:35', 'Mateo', 13, 35, 'οπως πληρωθη το ρηθεν δια του προφητου λεγοντος ανοιξω εν παραβολαις το στομα μου ερευξομαι κεκρυμμενα απο καταβολης κοσμου'),
('grc_f35', 'Mateo 13:36', 'Mateo', 13, 36, 'τοτε αφεις τους οχλους ηλθεν εις την οικιαν ο ιησους και προσηλθον αυτω οι μαθηται αυτου λεγοντες φρασον ημιν την παραβολην των ζιζανιων του αγρου'),
('grc_f35', 'Mateo 13:37', 'Mateo', 13, 37, 'ο δε αποκριθεις ειπεν αυτοις ο σπειρων το καλον σπερμα εστιν ο υιος του ανθρωπου'),
('grc_f35', 'Mateo 13:38', 'Mateo', 13, 38, 'ο δε αγρος εστιν ο κοσμος το δε καλον σπερμα ουτοι εισιν οι υιοι της βασιλειας τα δε ζιζανια εισιν οι υιοι του πονηρου'),
('grc_f35', 'Mateo 13:39', 'Mateo', 13, 39, 'ο δε εχθρος ο σπειρας αυτα εστιν ο διαβολος ο δε θερισμος συντελεια του αιωνος εστιν οι δε θερισται αγγελοι εισιν'),
('grc_f35', 'Mateo 13:40', 'Mateo', 13, 40, 'ωσπερ ουν συλλεγεται τα ζιζανια και πυρι καιεται ουτως εσται εν τη συντελεια του αιωνος τουτου'),
('grc_f35', 'Mateo 13:41', 'Mateo', 13, 41, 'αποστελει ο υιος του ανθρωπου τους αγγελους αυτου και συλλεξουσιν εκ της βασιλειας αυτου παντα τα σκανδαλα και τους ποιουντας την ανομιαν'),
('grc_f35', 'Mateo 13:42', 'Mateo', 13, 42, 'και βαλουσιν αυτους εις την καμινον του πυρος εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 13:43', 'Mateo', 13, 43, 'τοτε οι δικαιοι εκλαμψουσιν ως ο ηλιος εν τη βασιλεια του πατρος αυτων ο εχων ωτα ακουειν ακουετω'),
('grc_f35', 'Mateo 13:44', 'Mateo', 13, 44, 'παλιν ομοια εστιν η βασιλεια των ουρανων θησαυρω κεκρυμμενω εν αγρω ον ευρων ανθρωπος εκρυψεν και απο της χαρας αυτου υπαγει και παντα οσα εχει πωλει και αγοραζει τον αγρον εκεινον'),
('grc_f35', 'Mateo 13:45', 'Mateo', 13, 45, 'παλιν ομοια εστιν η βασιλεια των ουρανων ανθρωπω εμπορω ζητουντι καλους μαργαριτας'),
('grc_f35', 'Mateo 13:46', 'Mateo', 13, 46, 'ος ευρων ενα πολυτιμον μαργαριτην απελθων πεπρακεν παντα οσα ειχεν και ηγορασεν αυτον'),
('grc_f35', 'Mateo 13:47', 'Mateo', 13, 47, 'παλιν ομοια εστιν η βασιλεια των ουρανων σαγηνη βληθειση εις την θαλασσαν και εκ παντος γενους συναγαγουση'),
('grc_f35', 'Mateo 13:48', 'Mateo', 13, 48, 'ην οτε επληρωθη αναβιβασαντες επι τον αιγιαλον και καθισαντες συνελεξαν τα καλα εις αγγεια τα δε σαπρα εξω εβαλον'),
('grc_f35', 'Mateo 13:49', 'Mateo', 13, 49, 'ουτως εσται εν τη συντελεια του αιωνος εξελευσονται οι αγγελοι και αφοριουσιν τους πονηρους εκ μεσου των δικαιων'),
('grc_f35', 'Mateo 13:50', 'Mateo', 13, 50, 'και βαλουσιν αυτους εις την καμινον του πυρος εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 13:51', 'Mateo', 13, 51, 'λεγει αυτοις ο ιησους συνηκατε ταυτα παντα λεγουσιν αυτω ναι κυριε'),
('grc_f35', 'Mateo 13:52', 'Mateo', 13, 52, 'ο δε ειπεν αυτοις δια τουτο πας γραμματευς μαθητευθεις εις την βασιλειαν των ουρανων ομοιος εστιν ανθρωπω οικοδεσποτη οστις εκβαλλει εκ του θησαυρου αυτου καινα και παλαια'),
('grc_f35', 'Mateo 13:53', 'Mateo', 13, 53, 'και εγενετο οτε ετελεσεν ο ιησους τας παραβολας ταυτας μετηρεν εκειθεν'),
('grc_f35', 'Mateo 13:54', 'Mateo', 13, 54, 'και ελθων εις την πατριδα αυτου εδιδασκεν αυτους εν τη συναγωγη αυτων ωστε εκπληττεσθαι αυτους και λεγειν ποθεν τουτω η σοφια αυτη και αι δυναμεις'),
('grc_f35', 'Mateo 13:55', 'Mateo', 13, 55, 'ουχ ουτος εστιν ο του τεκτονος υιος ουχι η μητηρ αυτου λεγεται μαριαμ και οι αδελφοι αυτου ιακωβος και ιωσης και σιμων και ιουδας'),
('grc_f35', 'Mateo 13:56', 'Mateo', 13, 56, 'και αι αδελφαι αυτου ουχι πασαι προς ημας εισιν ποθεν ουν τουτω ταυτα παντα'),
('grc_f35', 'Mateo 13:57', 'Mateo', 13, 57, 'και εσκανδαλιζοντο εν αυτω ο δε ιησους ειπεν αυτοις ουκ εστιν προφητης ατιμος ει μη εν τη πατριδι αυτου και εν τη οικια αυτου'),
('grc_f35', 'Mateo 13:58', 'Mateo', 13, 58, 'και ουκ εποιησεν εκει δυναμεις πολλας δια την απιστιαν αυτων'),
('grc_f35', 'Mateo 14:1', 'Mateo', 14, 1, 'εν εκεινω τω καιρω ηκουσεν ηρωδης ο τετραρχης την ακοην ιησου'),
('grc_f35', 'Mateo 14:2', 'Mateo', 14, 2, 'και ειπεν τοις παισιν αυτου ουτος εστιν ιωαννης ο βαπτιστης αυτος ηγερθη απο των νεκρων και δια τουτο αι δυναμεις ενεργουσιν εν αυτω'),
('grc_f35', 'Mateo 14:3', 'Mateo', 14, 3, 'ο γαρ ηρωδης κρατησας τον ιωαννην εδησεν αυτον και εθετο εν φυλακη δια ηρωδιαδα την γυναικα φιλιππου του αδελφου αυτου'),
('grc_f35', 'Mateo 14:4', 'Mateo', 14, 4, 'ελεγεν γαρ αυτω ο ιωαννης ουκ εξεστιν σοι εχειν αυτην'),
('grc_f35', 'Mateo 14:5', 'Mateo', 14, 5, 'και θελων αυτον αποκτειναι εφοβειτο τον οχλον οτι ως προφητην αυτον ειχον'),
('grc_f35', 'Mateo 14:6', 'Mateo', 14, 6, 'γενεσιων δε αγομενων του ηρωδου ωρχησατο η θυγατηρ της ηρωδιαδος εν τω μεσω και ηρεσεν τω ηρωδη'),
('grc_f35', 'Mateo 14:7', 'Mateo', 14, 7, 'οθεν μεθ ορκου ωμολογησεν αυτη δουναι ο εαν αιτησηται'),
('grc_f35', 'Mateo 14:8', 'Mateo', 14, 8, 'η δε προβιβασθεισα υπο της μητρος αυτης δος μοι φησιν ωδε επι πινακι την κεφαλην ιωαννου του βαπτιστου'),
('grc_f35', 'Mateo 14:9', 'Mateo', 14, 9, 'και ελυπηθη ο βασιλευς δια δε τους ορκους και τους συνανακειμενους εκελευσεν δοθηναι'),
('grc_f35', 'Mateo 14:10', 'Mateo', 14, 10, 'και πεμψας απεκεφαλισεν τον ιωαννην εν τη φυλακη'),
('grc_f35', 'Mateo 14:11', 'Mateo', 14, 11, 'και ηνεχθη η κεφαλη αυτου επι πινακι και εδοθη τω κορασιω και ηνεγκεν τη μητρι αυτης'),
('grc_f35', 'Mateo 14:12', 'Mateo', 14, 12, 'και προσελθοντες οι μαθηται αυτου ηραν το σωμα και εθαψαν αυτο και ελθοντες απηγγειλαν τω ιησου'),
('grc_f35', 'Mateo 14:13', 'Mateo', 14, 13, 'και ακουσας ο ιησους ανεχωρησεν εκειθεν εν πλοιω εις ερημον τοπον κατ ιδιαν και ακουσαντες οι οχλοι ηκολουθησαν αυτω πεζη απο των πολεων'),
('grc_f35', 'Mateo 14:14', 'Mateo', 14, 14, 'και εξελθων ο ιησους ειδεν πολυν οχλον και εσπλαγχνισθη επ αυτοις και εθεραπευσεν τους αρρωστους αυτων'),
('grc_f35', 'Mateo 14:15', 'Mateo', 14, 15, 'οψιας δε γενομενης προσηλθον αυτω οι μαθηται αυτου λεγοντες ερημος εστιν ο τοπος και η ωρα ηδη παρηλθεν απολυσον τους οχλους ινα απελθοντες εις τας κωμας αγορασωσιν εαυτοις βρωματα'),
('grc_f35', 'Mateo 14:16', 'Mateo', 14, 16, 'ο δε ιησους ειπεν αυτοις ου χρειαν εχουσιν απελθειν δοτε αυτοις υμεις φαγειν'),
('grc_f35', 'Mateo 14:17', 'Mateo', 14, 17, 'οι δε λεγουσιν αυτω ουκ εχομεν ωδε ει μη πεντε αρτους και δυο ιχθυας'),
('grc_f35', 'Mateo 14:18', 'Mateo', 14, 18, 'ο δε ειπεν φερετε μοι αυτους ωδε'),
('grc_f35', 'Mateo 14:19', 'Mateo', 14, 19, 'και κελευσας τους οχλους ανακλιθηναι επι τους χορτους λαβων τους πεντε αρτους και τους δυο ιχθυας αναβλεψας εις τον ουρανον ευλογησεν και κλασας εδωκεν τοις μαθηταις τους αρτους οι δε μαθηται τοις οχλοις'),
('grc_f35', 'Mateo 14:20', 'Mateo', 14, 20, 'και εφαγον παντες και εχορτασθησαν και ηραν το περισσευον των κλασματων δωδεκα κοφινους πληρεις'),
('grc_f35', 'Mateo 14:21', 'Mateo', 14, 21, 'οι δε εσθιοντες ησαν ανδρες ωσει πεντακισχιλιοι χωρις γυναικων και παιδιων'),
('grc_f35', 'Mateo 14:22', 'Mateo', 14, 22, 'και ευθεως ηναγκασεν ο ιησους τους μαθητας αυτου εμβηναι εις το πλοιον και προαγειν αυτον εις το περαν εως ου απολυση τους οχλους'),
('grc_f35', 'Mateo 14:23', 'Mateo', 14, 23, 'και απολυσας τους οχλους ανεβη εις το ορος κατ ιδιαν προσευξασθαι οψιας δε γενομενης μονος ην εκει'),
('grc_f35', 'Mateo 14:24', 'Mateo', 14, 24, 'το δε πλοιον ηδη μεσον της θαλασσης ην βασανιζομενον υπο των κυματων ην γαρ εναντιος ο ανεμος'),
('grc_f35', 'Mateo 14:25', 'Mateo', 14, 25, 'τεταρτη δε φυλακη της νυκτος απηλθεν προς αυτους ο ιησους περιπατων επι της θαλασσης'),
('grc_f35', 'Mateo 14:26', 'Mateo', 14, 26, 'και ιδοντες αυτον οι μαθηται επι την θαλασσαν περιπατουντα εταραχθησαν λεγοντες οτι φαντασμα εστιν και απο του φοβου εκραξαν'),
('grc_f35', 'Mateo 14:27', 'Mateo', 14, 27, 'ευθεως δε ελαλησεν αυτοις ο ιησους λεγων θαρσειτε εγω ειμι μη φοβεισθε'),
('grc_f35', 'Mateo 14:28', 'Mateo', 14, 28, 'αποκριθεις δε ο πετρος ειπεν κυριε ει συ ει κελευσον με προς σε ελθειν επι τα υδατα'),
('grc_f35', 'Mateo 14:29', 'Mateo', 14, 29, 'ο δε ειπεν ελθε και καταβας απο του πλοιου ο πετρος περιεπατησεν επι τα υδατα ελθειν προς τον ιησουν'),
('grc_f35', 'Mateo 14:30', 'Mateo', 14, 30, 'βλεπων δε τον ανεμον ισχυρον εφοβηθη και αρξαμενος καταποντιζεσθαι εκραξεν λεγων κυριε σωσον με'),
('grc_f35', 'Mateo 14:31', 'Mateo', 14, 31, 'και ευθεως ο ιησους εκτεινας την χειρα επελαβετο αυτου και λεγει αυτω ολιγοπιστε εις τι εδιστασας'),
('grc_f35', 'Mateo 14:32', 'Mateo', 14, 32, 'και εμβαντων αυτων εις το πλοιον εκοπασεν ο ανεμος'),
('grc_f35', 'Mateo 14:33', 'Mateo', 14, 33, 'οι δε εν τω πλοιω ελθοντες προσεκυνησαν αυτω λεγοντες αληθως θεου υιος ει'),
('grc_f35', 'Mateo 14:34', 'Mateo', 14, 34, 'και διαπερασαντες ηλθον εις την γην γενησαρετ'),
('grc_f35', 'Mateo 14:35', 'Mateo', 14, 35, 'και επιγνοντες αυτον οι ανδρες του τοπου εκεινου απεστειλαν εις ολην την περιχωρον εκεινην και προσηνεγκαν αυτω παντας τους κακως εχοντας'),
('grc_f35', 'Mateo 14:36', 'Mateo', 14, 36, 'και παρεκαλουν αυτον ινα καν μονον αψωνται του κρασπεδου του ιματιου αυτου και οσοι ηψαντο διεσωθησαν'),
('grc_f35', 'Mateo 15:1', 'Mateo', 15, 1, 'τοτε προσερχονται τω ιησου οι απο ιεροσολυμων γραμματεις και φαρισαιοι λεγοντες'),
('grc_f35', 'Mateo 15:2', 'Mateo', 15, 2, 'δια τι οι μαθηται σου παραβαινουσιν την παραδοσιν των πρεσβυτερων ου γαρ νιπτονται τας χειρας αυτων οταν αρτον εσθιωσιν'),
('grc_f35', 'Mateo 15:3', 'Mateo', 15, 3, 'ο δε αποκριθεις ειπεν αυτοις δια τι και υμεις παραβαινετε την εντολην του θεου δια την παραδοσιν υμων'),
('grc_f35', 'Mateo 15:4', 'Mateo', 15, 4, 'ο γαρ θεος ενετειλατο λεγων τιμα τον πατερα και την μητερα και ο κακολογων πατερα η μητερα θανατω τελευτατω'),
('grc_f35', 'Mateo 15:5', 'Mateo', 15, 5, 'υμεις δε λεγετε ος αν ειπη τω πατρι η τη μητρι δωρον ο εαν εξ εμου ωφεληθης'),
('grc_f35', 'Mateo 15:6', 'Mateo', 15, 6, 'και ου μη τιμηση τον πατερα αυτου η την μητερα και ηκυρωσατε την εντολην του θεου δια την παραδοσιν υμων'),
('grc_f35', 'Mateo 15:7', 'Mateo', 15, 7, 'υποκριται καλως προεφητευσεν περι υμων ησαιας λεγων'),
('grc_f35', 'Mateo 15:8', 'Mateo', 15, 8, 'εγγιζει μοι ο λαος ουτος τω στοματι αυτων και τοις χειλεσιν με τιμα η δε καρδια αυτων πορρω απεχει απ εμου'),
('grc_f35', 'Mateo 15:9', 'Mateo', 15, 9, 'ματην δε σεβονται με διδασκοντες διδασκαλιας ενταλματα ανθρωπων'),
('grc_f35', 'Mateo 15:10', 'Mateo', 15, 10, 'και προσκαλεσαμενος τον οχλον ειπεν αυτοις ακουετε και συνιετε'),
('grc_f35', 'Mateo 15:11', 'Mateo', 15, 11, 'ου το εισερχομενον εις το στομα κοινοι τον ανθρωπον αλλα το εκπορευομενον εκ του στοματος τουτο κοινοι τον ανθρωπον'),
('grc_f35', 'Mateo 15:12', 'Mateo', 15, 12, 'τοτε προσελθοντες οι μαθηται αυτου ειπον αυτω οιδας οτι οι φαρισαιοι ακουσαντες τον λογον εσκανδαλισθησαν'),
('grc_f35', 'Mateo 15:13', 'Mateo', 15, 13, 'ο δε αποκριθεις ειπεν πασα φυτεια ην ουκ εφυτευσεν ο πατηρ μου ο ουρανιος εκριζωθησεται'),
('grc_f35', 'Mateo 15:14', 'Mateo', 15, 14, 'αφετε αυτους οδηγοι εισιν τυφλοι τυφλων τυφλος δε τυφλον εαν οδηγη αμφοτεροι εις βοθυνον εμπεσουνται'),
('grc_f35', 'Mateo 15:15', 'Mateo', 15, 15, 'αποκριθεις δε ο πετρος ειπεν αυτω φρασον ημιν την παραβολην ταυτην'),
('grc_f35', 'Mateo 15:16', 'Mateo', 15, 16, 'ο δε ιησους ειπεν ακμην και υμεις ασυνετοι εστε'),
('grc_f35', 'Mateo 15:17', 'Mateo', 15, 17, 'ουπω νοειτε οτι παν το εισπορευομενον εις το στομα εις την κοιλιαν χωρει και εις αφεδρωνα εκβαλλεται'),
('grc_f35', 'Mateo 15:18', 'Mateo', 15, 18, 'τα δε εκπορευομενα εκ του στοματος εκ της καρδιας εξερχεται κακεινα κοινοι τον ανθρωπον'),
('grc_f35', 'Mateo 15:19', 'Mateo', 15, 19, 'εκ γαρ της καρδιας εξερχονται διαλογισμοι πονηροι φονοι μοιχειαι πορνειαι κλοπαι ψευδομαρτυριαι βλασφημιαι'),
('grc_f35', 'Mateo 15:20', 'Mateo', 15, 20, 'ταυτα εστιν τα κοινουντα τον ανθρωπον το δε ανιπτοις χερσιν φαγειν ου κοινοι τον ανθρωπον'),
('grc_f35', 'Mateo 15:21', 'Mateo', 15, 21, 'και εξελθων εκειθεν ο ιησους ανεχωρησεν εις τα μερη τυρου και σιδωνος'),
('grc_f35', 'Mateo 15:22', 'Mateo', 15, 22, 'και ιδου γυνη χαναναια απο των οριων εκεινων εξελθουσα εκραυγασεν αυτω λεγουσα ελεησον με κυριε υιε δαυιδ η θυγατηρ μου κακως δαιμονιζεται'),
('grc_f35', 'Mateo 15:23', 'Mateo', 15, 23, 'ο δε ουκ απεκριθη αυτη λογον και προσελθοντες οι μαθηται αυτου ηρωτων αυτον λεγοντες απολυσον αυτην οτι κραζει οπισθεν ημων'),
('grc_f35', 'Mateo 15:24', 'Mateo', 15, 24, 'ο δε αποκριθεις ειπεν ουκ απεσταλην ει μη εις τα προβατα τα απολωλοτα οικου ισραηλ'),
('grc_f35', 'Mateo 15:25', 'Mateo', 15, 25, 'η δε ελθουσα προσεκυνησεν αυτω λεγουσα κυριε βοηθει μοι'),
('grc_f35', 'Mateo 15:26', 'Mateo', 15, 26, 'ο δε αποκριθεις ειπεν ουκ εστιν καλον λαβειν τον αρτον των τεκνων και βαλειν τοις κυναριοις'),
('grc_f35', 'Mateo 15:27', 'Mateo', 15, 27, 'η δε ειπεν ναι κυριε και γαρ τα κυναρια εσθιει απο των ψιχιων των πιπτοντων απο της τραπεζης των κυριων αυτων'),
('grc_f35', 'Mateo 15:28', 'Mateo', 15, 28, 'τοτε αποκριθεις ο ιησους ειπεν αυτη ω γυναι μεγαλη σου η πιστις γενηθητω σοι ως θελεις και ιαθη η θυγατηρ αυτης απο της ωρας εκεινης'),
('grc_f35', 'Mateo 15:29', 'Mateo', 15, 29, 'και μεταβας εκειθεν ο ιησους ηλθεν παρα την θαλασσαν της γαλιλαιας και αναβας εις το ορος εκαθητο εκει'),
('grc_f35', 'Mateo 15:30', 'Mateo', 15, 30, 'και προσηλθον αυτω οχλοι πολλοι εχοντες μεθ εαυτων χωλους τυφλους κωφους κυλλους και ετερους πολλους και ερριψαν αυτους παρα τους ποδας του ιησου και εθεραπευσεν αυτους'),
('grc_f35', 'Mateo 15:31', 'Mateo', 15, 31, 'ωστε τους οχλους θαυμασαι βλεποντας κωφους λαλουντας κυλλους υγιεις χωλους περιπατουντας και τυφλους βλεποντας και εδοξαζον τον θεον ισραηλ'),
('grc_f35', 'Mateo 15:32', 'Mateo', 15, 32, 'ο δε ιησους προσκαλεσαμενος τους μαθητας αυτου ειπεν σπλαγχνιζομαι επι τον οχλον οτι ηδη ημερας τρεις προσμενουσιν μοι και ουκ εχουσιν τι φαγωσιν και απολυσαι αυτους νηστις ου θελω μηποτε εκλυθωσιν εν τη οδω'),
('grc_f35', 'Mateo 15:33', 'Mateo', 15, 33, 'και λεγουσιν αυτω οι μαθηται αυτου ποθεν ημιν εν ερημια αρτοι τοσουτοι ωστε χορτασαι οχλον τοσουτον'),
('grc_f35', 'Mateo 15:34', 'Mateo', 15, 34, 'και λεγει αυτοις ο ιησους ποσους αρτους εχετε οι δε ειπον επτα και ολιγα ιχθυδια'),
('grc_f35', 'Mateo 15:35', 'Mateo', 15, 35, 'και εκελευσεν τοις οχλοις αναπεσειν επι την γην'),
('grc_f35', 'Mateo 15:36', 'Mateo', 15, 36, 'και λαβων τους επτα αρτους και τους ιχθυας ευχαριστησας εκλασεν και εδωκεν τοις μαθηταις αυτου οι δε μαθηται τω οχλω'),
('grc_f35', 'Mateo 15:37', 'Mateo', 15, 37, 'και εφαγον παντες και εχορτασθησαν και ηραν το περισσευον των κλασματων επτα σπυριδας πληρεις'),
('grc_f35', 'Mateo 15:38', 'Mateo', 15, 38, 'οι δε εσθιοντες ησαν τετρακισχιλιοι ανδρες χωρις γυναικων και παιδιων'),
('grc_f35', 'Mateo 15:39', 'Mateo', 15, 39, 'και απολυσας τους οχλους ενεβη εις το πλοιον και ηλθεν εις τα ορια μαγδαλα'),
('grc_f35', 'Mateo 16:1', 'Mateo', 16, 1, 'και προσελθοντες οι φαρισαιοι και σαδδουκαιοι πειραζοντες επηρωτησαν αυτον σημειον εκ του ουρανου επιδειξαι αυτοις'),
('grc_f35', 'Mateo 16:2', 'Mateo', 16, 2, 'ο δε αποκριθεις ειπεν αυτοις οψιας γενομενης λεγετε ευδια πυρραζει γαρ ο ουρανος'),
('grc_f35', 'Mateo 16:3', 'Mateo', 16, 3, 'και πρωι σημερον χειμων πυρραζει γαρ στυγναζων ο ουρανος υποκριται το μεν προσωπον του ουρανου γινωσκετε διακρινειν τα δε σημεια των καιρων ου δυνασθε'),
('grc_f35', 'Mateo 16:4', 'Mateo', 16, 4, 'γενεα πονηρα και μοιχαλις σημειον επιζητει και σημειον ου δοθησεται αυτη ει μη το σημειον ιωνα του προφητου και καταλιπων αυτους απηλθεν'),
('grc_f35', 'Mateo 16:5', 'Mateo', 16, 5, 'και ελθοντες οι μαθηται αυτου εις το περαν επελαθοντο αρτους λαβειν'),
('grc_f35', 'Mateo 16:6', 'Mateo', 16, 6, 'ο δε ιησους ειπεν αυτοις ορατε και προσεχετε απο της ζυμης των φαρισαιων και σαδδουκαιων'),
('grc_f35', 'Mateo 16:7', 'Mateo', 16, 7, 'οι δε διελογιζοντο εν εαυτοις λεγοντες οτι αρτους ουκ ελαβομεν'),
('grc_f35', 'Mateo 16:8', 'Mateo', 16, 8, 'γνους δε ο ιησους ειπεν αυτοις τι διαλογιζεσθε εν εαυτοις ολιγοπιστοι οτι αρτους ουκ ελαβετε'),
('grc_f35', 'Mateo 16:9', 'Mateo', 16, 9, 'ουπω νοειτε ουδε μνημονευετε τους πεντε αρτους των πεντακισχιλιων και ποσους κοφινους ελαβετε'),
('grc_f35', 'Mateo 16:10', 'Mateo', 16, 10, 'ουδε τους επτα αρτους των τετρακισχιλιων και ποσας σπυριδας ελαβετε'),
('grc_f35', 'Mateo 16:11', 'Mateo', 16, 11, 'πως ου νοειτε οτι ου περι αρτου ειπον υμιν προσεχειν απο της ζυμης των φαρισαιων και σαδδουκαιων'),
('grc_f35', 'Mateo 16:12', 'Mateo', 16, 12, 'τοτε συνηκαν οτι ουκ ειπεν προσεχειν απο της ζυμης του αρτου αλλα απο της διδαχης των φαρισαιων και σαδδουκαιων'),
('grc_f35', 'Mateo 16:13', 'Mateo', 16, 13, 'ελθων δε ο ιησους εις τα μερη καισαρειας της φιλιππου ηρωτα τους μαθητας αυτου λεγων τινα με λεγουσιν οι ανθρωποι ειναι τον υιον του ανθρωπου'),
('grc_f35', 'Mateo 16:14', 'Mateo', 16, 14, 'οι δε ειπον οι μεν ιωαννην τον βαπτιστην αλλοι δε ηλιαν ετεροι δε ιερεμιαν η ενα των προφητων'),
('grc_f35', 'Mateo 16:15', 'Mateo', 16, 15, 'λεγει αυτοις υμεις δε τινα με λεγετε ειναι'),
('grc_f35', 'Mateo 16:16', 'Mateo', 16, 16, 'αποκριθεις δε σιμων πετρος ειπεν συ ει ο χριστος ο υιος του θεου του ζωντος'),
('grc_f35', 'Mateo 16:17', 'Mateo', 16, 17, 'και αποκριθεις ο ιησους ειπεν αυτω μακαριος ει σιμων βαριωνα οτι σαρξ και αιμα ουκ απεκαλυψεν σοι αλλ ο πατηρ μου ο εν τοις ουρανοις'),
('grc_f35', 'Mateo 16:18', 'Mateo', 16, 18, 'καγω δε σοι λεγω οτι συ ει πετρος και επι ταυτη τη πετρα οικοδομησω μου την εκκλησιαν και πυλαι αδου ου κατισχυσουσιν αυτης'),
('grc_f35', 'Mateo 16:19', 'Mateo', 16, 19, 'και δωσω σοι τας κλεις της βασιλειας των ουρανων και ο εαν δησης επι της γης εσται δεδεμενον εν τοις ουρανοις και ο εαν λυσης επι της γης εσται λελυμενον εν τοις ουρανοις'),
('grc_f35', 'Mateo 16:20', 'Mateo', 16, 20, 'τοτε διεστειλατο τοις μαθηταις αυτου ινα μηδενι ειπωσιν οτι αυτος εστιν ο χριστος'),
('grc_f35', 'Mateo 16:21', 'Mateo', 16, 21, 'απο τοτε ηρξατο ο ιησους δεικνυειν τοις μαθηταις αυτου οτι δει αυτον απελθειν εις ιεροσολυμα και πολλα παθειν απο των πρεσβυτερων και αρχιερεων και γραμματεων και αποκτανθηναι και τη τριτη ημερα εγερθηναι'),
('grc_f35', 'Mateo 16:22', 'Mateo', 16, 22, 'και προσλαβομενος αυτον ο πετρος ηρξατο επιτιμαν αυτω λεγων ιλεως σοι κυριε ου μη εσται σοι τουτο'),
('grc_f35', 'Mateo 16:23', 'Mateo', 16, 23, 'ο δε στραφεις ειπεν τω πετρω υπαγε οπισω μου σατανα σκανδαλον μου ει οτι ου φρονεις τα του θεου αλλα τα των ανθρωπων'),
('grc_f35', 'Mateo 16:24', 'Mateo', 16, 24, 'τοτε ο ιησους ειπεν τοις μαθηταις αυτου ει τις θελει οπισω μου ελθειν απαρνησασθω εαυτον και αρατω τον σταυρον αυτου και ακολουθειτω μοι'),
('grc_f35', 'Mateo 16:25', 'Mateo', 16, 25, 'ος γαρ αν θελη την ψυχην αυτου σωσαι απολεσει αυτην ος δ αν απολεση την ψυχην αυτου ενεκεν εμου ευρησει αυτην'),
('grc_f35', 'Mateo 16:26', 'Mateo', 16, 26, 'τι γαρ ωφελειται ανθρωπος εαν τον κοσμον ολον κερδηση την δε ψυχην αυτου ζημιωθη η τι δωσει ανθρωπος ανταλλαγμα της ψυχης αυτου'),
('grc_f35', 'Mateo 16:27', 'Mateo', 16, 27, 'μελλει γαρ ο υιος του ανθρωπου ερχεσθαι εν τη δοξη του πατρος αυτου μετα των αγγελων αυτου και τοτε αποδωσει εκαστω κατα την πραξιν αυτου'),
('grc_f35', 'Mateo 16:28', 'Mateo', 16, 28, 'αμην λεγω υμιν εισιν τινες ωδε εστωτες οιτινες ου μη γευσωνται θανατου εως αν ιδωσιν τον υιον του ανθρωπου ερχομενον εν τη βασιλεια αυτου'),
('grc_f35', 'Mateo 17:1', 'Mateo', 17, 1, 'και μεθ ημερας εξ παραλαμβανει ο ιησους τον πετρον και ιακωβον και ιωαννην τον αδελφον αυτου και αναφερει αυτους εις ορος υψηλον κατ ιδιαν'),
('grc_f35', 'Mateo 17:2', 'Mateo', 17, 2, 'και μετεμορφωθη εμπροσθεν αυτων και ελαμψεν το προσωπον αυτου ως ο ηλιος τα δε ιματια αυτου εγενετο λευκα ως το φως'),
('grc_f35', 'Mateo 17:3', 'Mateo', 17, 3, 'και ιδου ωφθησαν αυτοις μωσης και ηλιας μετ αυτου συλλαλουντες'),
('grc_f35', 'Mateo 17:4', 'Mateo', 17, 4, 'αποκριθεις δε ο πετρος ειπεν τω ιησου κυριε καλον εστιν ημας ωδε ειναι ει θελεις ποιησωμεν ωδε τρεις σκηνας σοι μιαν και μωσει μιαν και μιαν ηλια'),
('grc_f35', 'Mateo 17:5', 'Mateo', 17, 5, 'ετι αυτου λαλουντος ιδου νεφελη φωτεινη επεσκιασεν αυτους και ιδου φωνη εκ της νεφελης λεγουσα ουτος εστιν ο υιος μου ο αγαπητος εν ω ευδοκησα αυτου ακουετε'),
('grc_f35', 'Mateo 17:6', 'Mateo', 17, 6, 'και ακουσαντες οι μαθηται επεσον επι προσωπον αυτων και εφοβηθησαν σφοδρα'),
('grc_f35', 'Mateo 17:7', 'Mateo', 17, 7, 'και προσελθων ο ιησους ηψατο αυτων και ειπεν εγερθητε και μη φοβεισθε'),
('grc_f35', 'Mateo 17:8', 'Mateo', 17, 8, 'επαραντες δε τους οφθαλμους αυτων ουδενα ειδον ει μη τον ιησουν μονον'),
('grc_f35', 'Mateo 17:9', 'Mateo', 17, 9, 'και καταβαινοντων αυτων εκ του ορους ενετειλατο αυτοις ο ιησους λεγων μηδενι ειπητε το οραμα εως ου ο υιος του ανθρωπου εκ νεκρων αναστη'),
('grc_f35', 'Mateo 17:10', 'Mateo', 17, 10, 'και επηρωτησαν αυτον οι μαθηται αυτου λεγοντες τι ουν οι γραμματεις λεγουσιν οτι ηλιαν δει ελθειν πρωτον'),
('grc_f35', 'Mateo 17:11', 'Mateo', 17, 11, 'ο δε ιησους αποκριθεις ειπεν αυτοις ηλιας μεν ερχεται πρωτον και αποκαταστησει παντα'),
('grc_f35', 'Mateo 17:12', 'Mateo', 17, 12, 'λεγω δε υμιν οτι ηλιας ηδη ηλθεν και ουκ επεγνωσαν αυτον αλλ εποιησαν εν αυτω οσα ηθελησαν ουτως και ο υιος του ανθρωπου μελλει πασχειν υπ αυτων'),
('grc_f35', 'Mateo 17:13', 'Mateo', 17, 13, 'τοτε συνηκαν οι μαθηται οτι περι ιωαννου του βαπτιστου ειπεν αυτοις'),
('grc_f35', 'Mateo 17:14', 'Mateo', 17, 14, 'και ελθοντων αυτων προς τον οχλον προσηλθεν αυτω ανθρωπος γονυπετων αυτον και λεγων'),
('grc_f35', 'Mateo 17:15', 'Mateo', 17, 15, 'κυριε ελεησον μου τον υιον οτι σεληνιαζεται και κακως πασχει πολλακις γαρ πιπτει εις το πυρ και πολλακις εις το υδωρ'),
('grc_f35', 'Mateo 17:16', 'Mateo', 17, 16, 'και προσηνεγκα αυτον τοις μαθηταις σου και ουκ ηδυνηθησαν αυτον θεραπευσαι'),
('grc_f35', 'Mateo 17:17', 'Mateo', 17, 17, 'αποκριθεις δε ο ιησους ειπεν ω γενεα απιστος και διεστραμμενη εως ποτε εσομαι μεθ υμων εως ποτε ανεξομαι υμων φερετε μοι αυτον ωδε'),
('grc_f35', 'Mateo 17:18', 'Mateo', 17, 18, 'και επετιμησεν αυτω ο ιησους και εξηλθεν απ αυτου το δαιμονιον και ιαθη ο παις απο της ωρας εκεινης'),
('grc_f35', 'Mateo 17:19', 'Mateo', 17, 19, 'τοτε προσελθοντες οι μαθηται τω ιησου κατ ιδιαν ειπον δια τι ημεις ουκ ηδυνηθημεν εκβαλειν αυτο'),
('grc_f35', 'Mateo 17:20', 'Mateo', 17, 20, 'ο δε ιησους ειπεν αυτοις δια την απιστιαν υμων αμην γαρ λεγω υμιν εαν εχητε πιστιν ως κοκκον σιναπεως ερειτε τω ορει τουτω μεταβηθι εντευθεν εκει και μεταβησεται και ουδεν αδυνατησει υμιν'),
('grc_f35', 'Mateo 17:21', 'Mateo', 17, 21, 'τουτο δε το γενος ουκ εκπορευεται ει μη εν προσευχη και νηστεια'),
('grc_f35', 'Mateo 17:22', 'Mateo', 17, 22, 'αναστρεφομενων δε αυτων εν τη γαλιλαια ειπεν αυτοις ο ιησους μελλει ο υιος του ανθρωπου παραδιδοσθαι εις χειρας ανθρωπων'),
('grc_f35', 'Mateo 17:23', 'Mateo', 17, 23, 'και αποκτενουσιν αυτον και τη τριτη ημερα εγερθησεται και ελυπηθησαν σφοδρα'),
('grc_f35', 'Mateo 17:24', 'Mateo', 17, 24, 'ελθοντων δε αυτων εις καπερναουμ προσηλθον οι τα διδραχμα λαμβανοντες τω πετρω και ειπον ο διδασκαλος υμων ου τελει τα διδραχμα'),
('grc_f35', 'Mateo 17:25', 'Mateo', 17, 25, 'λεγει ναι και οτε εισηλθον εις την οικιαν προεφθασεν αυτον ο ιησους λεγων τι σοι δοκει σιμων οι βασιλεις της γης απο τινων λαμβανουσιν τελη η κηνσον απο των υιων αυτων η απο των αλλοτριων'),
('grc_f35', 'Mateo 17:26', 'Mateo', 17, 26, 'λεγει αυτω ο πετρος απο των αλλοτριων εφη αυτω ο ιησους αρα γε ελευθεροι εισιν οι υιοι'),
('grc_f35', 'Mateo 17:27', 'Mateo', 17, 27, 'ινα δε μη σκανδαλισωμεν αυτους πορευθεις εις την θαλασσαν βαλε αγκιστρον και τον αναβαντα πρωτον ιχθυν αρον και ανοιξας το στομα αυτου ευρησεις στατηρα εκεινον λαβων δος αυτοις αντι εμου και σου'),
('grc_f35', 'Mateo 18:1', 'Mateo', 18, 1, 'εν εκεινη τη ωρα προσηλθον οι μαθηται τω ιησου λεγοντες τις αρα μειζων εστιν εν τη βασιλεια των ουρανων'),
('grc_f35', 'Mateo 18:2', 'Mateo', 18, 2, 'και προσκαλεσαμενος ο ιησους παιδιον εστησεν αυτο εν μεσω αυτων'),
('grc_f35', 'Mateo 18:3', 'Mateo', 18, 3, 'και ειπεν αμην λεγω υμιν εαν μη στραφητε και γενησθε ως τα παιδια ου μη εισελθητε εις την βασιλειαν των ουρανων'),
('grc_f35', 'Mateo 18:4', 'Mateo', 18, 4, 'οστις ουν ταπεινωσει εαυτον ως το παιδιον τουτο ουτος εστιν ο μειζων εν τη βασιλεια των ουρανων'),
('grc_f35', 'Mateo 18:5', 'Mateo', 18, 5, 'και ος εαν δεξηται παιδιον τοιουτον εν επι τω ονοματι μου εμε δεχεται'),
('grc_f35', 'Mateo 18:6', 'Mateo', 18, 6, 'ος δ αν σκανδαλιση ενα των μικρων τουτων των πιστευοντων εις εμε συμφερει αυτω ινα κρεμασθη μυλος ονικος εις τον τραχηλον αυτου και καταποντισθη εν τω πελαγει της θαλασσης'),
('grc_f35', 'Mateo 18:7', 'Mateo', 18, 7, 'ουαι τω κοσμω απο των σκανδαλων αναγκη γαρ εστιν ελθειν τα σκανδαλα πλην ουαι τω ανθρωπω εκεινω δι ου το σκανδαλον ερχεται'),
('grc_f35', 'Mateo 18:8', 'Mateo', 18, 8, 'ει δε η χειρ σου η ο πους σου σκανδαλιζει σε εκκοψον αυτα και βαλε απο σου καλον σοι εστιν εισελθειν εις την ζωην χωλον η κυλλον η δυο χειρας η δυο ποδας εχοντα βληθηναι εις το πυρ το αιωνιον'),
('grc_f35', 'Mateo 18:9', 'Mateo', 18, 9, 'και ει ο οφθαλμος σου σκανδαλιζει σε εξελε αυτον και βαλε απο σου καλον σοι εστιν μονοφθαλμον εις την ζωην εισελθειν η δυο οφθαλμους εχοντα βληθηναι εις την γεενναν του πυρος'),
('grc_f35', 'Mateo 18:10', 'Mateo', 18, 10, 'ορατε μη καταφρονησητε ενος των μικρων τουτων λεγω γαρ υμιν οτι οι αγγελοι αυτων εν ουρανοις δια παντος βλεπουσιν το προσωπον του πατρος μου του εν ουρανοις'),
('grc_f35', 'Mateo 18:11', 'Mateo', 18, 11, 'ηλθεν γαρ ο υιος του ανθρωπου σωσαι το απολωλος'),
('grc_f35', 'Mateo 18:12', 'Mateo', 18, 12, 'τι υμιν δοκει εαν γενηται τινι ανθρωπω εκατον προβατα και πλανηθη εν εξ αυτων ουχι αφεις τα ενενηκοντα εννεα επι τα ορη πορευθεις ζητει το πλανωμενον'),
('grc_f35', 'Mateo 18:13', 'Mateo', 18, 13, 'και εαν γενηται ευρειν αυτο αμην λεγω υμιν οτι χαιρει επ αυτω μαλλον η επι τοις ενενηκοντα εννεα τοις μη πεπλανημενοις'),
('grc_f35', 'Mateo 18:14', 'Mateo', 18, 14, 'ουτως ουκ εστιν θελημα εμπροσθεν του πατρος υμων του εν ουρανοις ινα αποληται εις των μικρων τουτων'),
('grc_f35', 'Mateo 18:15', 'Mateo', 18, 15, 'εαν δε αμαρτη εις σε ο αδελφος σου υπαγε ελεγξον αυτον μεταξυ σου και αυτου μονου εαν σου ακουση εκερδησας τον αδελφον σου'),
('grc_f35', 'Mateo 18:16', 'Mateo', 18, 16, 'εαν δε μη ακουση παραλαβε μετα σου ετι ενα η δυο ινα επι στοματος δυο μαρτυρων η τριων σταθη παν ρημα'),
('grc_f35', 'Mateo 18:17', 'Mateo', 18, 17, 'εαν δε παρακουση αυτων ειπε τη εκκλησια εαν δε και της εκκλησιας παρακουση εστω σοι ωσπερ ο εθνικος και ο τελωνης'),
('grc_f35', 'Mateo 18:18', 'Mateo', 18, 18, 'αμην λεγω υμιν οσα εαν δησητε επι της γης εσται δεδεμενα εν τω ουρανω και οσα εαν λυσητε επι της γης εσται λελυμενα εν τω ουρανω'),
('grc_f35', 'Mateo 18:19', 'Mateo', 18, 19, 'παλιν αμην λεγω υμιν οτι εαν δυο υμων συμφωνησωσιν επι της γης περι παντος πραγματος ου εαν αιτησωνται γενησεται αυτοις παρα του πατρος μου του εν ουρανοις'),
('grc_f35', 'Mateo 18:20', 'Mateo', 18, 20, 'ου γαρ εισιν δυο η τρεις συνηγμενοι εις το εμον ονομα εκει ειμι εν μεσω αυτων'),
('grc_f35', 'Mateo 18:21', 'Mateo', 18, 21, 'τοτε προσελθων αυτω ο πετρος ειπεν κυριε ποσακις αμαρτησει εις εμε ο αδελφος μου και αφησω αυτω εως επτακις'),
('grc_f35', 'Mateo 18:22', 'Mateo', 18, 22, 'λεγει αυτω ο ιησους ου λεγω σοι εως επτακις αλλ εως εβδομηκοντακις επτα'),
('grc_f35', 'Mateo 18:23', 'Mateo', 18, 23, 'δια τουτο ωμοιωθη η βασιλεια των ουρανων ανθρωπω βασιλει ος ηθελησεν συναραι λογον μετα των δουλων αυτου'),
('grc_f35', 'Mateo 18:24', 'Mateo', 18, 24, 'αρξαμενου δε αυτου συναιρειν προσηνεχθη αυτω εις οφειλετης μυριων ταλαντων'),
('grc_f35', 'Mateo 18:25', 'Mateo', 18, 25, 'μη εχοντος δε αυτου αποδουναι εκελευσεν αυτον ο κυριος αυτου πραθηναι και την γυναικα αυτου και τα τεκνα και παντα οσα ειχεν και αποδοθηναι'),
('grc_f35', 'Mateo 18:26', 'Mateo', 18, 26, 'πεσων ουν ο δουλος προσεκυνει αυτω λεγων κυριε μακροθυμησον επ εμοι και παντα σοι αποδωσω'),
('grc_f35', 'Mateo 18:27', 'Mateo', 18, 27, 'σπλαγχνισθεις δε ο κυριος του δουλου εκεινου απελυσεν αυτον και το δανειον αφηκεν αυτω'),
('grc_f35', 'Mateo 18:28', 'Mateo', 18, 28, 'εξελθων δε ο δουλος εκεινος ευρεν ενα των συνδουλων αυτου ος ωφειλεν αυτω εκατον δηναρια και κρατησας αυτον επνιγεν λεγων αποδος μοι ει τι οφειλεις'),
('grc_f35', 'Mateo 18:29', 'Mateo', 18, 29, 'πεσων ουν ο συνδουλος αυτου εις τους ποδας αυτου παρεκαλει αυτον λεγων μακροθυμησον επ εμοι και αποδωσω σοι'),
('grc_f35', 'Mateo 18:30', 'Mateo', 18, 30, 'ο δε ουκ ηθελεν αλλα απελθων εβαλεν αυτον εις φυλακην εως ου αποδω το οφειλομενον'),
('grc_f35', 'Mateo 18:31', 'Mateo', 18, 31, 'ιδοντες δε οι συνδουλοι αυτου τα γενομενα ελυπηθησαν σφοδρα και ελθοντες διεσαφησαν τω κυριω εαυτων παντα τα γενομενα'),
('grc_f35', 'Mateo 18:32', 'Mateo', 18, 32, 'τοτε προσκαλεσαμενος αυτον ο κυριος αυτου λεγει αυτω δουλε πονηρε πασαν την οφειλην εκεινην αφηκα σοι επει παρεκαλεσας με'),
('grc_f35', 'Mateo 18:33', 'Mateo', 18, 33, 'ουκ εδει και σε ελεησαι τον συνδουλον σου ως και εγω σε ηλεησα'),
('grc_f35', 'Mateo 18:34', 'Mateo', 18, 34, 'και οργισθεις ο κυριος αυτου παρεδωκεν αυτον τοις βασανισταις εως ου αποδω παν το οφειλομενον αυτω'),
('grc_f35', 'Mateo 18:35', 'Mateo', 18, 35, 'ουτως και ο πατηρ μου ο επουρανιος ποιησει υμιν εαν μη αφητε εκαστος τω αδελφω αυτου απο των καρδιων υμων τα παραπτωματα αυτων'),
('grc_f35', 'Mateo 19:1', 'Mateo', 19, 1, 'και εγενετο οτε ετελεσεν ο ιησους τους λογους τουτους μετηρεν απο της γαλιλαιας και ηλθεν εις τα ορια της ιουδαιας περαν του ιορδανου'),
('grc_f35', 'Mateo 19:2', 'Mateo', 19, 2, 'και ηκολουθησαν αυτω οχλοι πολλοι και εθεραπευσεν αυτους εκει'),
('grc_f35', 'Mateo 19:3', 'Mateo', 19, 3, 'και προσηλθον αυτω οι φαρισαιοι πειραζοντες αυτον και λεγοντες αυτω ει εξεστιν ανθρωπω απολυσαι την γυναικα αυτου κατα πασαν αιτιαν'),
('grc_f35', 'Mateo 19:4', 'Mateo', 19, 4, 'ο δε αποκριθεις ειπεν αυτοις ουκ ανεγνωτε οτι ο ποιησας απ αρχης αρσεν και θηλυ εποιησεν αυτους'),
('grc_f35', 'Mateo 19:5', 'Mateo', 19, 5, 'και ειπεν ενεκεν τουτου καταλειψει ανθρωπος τον πατερα αυτου και την μητερα και προσκολληθησεται προς την γυναικα αυτου και εσονται οι δυο εις σαρκα μιαν'),
('grc_f35', 'Mateo 19:6', 'Mateo', 19, 6, 'ωστε ουκετι εισιν δυο αλλα σαρξ μια ο ουν ο θεος συνεζευξεν ανθρωπος μη χωριζετω'),
('grc_f35', 'Mateo 19:7', 'Mateo', 19, 7, 'λεγουσιν αυτω τι ουν μωσης ενετειλατο δουναι βιβλιον αποστασιου και απολυσαι αυτην'),
('grc_f35', 'Mateo 19:8', 'Mateo', 19, 8, 'λεγει αυτοις οτι μωσης προς την σκληροκαρδιαν υμων επετρεψεν υμιν απολυσαι τας γυναικας υμων απ αρχης δε ου γεγονεν ουτως'),
('grc_f35', 'Mateo 19:9', 'Mateo', 19, 9, 'λεγω δε υμιν οτι ος αν απολυση την γυναικα αυτου μη επι πορνεια και γαμηση αλλην μοιχαται και ο απολελυμενην γαμησας μοιχαται'),
('grc_f35', 'Mateo 19:10', 'Mateo', 19, 10, 'λεγουσιν αυτω οι μαθηται αυτου ει ουτως εστιν η αιτια του ανθρωπου μετα της γυναικος ου συμφερει γαμησαι'),
('grc_f35', 'Mateo 19:11', 'Mateo', 19, 11, 'ο δε ειπεν αυτοις ου παντες χωρουσιν τον λογον τουτον αλλ οις δεδοται'),
('grc_f35', 'Mateo 19:12', 'Mateo', 19, 12, 'εισιν γαρ ευνουχοι οιτινες εκ κοιλιας μητρος εγεννηθησαν ουτως και εισιν ευνουχοι οιτινες ευνουχισθησαν υπο των ανθρωπων και εισιν ευνουχοι οιτινες ευνουχισαν εαυτους δια την βασιλειαν των ουρανων ο δυναμενος χωρειν χωρειτω'),
('grc_f35', 'Mateo 19:13', 'Mateo', 19, 13, 'τοτε προσηνεχθη αυτω παιδια ινα τας χειρας επιθη αυτοις και προσευξηται οι δε μαθηται επετιμησαν αυτοις'),
('grc_f35', 'Mateo 19:14', 'Mateo', 19, 14, 'ο δε ιησους ειπεν αφετε τα παιδια και μη κωλυετε αυτα ελθειν προς με των γαρ τοιουτων εστιν η βασιλεια των ουρανων'),
('grc_f35', 'Mateo 19:15', 'Mateo', 19, 15, 'και επιθεις αυτοις τας χειρας επορευθη εκειθεν'),
('grc_f35', 'Mateo 19:16', 'Mateo', 19, 16, 'και ιδου εις τις προσελθων ειπεν αυτω διδασκαλε αγαθε τι αγαθον ποιησω ινα εχω ζωην αιωνιον'),
('grc_f35', 'Mateo 19:17', 'Mateo', 19, 17, 'ο δε ειπεν αυτω τι με λεγεις αγαθον ουδεις αγαθος ει μη εις ο θεος ει δε θελεις εισελθειν εις την ζωην τηρησον τας εντολας'),
('grc_f35', 'Mateo 19:18', 'Mateo', 19, 18, 'λεγει αυτω ποιας ο δε ιησους ειπεν το ου φονευσεις ου μοιχευσεις ου κλεψεις ου ψευδομαρτυρησεις'),
('grc_f35', 'Mateo 19:19', 'Mateo', 19, 19, 'τιμα τον πατερα και την μητερα και αγαπησεις τον πλησιον σου ως σεαυτον'),
('grc_f35', 'Mateo 19:20', 'Mateo', 19, 20, 'λεγει αυτω ο νεανισκος παντα ταυτα εφυλαξαμην εκ νεοτητος μου τι ετι υστερω'),
('grc_f35', 'Mateo 19:21', 'Mateo', 19, 21, 'εφη αυτω ο ιησους ει θελεις τελειος ειναι υπαγε πωλησον σου τα υπαρχοντα και δος πτωχοις και εξεις θησαυρον εν ουρανω και δευρο ακολουθει μοι'),
('grc_f35', 'Mateo 19:22', 'Mateo', 19, 22, 'ακουσας δε ο νεανισκος τον λογον απηλθεν λυπουμενος ην γαρ εχων κτηματα πολλα'),
('grc_f35', 'Mateo 19:23', 'Mateo', 19, 23, 'ο δε ιησους ειπεν τοις μαθηταις αυτου αμην λεγω υμιν οτι δυσκολως πλουσιος εισελευσεται εις την βασιλειαν των ουρανων'),
('grc_f35', 'Mateo 19:24', 'Mateo', 19, 24, 'παλιν δε λεγω υμιν ευκοπωτερον εστιν καμηλον δια τρυπηματος ραφιδος διελθειν η πλουσιον εις την βασιλειαν του θεου εισελθειν'),
('grc_f35', 'Mateo 19:25', 'Mateo', 19, 25, 'ακουσαντες δε οι μαθηται αυτου εξεπλησσοντο σφοδρα λεγοντες τις αρα δυναται σωθηναι'),
('grc_f35', 'Mateo 19:26', 'Mateo', 19, 26, 'εμβλεψας δε ο ιησους ειπεν αυτοις παρα ανθρωποις τουτο αδυνατον εστιν παρα δε θεω παντα δυνατα'),
('grc_f35', 'Mateo 19:27', 'Mateo', 19, 27, 'τοτε αποκριθεις ο πετρος ειπεν αυτω ιδου ημεις αφηκαμεν παντα και ηκολουθησαμεν σοι τι αρα εσται ημιν'),
('grc_f35', 'Mateo 19:28', 'Mateo', 19, 28, 'ο δε ιησους ειπεν αυτοις αμην λεγω υμιν οτι υμεις οι ακολουθησαντες μοι εν τη παλιγγενεσια οταν καθιση ο υιος του ανθρωπου επι θρονου δοξης αυτου καθισεσθε και υμεις επι δωδεκα θρονους κρινοντες τας δωδεκα φυλας του ισραηλ'),
('grc_f35', 'Mateo 19:29', 'Mateo', 19, 29, 'και πας ος αφηκεν οικιας η αδελφους η αδελφας η πατερα η μητερα η γυναικα η τεκνα η αγρους ενεκεν του ονοματος μου εκατονταπλασιονα ληψεται και ζωην αιωνιον κληρονομησει'),
('grc_f35', 'Mateo 19:30', 'Mateo', 19, 30, 'πολλοι δε εσονται πρωτοι εσχατοι και εσχατοι πρωτοι'),
('grc_f35', 'Mateo 20:1', 'Mateo', 20, 1, 'ομοια γαρ εστιν η βασιλεια των ουρανων ανθρωπω οικοδεσποτη οστις εξηλθεν αμα πρωι μισθωσασθαι εργατας εις τον αμπελωνα αυτου'),
('grc_f35', 'Mateo 20:2', 'Mateo', 20, 2, 'και συμφωνησας μετα των εργατων εκ δηναριου την ημεραν απεστειλεν αυτους εις τον αμπελωνα αυτου'),
('grc_f35', 'Mateo 20:3', 'Mateo', 20, 3, 'και εξελθων περι τριτην ωραν ειδεν αλλους εστωτας εν τη αγορα αργους'),
('grc_f35', 'Mateo 20:4', 'Mateo', 20, 4, 'και εκεινοις ειπεν υπαγετε και υμεις εις τον αμπελωνα και ο εαν η δικαιον δωσω υμιν οι δε απηλθον'),
('grc_f35', 'Mateo 20:5', 'Mateo', 20, 5, 'παλιν εξελθων περι εκτην και ενατην ωραν εποιησεν ωσαυτως'),
('grc_f35', 'Mateo 20:6', 'Mateo', 20, 6, 'περι δε την ενδεκατην ωραν εξελθων ευρεν αλλους εστωτας αργους και λεγει αυτοις τι ωδε εστηκατε ολην την ημεραν αργοι'),
('grc_f35', 'Mateo 20:7', 'Mateo', 20, 7, 'λεγουσιν αυτω οτι ουδεις ημας εμισθωσατο λεγει αυτοις υπαγετε και υμεις εις τον αμπελωνα και ο εαν η δικαιον ληψεσθε'),
('grc_f35', 'Mateo 20:8', 'Mateo', 20, 8, 'οψιας δε γενομενης λεγει ο κυριος του αμπελωνος τω επιτροπω αυτου καλεσον τους εργατας και αποδος αυτοις τον μισθον αρξαμενος απο των εσχατων εως των πρωτων'),
('grc_f35', 'Mateo 20:9', 'Mateo', 20, 9, 'και ελθοντες οι περι την ενδεκατην ωραν ελαβον ανα δηναριον'),
('grc_f35', 'Mateo 20:10', 'Mateo', 20, 10, 'ελθοντες δε οι πρωτοι ενομισαν οτι πλειονα ληψονται και ελαβον και αυτοι ανα δηναριον'),
('grc_f35', 'Mateo 20:11', 'Mateo', 20, 11, 'λαβοντες δε εγογγυζον κατα του οικοδεσποτου'),
('grc_f35', 'Mateo 20:12', 'Mateo', 20, 12, 'λεγοντες οτι ουτοι οι εσχατοι μιαν ωραν εποιησαν και ισους ημιν αυτους εποιησας τοις βαστασασιν το βαρος της ημερας και τον καυσωνα'),
('grc_f35', 'Mateo 20:13', 'Mateo', 20, 13, 'ο δε αποκριθεις ειπεν ενι αυτων εταιρε ουκ αδικω σε ουχι δηναριου συνεφωνησας μοι'),
('grc_f35', 'Mateo 20:14', 'Mateo', 20, 14, 'αρον το σον και υπαγε θελω δε τουτω τω εσχατω δουναι ως και σοι'),
('grc_f35', 'Mateo 20:15', 'Mateo', 20, 15, 'η ουκ εξεστιν μοι ποιησαι ο θελω εν τοις εμοις ει ο οφθαλμος σου πονηρος εστιν οτι εγω αγαθος ειμι'),
('grc_f35', 'Mateo 20:16', 'Mateo', 20, 16, 'ουτως εσονται οι εσχατοι πρωτοι και οι πρωτοι εσχατοι πολλοι γαρ εισιν κλητοι ολιγοι δε εκλεκτοι'),
('grc_f35', 'Mateo 20:17', 'Mateo', 20, 17, 'και αναβαινων ο ιησους εις ιεροσολυμα παρελαβεν τους δωδεκα μαθητας κατ ιδιαν εν τη οδω και ειπεν αυτοις'),
('grc_f35', 'Mateo 20:18', 'Mateo', 20, 18, 'ιδου αναβαινομεν εις ιεροσολυμα και ο υιος του ανθρωπου παραδοθησεται τοις αρχιερευσιν και γραμματευσιν και κατακρινουσιν αυτον θανατω'),
('grc_f35', 'Mateo 20:19', 'Mateo', 20, 19, 'και παραδωσουσιν αυτον τοις εθνεσιν εις το εμπαιξαι και μαστιγωσαι και σταυρωσαι και τη τριτη ημερα αναστησεται'),
('grc_f35', 'Mateo 20:20', 'Mateo', 20, 20, 'τοτε προσηλθεν αυτω η μητηρ των υιων ζεβεδαιου μετα των υιων αυτης προσκυνουσα και αιτουσα τι παρ αυτου'),
('grc_f35', 'Mateo 20:21', 'Mateo', 20, 21, 'ο δε ειπεν αυτη τι θελεις λεγει αυτω ειπε ινα καθισωσιν ουτοι οι δυο υιοι μου εις εκ δεξιων σου και εις εξ ευωνυμων σου εν τη βασιλεια σου'),
('grc_f35', 'Mateo 20:22', 'Mateo', 20, 22, 'αποκριθεις δε ο ιησους ειπεν ουκ οιδατε τι αιτεισθε δυνασθε πιειν το ποτηριον ο εγω μελλω πινειν η το βαπτισμα ο εγω βαπτιζομαι βαπτισθηναι λεγουσιν αυτω δυναμεθα'),
('grc_f35', 'Mateo 20:23', 'Mateo', 20, 23, 'και λεγει αυτοις το μεν ποτηριον μου πιεσθε και το βαπτισμα ο εγω βαπτιζομαι βαπτισθησεσθε το δε καθισαι εκ δεξιων μου και εξ ευωνυμων μου ουκ εστιν εμον δουναι αλλ οις ητοιμασται υπο του πατρος μου'),
('grc_f35', 'Mateo 20:24', 'Mateo', 20, 24, 'και ακουσαντες οι δεκα ηγανακτησαν περι των δυο αδελφων'),
('grc_f35', 'Mateo 20:25', 'Mateo', 20, 25, 'ο δε ιησους προσκαλεσαμενος αυτους ειπεν οιδατε οτι οι αρχοντες των εθνων κατακυριευουσιν αυτων και οι μεγαλοι κατεξουσιαζουσιν αυτων'),
('grc_f35', 'Mateo 20:26', 'Mateo', 20, 26, 'ουχ ουτως δε εσται υμιν αλλ ος εαν θελη εν υμιν μεγας γενεσθαι εσται υμων διακονος'),
('grc_f35', 'Mateo 20:27', 'Mateo', 20, 27, 'και ος εαν θελη εν υμιν ειναι πρωτος εσται υμων δουλος'),
('grc_f35', 'Mateo 20:28', 'Mateo', 20, 28, 'ωσπερ ο υιος του ανθρωπου ουκ ηλθεν διακονηθηναι αλλα διακονησαι και δουναι την ψυχην αυτου λυτρον αντι πολλων'),
('grc_f35', 'Mateo 20:29', 'Mateo', 20, 29, 'και εκπορευομενων αυτων απο ιεριχω ηκολουθησεν αυτω οχλος πολυς'),
('grc_f35', 'Mateo 20:30', 'Mateo', 20, 30, 'και ιδου δυο τυφλοι καθημενοι παρα την οδον ακουσαντες οτι ιησους παραγει εκραξαν λεγοντες ελεησον ημας κυριε υιος δαυιδ'),
('grc_f35', 'Mateo 20:31', 'Mateo', 20, 31, 'ο δε οχλος επετιμησεν αυτοις ινα σιωπησωσιν οι δε μειζον εκραζον λεγοντες ελεησον ημας κυριε υιος δαυιδ'),
('grc_f35', 'Mateo 20:32', 'Mateo', 20, 32, 'και στας ο ιησους εφωνησεν αυτους και ειπεν τι θελετε ποιησω υμιν'),
('grc_f35', 'Mateo 20:33', 'Mateo', 20, 33, 'λεγουσιν αυτω κυριε ινα ανοιχθωσιν ημων οι οφθαλμοι'),
('grc_f35', 'Mateo 20:34', 'Mateo', 20, 34, 'σπλαγχνισθεις δε ο ιησους ηψατο των οφθαλμων αυτων και ευθεως ανεβλεψαν αυτων οι οφθαλμοι και ηκολουθησαν αυτω'),
('grc_f35', 'Mateo 21:1', 'Mateo', 21, 1, 'και οτε ηγγισαν εις ιεροσολυμα και ηλθον εις βηθσφαγη προς το ορος των ελαιων τοτε ο ιησους απεστειλεν δυο μαθητας'),
('grc_f35', 'Mateo 21:2', 'Mateo', 21, 2, 'λεγων αυτοις πορευθητε εις την κωμην την απεναντι υμων και ευθεως ευρησετε ονον δεδεμενην και πωλον μετ αυτης λυσαντες αγαγετε μοι'),
('grc_f35', 'Mateo 21:3', 'Mateo', 21, 3, 'και εαν τις υμιν ειπη τι ερειτε οτι ο κυριος αυτων χρειαν εχει ευθεως δε αποστελλει αυτους'),
('grc_f35', 'Mateo 21:4', 'Mateo', 21, 4, 'τουτο δε ολον γεγονεν ινα πληρωθη το ρηθεν δια του προφητου λεγοντος'),
('grc_f35', 'Mateo 21:5', 'Mateo', 21, 5, 'ειπατε τη θυγατρι σιων ιδου ο βασιλευς σου ερχεται σοι πραυς και επιβεβηκως επι ονον και πωλον υιον υποζυγιου'),
('grc_f35', 'Mateo 21:6', 'Mateo', 21, 6, 'πορευθεντες δε οι μαθηται και ποιησαντες καθως προσεταξεν αυτοις ο ιησους'),
('grc_f35', 'Mateo 21:7', 'Mateo', 21, 7, 'ηγαγον την ονον και τον πωλον και επεθηκαν επανω αυτων τα ιματια αυτων και επεκαθισεν επανω αυτων'),
('grc_f35', 'Mateo 21:8', 'Mateo', 21, 8, 'ο δε πλειστος οχλος εστρωσαν αυτων τα ιματια εν τη οδω αλλοι δε εκοπτον κλαδους απο των δενδρων και εστρωννυον εν τη οδω'),
('grc_f35', 'Mateo 21:9', 'Mateo', 21, 9, 'οι δε οχλοι οι προαγοντες και οι ακολουθουντες εκραζον λεγοντες ωσαννα τω υιω δαυιδ ευλογημενος ο ερχομενος εν ονοματι κυριου ωσαννα εν τοις υψιστοις'),
('grc_f35', 'Mateo 21:10', 'Mateo', 21, 10, 'και εισελθοντος αυτου εις ιεροσολυμα εσεισθη πασα η πολις λεγουσα τις εστιν ουτος'),
('grc_f35', 'Mateo 21:11', 'Mateo', 21, 11, 'οι δε οχλοι ελεγον ουτος εστιν ιησους ο προφητης ο απο ναζαρετ της γαλιλαιας'),
('grc_f35', 'Mateo 21:12', 'Mateo', 21, 12, 'και εισηλθεν ο ιησους εις το ιερον του θεου και εξεβαλεν παντας τους πωλουντας και αγοραζοντας εν τω ιερω και τας τραπεζας των κολλυβιστων κατεστρεψεν και τας καθεδρας των πωλουντων τας περιστερας'),
('grc_f35', 'Mateo 21:13', 'Mateo', 21, 13, 'και λεγει αυτοις γεγραπται ο οικος μου οικος προσευχης κληθησεται υμεις δε αυτον εποιησατε σπηλαιον ληστων'),
('grc_f35', 'Mateo 21:14', 'Mateo', 21, 14, 'και προσηλθον αυτω χωλοι και τυφλοι εν τω ιερω και εθεραπευσεν αυτους'),
('grc_f35', 'Mateo 21:15', 'Mateo', 21, 15, 'ιδοντες δε οι αρχιερεις και οι γραμματεις τα θαυμασια α εποιησεν και τους παιδας κραζοντας εν τω ιερω και λεγοντας ωσαννα τω υιω δαυιδ ηγανακτησαν'),
('grc_f35', 'Mateo 21:16', 'Mateo', 21, 16, 'και ειπον αυτω ακουεις τι ουτοι λεγουσιν ο δε ιησους λεγει αυτοις ναι ουδεποτε ανεγνωτε οτι εκ στοματος νηπιων και θηλαζοντων κατηρτισω αινον'),
('grc_f35', 'Mateo 21:17', 'Mateo', 21, 17, 'και καταλιπων αυτους εξηλθεν εξω της πολεως εις βηθανιαν και ηυλισθη εκει'),
('grc_f35', 'Mateo 21:18', 'Mateo', 21, 18, 'πρωιας δε επαναγων εις την πολιν επεινασεν'),
('grc_f35', 'Mateo 21:19', 'Mateo', 21, 19, 'και ιδων συκην μιαν επι της οδου ηλθεν επ αυτην και ουδεν ευρεν εν αυτη ει μη φυλλα μονον και λεγει αυτη μηκετι εκ σου καρπος γενηται εις τον αιωνα και εξηρανθη παραχρημα η συκη'),
('grc_f35', 'Mateo 21:20', 'Mateo', 21, 20, 'και ιδοντες οι μαθηται εθαυμασαν λεγοντες πως παραχρημα εξηρανθη η συκη'),
('grc_f35', 'Mateo 21:21', 'Mateo', 21, 21, 'αποκριθεις δε ο ιησους ειπεν αυτοις αμην λεγω υμιν εαν εχητε πιστιν και μη διακριθητε ου μονον το της συκης ποιησετε αλλα καν τω ορει τουτω ειπητε αρθητι και βληθητι εις την θαλασσαν γενησεται'),
('grc_f35', 'Mateo 21:22', 'Mateo', 21, 22, 'και παντα οσα εαν αιτησητε εν τη προσευχη πιστευοντες ληψεσθε'),
('grc_f35', 'Mateo 21:23', 'Mateo', 21, 23, 'και ελθοντι αυτω εις το ιερον προσηλθον αυτω διδασκοντι οι αρχιερεις και οι πρεσβυτεροι του λαου λεγοντες εν ποια εξουσια ταυτα ποιεις και τις σοι εδωκεν την εξουσιαν ταυτην'),
('grc_f35', 'Mateo 21:24', 'Mateo', 21, 24, 'αποκριθεις δε ο ιησους ειπεν αυτοις ερωτησω υμας καγω λογον ενα ον εαν ειπητε μοι καγω υμιν ερω εν ποια εξουσια ταυτα ποιω'),
('grc_f35', 'Mateo 21:25', 'Mateo', 21, 25, 'το βαπτισμα ιωαννου ποθεν ην εξ ουρανου η εξ ανθρωπων οι δε διελογιζοντο παρ εαυτοις λεγοντες εαν ειπωμεν εξ ουρανου ερει ημιν δια τι ουν ουκ επιστευσατε αυτω'),
('grc_f35', 'Mateo 21:26', 'Mateo', 21, 26, 'εαν δε ειπωμεν εξ ανθρωπων φοβουμεθα τον οχλον παντες γαρ εχουσιν τον ιωαννην ως προφητην'),
('grc_f35', 'Mateo 21:27', 'Mateo', 21, 27, 'και αποκριθεντες τω ιησου ειπον ουκ οιδαμεν εφη αυτοις και αυτος ουδε εγω λεγω υμιν εν ποια εξουσια ταυτα ποιω'),
('grc_f35', 'Mateo 21:28', 'Mateo', 21, 28, 'τι δε υμιν δοκει ανθρωπος τις ειχεν τεκνα δυο και προσελθων τω πρωτω ειπεν τεκνον υπαγε σημερον εργαζου εν τω αμπελωνι μου'),
('grc_f35', 'Mateo 21:29', 'Mateo', 21, 29, 'ο δε αποκριθεις ειπεν ου θελω υστερον δε μεταμεληθεις απηλθεν'),
('grc_f35', 'Mateo 21:30', 'Mateo', 21, 30, 'και προσελθων τω ετερω ειπεν ωσαυτως ο δε αποκριθεις ειπεν εγω κυριε και ουκ απηλθεν'),
('grc_f35', 'Mateo 21:31', 'Mateo', 21, 31, 'τις εκ των δυο εποιησεν το θελημα του πατρος λεγουσιν αυτω ο πρωτος λεγει αυτοις ο ιησους αμην λεγω υμιν οτι οι τελωναι και αι πορναι προαγουσιν υμας εις την βασιλειαν του θεου'),
('grc_f35', 'Mateo 21:32', 'Mateo', 21, 32, 'ηλθεν γαρ προς υμας ιωαννης εν οδω δικαιοσυνης και ουκ επιστευσατε αυτω οι δε τελωναι και αι πορναι επιστευσαν αυτω υμεις δε ιδοντες ου μετεμεληθητε υστερον του πιστευσαι αυτω'),
('grc_f35', 'Mateo 21:33', 'Mateo', 21, 33, 'αλλην παραβολην ακουσατε ανθρωπος τις ην οικοδεσποτης οστις εφυτευσεν αμπελωνα και φραγμον αυτω περιεθηκεν και ωρυξεν εν αυτω ληνον και ωκοδομησεν πυργον και εξεδοτο αυτον γεωργοις και απεδημησεν'),
('grc_f35', 'Mateo 21:34', 'Mateo', 21, 34, 'οτε δε ηγγισεν ο καιρος των καρπων απεστειλεν τους δουλους αυτου προς τους γεωργους λαβειν τους καρπους αυτου'),
('grc_f35', 'Mateo 21:35', 'Mateo', 21, 35, 'και λαβοντες οι γεωργοι τους δουλους αυτου ον μεν εδηραν ον δε απεκτειναν ον δε ελιθοβολησαν'),
('grc_f35', 'Mateo 21:36', 'Mateo', 21, 36, 'παλιν απεστειλεν αλλους δουλους πλειονας των πρωτων και εποιησαν αυτοις ωσαυτως'),
('grc_f35', 'Mateo 21:37', 'Mateo', 21, 37, 'υστερον δε απεστειλεν προς αυτους τον υιον αυτου λεγων εντραπησονται τον υιον μου'),
('grc_f35', 'Mateo 21:38', 'Mateo', 21, 38, 'οι δε γεωργοι ιδοντες τον υιον ειπον εν εαυτοις ουτος εστιν ο κληρονομος δευτε αποκτεινωμεν αυτον και κατασχωμεν την κληρονομιαν αυτου'),
('grc_f35', 'Mateo 21:39', 'Mateo', 21, 39, 'και λαβοντες αυτον εξεβαλον εξω του αμπελωνος και απεκτειναν'),
('grc_f35', 'Mateo 21:40', 'Mateo', 21, 40, 'οταν ουν ελθη ο κυριος του αμπελωνος τι ποιησει τοις γεωργοις εκεινοις'),
('grc_f35', 'Mateo 21:41', 'Mateo', 21, 41, 'λεγουσιν αυτω κακους κακως απολεσει αυτους και τον αμπελωνα εκδωσεται αλλοις γεωργοις οιτινες αποδωσουσιν αυτω τους καρπους εν τοις καιροις αυτων'),
('grc_f35', 'Mateo 21:42', 'Mateo', 21, 42, 'λεγει αυτοις ο ιησους ουδεποτε ανεγνωτε εν ταις γραφαις λιθον ον απεδοκιμασαν οι οικοδομουντες ουτος εγενηθη εις κεφαλην γωνιας παρα κυριου εγενετο αυτη και εστιν θαυμαστη εν οφθαλμοις ημων'),
('grc_f35', 'Mateo 21:43', 'Mateo', 21, 43, 'δια τουτο λεγω υμιν οτι αρθησεται αφ υμων η βασιλεια του θεου και δοθησεται εθνει ποιουντι τους καρπους αυτης'),
('grc_f35', 'Mateo 21:44', 'Mateo', 21, 44, 'και ο πεσων επι τον λιθον τουτον συνθλασθησεται εφ ον δ αν πεση λικμησει αυτον'),
('grc_f35', 'Mateo 21:45', 'Mateo', 21, 45, 'και ακουσαντες οι αρχιερεις και οι φαρισαιοι τας παραβολας αυτου εγνωσαν οτι περι αυτων λεγει'),
('grc_f35', 'Mateo 21:46', 'Mateo', 21, 46, 'και ζητουντες αυτον κρατησαι εφοβηθησαν τους οχλους επειδη ως προφητην αυτον ειχον'),
('grc_f35', 'Mateo 22:1', 'Mateo', 22, 1, 'και αποκριθεις ο ιησους παλιν ειπεν αυτοις εν παραβολαις λεγων'),
('grc_f35', 'Mateo 22:2', 'Mateo', 22, 2, 'ωμοιωθη η βασιλεια των ουρανων ανθρωπω βασιλει οστις εποιησεν γαμους τω υιω αυτου'),
('grc_f35', 'Mateo 22:3', 'Mateo', 22, 3, 'και απεστειλεν τους δουλους αυτου καλεσαι τους κεκλημενους εις τους γαμους και ουκ ηθελον ελθειν'),
('grc_f35', 'Mateo 22:4', 'Mateo', 22, 4, 'παλιν απεστειλεν αλλους δουλους λεγων ειπατε τοις κεκλημενοις ιδου το αριστον μου ητοιμασα οι ταυροι μου και τα σιτιστα τεθυμενα και παντα ετοιμα δευτε εις τους γαμους'),
('grc_f35', 'Mateo 22:5', 'Mateo', 22, 5, 'οι δε αμελησαντες απηλθον ο μεν εις τον ιδιον αγρον ο δε εις την εμποριαν αυτου'),
('grc_f35', 'Mateo 22:6', 'Mateo', 22, 6, 'οι δε λοιποι κρατησαντες τους δουλους αυτου υβρισαν και απεκτειναν'),
('grc_f35', 'Mateo 22:7', 'Mateo', 22, 7, 'και ακουσας ο βασιλευς εκεινος ωργισθη και πεμψας τα στρατευματα αυτου απωλεσεν τους φονεις εκεινους και την πολιν αυτων ενεπρησεν'),
('grc_f35', 'Mateo 22:8', 'Mateo', 22, 8, 'τοτε λεγει τοις δουλοις αυτου ο μεν γαμος ετοιμος εστιν οι δε κεκλημενοι ουκ ησαν αξιοι'),
('grc_f35', 'Mateo 22:9', 'Mateo', 22, 9, 'πορευεσθε ουν επι τας διεξοδους των οδων και οσους αν ευρητε καλεσατε εις τους γαμους'),
('grc_f35', 'Mateo 22:10', 'Mateo', 22, 10, 'και εξελθοντες οι δουλοι εκεινοι εις τας οδους συνηγαγον παντας οσους ευρον πονηρους τε και αγαθους και επλησθη ο γαμος ανακειμενων'),
('grc_f35', 'Mateo 22:11', 'Mateo', 22, 11, 'εισελθων δε ο βασιλευς θεασασθαι τους ανακειμενους ειδεν εκει ανθρωπον ουκ ενδεδυμενον ενδυμα γαμου'),
('grc_f35', 'Mateo 22:12', 'Mateo', 22, 12, 'και λεγει αυτω εταιρε πως εισηλθες ωδε μη εχων ενδυμα γαμου ο δε εφιμωθη'),
('grc_f35', 'Mateo 22:13', 'Mateo', 22, 13, 'τοτε ειπεν ο βασιλευς τοις διακονοις δησαντες αυτου χειρας και ποδας αρατε αυτον και εκβαλετε εις το σκοτος το εξωτερον εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 22:14', 'Mateo', 22, 14, 'πολλοι γαρ εισιν κλητοι ολιγοι δε εκλεκτοι'),
('grc_f35', 'Mateo 22:15', 'Mateo', 22, 15, 'τοτε πορευθεντες οι φαρισαιοι συμβουλιον ελαβον οπως αυτον παγιδευσωσιν εν λογω'),
('grc_f35', 'Mateo 22:16', 'Mateo', 22, 16, 'και αποστελλουσιν αυτω τους μαθητας αυτων μετα των ηρωδιανων λεγοντες διδασκαλε οιδαμεν οτι αληθης ει και την οδον του θεου εν αληθεια διδασκεις και ου μελει σοι περι ουδενος ου γαρ βλεπεις εις προσωπον ανθρωπων'),
('grc_f35', 'Mateo 22:17', 'Mateo', 22, 17, 'ειπε ουν ημιν τι σοι δοκει εξεστιν δουναι κηνσον καισαρι η ου'),
('grc_f35', 'Mateo 22:18', 'Mateo', 22, 18, 'γνους δε ο ιησους την πονηριαν αυτων ειπεν τι με πειραζετε υποκριται'),
('grc_f35', 'Mateo 22:19', 'Mateo', 22, 19, 'επιδειξατε μοι το νομισμα του κηνσου οι δε προσηνεγκαν αυτω δηναριον'),
('grc_f35', 'Mateo 22:20', 'Mateo', 22, 20, 'και λεγει αυτοις τινος η εικων αυτη και η επιγραφη'),
('grc_f35', 'Mateo 22:21', 'Mateo', 22, 21, 'λεγουσιν αυτω καισαρος τοτε λεγει αυτοις αποδοτε ουν τα καισαρος καισαρι και τα του θεου τω θεω'),
('grc_f35', 'Mateo 22:22', 'Mateo', 22, 22, 'και ακουσαντες εθαυμασαν και αφεντες αυτον απηλθον'),
('grc_f35', 'Mateo 22:23', 'Mateo', 22, 23, 'εν εκεινη τη ημερα προσηλθον αυτω σαδδουκαιοι οι λεγοντες μη ειναι αναστασιν και επηρωτησαν αυτον'),
('grc_f35', 'Mateo 22:24', 'Mateo', 22, 24, 'λεγοντες διδασκαλε μωσης ειπεν εαν τις αποθανη μη εχων τεκνα επιγαμβρευσει ο αδελφος αυτου την γυναικα αυτου και αναστησει σπερμα τω αδελφω αυτου'),
('grc_f35', 'Mateo 22:25', 'Mateo', 22, 25, 'ησαν δε παρ ημιν επτα αδελφοι και ο πρωτος γαμησας ετελευτησεν και μη εχων σπερμα αφηκεν την γυναικα αυτου τω αδελφω αυτου'),
('grc_f35', 'Mateo 22:26', 'Mateo', 22, 26, 'ομοιως και ο δευτερος και ο τριτος εως των επτα'),
('grc_f35', 'Mateo 22:27', 'Mateo', 22, 27, 'υστερον δε παντων απεθανεν και η γυνη'),
('grc_f35', 'Mateo 22:28', 'Mateo', 22, 28, 'εν τη ουν αναστασει τινος των επτα εσται γυνη παντες γαρ εσχον αυτην'),
('grc_f35', 'Mateo 22:29', 'Mateo', 22, 29, 'αποκριθεις δε ο ιησους ειπεν αυτοις πλανασθε μη ειδοτες τας γραφας μηδε την δυναμιν του θεου'),
('grc_f35', 'Mateo 22:30', 'Mateo', 22, 30, 'εν γαρ τη αναστασει ουτε γαμουσιν ουτε εκγαμιζονται αλλ ως αγγελοι του θεου εν ουρανω εισιν'),
('grc_f35', 'Mateo 22:31', 'Mateo', 22, 31, 'περι δε της αναστασεως των νεκρων ουκ ανεγνωτε το ρηθεν υμιν υπο του θεου λεγοντος'),
('grc_f35', 'Mateo 22:32', 'Mateo', 22, 32, 'εγω ειμι ο θεος αβρααμ και ο θεος ισαακ και ο θεος ιακωβ ουκ εστιν ο θεος θεος νεκρων αλλα ζωντων'),
('grc_f35', 'Mateo 22:33', 'Mateo', 22, 33, 'και ακουσαντες οι οχλοι εξεπλησσοντο επι τη διδαχη αυτου'),
('grc_f35', 'Mateo 22:34', 'Mateo', 22, 34, 'οι δε φαρισαιοι ακουσαντες οτι εφιμωσεν τους σαδδουκαιους συνηχθησαν επι το αυτο'),
('grc_f35', 'Mateo 22:35', 'Mateo', 22, 35, 'και επηρωτησεν εις εξ αυτων νομικος πειραζων αυτον και λεγων'),
('grc_f35', 'Mateo 22:36', 'Mateo', 22, 36, 'διδασκαλε ποια εντολη μεγαλη εν τω νομω'),
('grc_f35', 'Mateo 22:37', 'Mateo', 22, 37, 'ο δε ιησους εφη αυτω αγαπησεις κυριον τον θεον σου εν ολη τη καρδια σου και εν ολη τη ψυχη σου και εν ολη τη διανοια σου'),
('grc_f35', 'Mateo 22:38', 'Mateo', 22, 38, 'αυτη εστιν πρωτη και μεγαλη εντολη'),
('grc_f35', 'Mateo 22:39', 'Mateo', 22, 39, 'δευτερα δε ομοια αυτη αγαπησεις τον πλησιον σου ως σεαυτον'),
('grc_f35', 'Mateo 22:40', 'Mateo', 22, 40, 'εν ταυταις ταις δυσιν εντολαις ολος ο νομος και οι προφηται κρεμανται'),
('grc_f35', 'Mateo 22:41', 'Mateo', 22, 41, 'συνηγμενων δε των φαρισαιων επηρωτησεν αυτους ο ιησους'),
('grc_f35', 'Mateo 22:42', 'Mateo', 22, 42, 'λεγων τι υμιν δοκει περι του χριστου τινος υιος εστιν λεγουσιν αυτω του δαυιδ'),
('grc_f35', 'Mateo 22:43', 'Mateo', 22, 43, 'λεγει αυτοις πως ουν δαυιδ εν πνευματι κυριον αυτον καλει λεγων'),
('grc_f35', 'Mateo 22:44', 'Mateo', 22, 44, 'ειπεν ο κυριος τω κυριω μου καθου εκ δεξιων μου εως αν θω τους εχθρους σου υποποδιον των ποδων σου'),
('grc_f35', 'Mateo 22:45', 'Mateo', 22, 45, 'ει ουν δαυιδ καλει αυτον κυριον πως υιος αυτου εστιν'),
('grc_f35', 'Mateo 22:46', 'Mateo', 22, 46, 'και ουδεις εδυνατο αποκριθηναι αυτω λογον ουδε ετολμησεν τις απ εκεινης της ημερας επερωτησαι αυτον ουκετι'),
('grc_f35', 'Mateo 23:1', 'Mateo', 23, 1, 'τοτε ο ιησους ελαλησεν τοις οχλοις και τοις μαθηταις αυτου'),
('grc_f35', 'Mateo 23:2', 'Mateo', 23, 2, 'λεγων επι της μωσεως καθεδρας εκαθισαν οι γραμματεις και οι φαρισαιοι'),
('grc_f35', 'Mateo 23:3', 'Mateo', 23, 3, 'παντα ουν οσα εαν ειπωσιν υμιν τηρειν τηρειτε και ποιειτε κατα δε τα εργα αυτων μη ποιειτε λεγουσιν γαρ και ου ποιουσιν'),
('grc_f35', 'Mateo 23:4', 'Mateo', 23, 4, 'δεσμευουσιν γαρ φορτια βαρεα και δυσβαστακτα και επιτιθεασιν επι τους ωμους των ανθρωπων τω δε δακτυλω αυτων ου θελουσιν κινησαι αυτα'),
('grc_f35', 'Mateo 23:5', 'Mateo', 23, 5, 'παντα δε τα εργα αυτων ποιουσιν προς το θεαθηναι τοις ανθρωποις πλατυνουσιν δε τα φυλακτηρια αυτων και μεγαλυνουσιν τα κρασπεδα των ιματιων αυτων'),
('grc_f35', 'Mateo 23:6', 'Mateo', 23, 6, 'φιλουσιν τε την πρωτοκλισιαν εν τοις δειπνοις και τας πρωτοκαθεδριας εν ταις συναγωγαις'),
('grc_f35', 'Mateo 23:7', 'Mateo', 23, 7, 'και τους ασπασμους εν ταις αγοραις και καλεισθαι υπο των ανθρωπων ραββι ραββι'),
('grc_f35', 'Mateo 23:8', 'Mateo', 23, 8, 'υμεις δε μη κληθητε ραββι εις γαρ εστιν υμων ο διδασκαλος ο χριστος παντες δε υμεις αδελφοι εστε'),
('grc_f35', 'Mateo 23:9', 'Mateo', 23, 9, 'και πατερα μη καλεσητε υμων επι της γης εις γαρ εστιν ο πατηρ υμων ο εν τοις ουρανοις'),
('grc_f35', 'Mateo 23:10', 'Mateo', 23, 10, 'μηδε κληθητε καθηγηται εις γαρ εστιν υμων ο καθηγητης ο χριστος'),
('grc_f35', 'Mateo 23:11', 'Mateo', 23, 11, 'ο δε μειζων υμων εστω υμων διακονος'),
('grc_f35', 'Mateo 23:12', 'Mateo', 23, 12, 'οστις δε υψωσει εαυτον ταπεινωθησεται και οστις ταπεινωσει εαυτον υψωθησεται'),
('grc_f35', 'Mateo 23:13', 'Mateo', 23, 13, 'ουαι δε υμιν γραμματεις και φαρισαιοι υποκριται οτι κατεσθιετε τας οικιας των χηρων και προφασει μακρα προσευχομενοι δια τουτο ληψεσθε περισσοτερον κριμα'),
('grc_f35', 'Mateo 23:14', 'Mateo', 23, 14, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι κλειετε την βασιλειαν των ουρανων εμπροσθεν των ανθρωπων υμεις γαρ ουκ εισερχεσθε ουδε τους εισερχομενους αφιετε εισελθειν'),
('grc_f35', 'Mateo 23:15', 'Mateo', 23, 15, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι περιαγετε την θαλασσαν και την ξηραν ποιησαι ενα προσηλυτον και οταν γενηται ποιειτε αυτον υιον γεεννης διπλοτερον υμων'),
('grc_f35', 'Mateo 23:16', 'Mateo', 23, 16, 'ουαι υμιν οδηγοι τυφλοι οι λεγοντες ος αν ομοση εν τω ναω ουδεν εστιν ος δ αν ομοση εν τω χρυσω του ναου οφειλει'),
('grc_f35', 'Mateo 23:17', 'Mateo', 23, 17, 'μωροι και τυφλοι τις γαρ μειζων εστιν ο χρυσος η ο ναος ο αγιαζων τον χρυσον'),
('grc_f35', 'Mateo 23:18', 'Mateo', 23, 18, 'και ος εαν ομοση εν τω θυσιαστηριω ουδεν εστιν ος δ αν ομοση εν τω δωρω τω επανω αυτου οφειλει'),
('grc_f35', 'Mateo 23:19', 'Mateo', 23, 19, 'μωροι και τυφλοι τι γαρ μειζον το δωρον η το θυσιαστηριον το αγιαζον το δωρον'),
('grc_f35', 'Mateo 23:20', 'Mateo', 23, 20, 'ο ουν ομοσας εν τω θυσιαστηριω ομνυει εν αυτω και εν πασιν τοις επανω αυτου'),
('grc_f35', 'Mateo 23:21', 'Mateo', 23, 21, 'και ο ομοσας εν τω ναω ομνυει εν αυτω και εν τω κατοικησαντι αυτον'),
('grc_f35', 'Mateo 23:22', 'Mateo', 23, 22, 'και ο ομοσας εν τω ουρανω ομνυει εν τω θρονω του θεου και εν τω καθημενω επανω αυτου'),
('grc_f35', 'Mateo 23:23', 'Mateo', 23, 23, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι αποδεκατουτε το ηδυοσμον και το ανηθον και το κυμινον και αφηκατε τα βαρυτερα του νομου την κρισιν και τον ελεον και την πιστιν ταυτα εδει ποιησαι κακεινα μη αφιεναι'),
('grc_f35', 'Mateo 23:24', 'Mateo', 23, 24, 'οδηγοι τυφλοι οι διυλιζοντες τον κωνωπα την δε καμηλον καταπινοντες'),
('grc_f35', 'Mateo 23:25', 'Mateo', 23, 25, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι καθαριζετε το εξωθεν του ποτηριου και της παροψιδος εσωθεν δε γεμουσιν εξ αρπαγης και αδικιας'),
('grc_f35', 'Mateo 23:26', 'Mateo', 23, 26, 'φαρισαιε τυφλε καθαρισον πρωτον το εντος του ποτηριου και της παροψιδος ινα γενηται και το εκτος αυτων καθαρον'),
('grc_f35', 'Mateo 23:27', 'Mateo', 23, 27, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι παρομοιαζετε ταφοις κεκονιαμενοις οιτινες εξωθεν μεν φαινονται ωραιοι εσωθεν δε γεμουσιν οστεων νεκρων και πασης ακαθαρσιας'),
('grc_f35', 'Mateo 23:28', 'Mateo', 23, 28, 'ουτως και υμεις εξωθεν μεν φαινεσθε τοις ανθρωποις δικαιοι εσωθεν δε μεστοι εστε υποκρισεως και ανομιας'),
('grc_f35', 'Mateo 23:29', 'Mateo', 23, 29, 'ουαι υμιν γραμματεις και φαρισαιοι υποκριται οτι οικοδομειτε τους ταφους των προφητων και κοσμειτε τα μνημεια των δικαιων'),
('grc_f35', 'Mateo 23:30', 'Mateo', 23, 30, 'και λεγετε ει ημεν εν ταις ημεραις των πατερων ημων ουκ αν ημεν κοινωνοι αυτων εν τω αιματι των προφητων'),
('grc_f35', 'Mateo 23:31', 'Mateo', 23, 31, 'ωστε μαρτυρειτε εαυτοις οτι υιοι εστε των φονευσαντων τους προφητας'),
('grc_f35', 'Mateo 23:32', 'Mateo', 23, 32, 'και υμεις πληρωσατε το μετρον των πατερων υμων'),
('grc_f35', 'Mateo 23:33', 'Mateo', 23, 33, 'οφεις γεννηματα εχιδνων πως φυγητε απο της κρισεως της γεεννης'),
('grc_f35', 'Mateo 23:34', 'Mateo', 23, 34, 'δια τουτο ιδου εγω αποστελλω προς υμας προφητας και σοφους και γραμματεις και εξ αυτων αποκτενειτε και σταυρωσετε και εξ αυτων μαστιγωσετε εν ταις συναγωγαις υμων και διωξετε απο πολεως εις πολιν'),
('grc_f35', 'Mateo 23:35', 'Mateo', 23, 35, 'οπως ελθη εφ υμας παν αιμα δικαιον εκχυνομενον επι της γης απο του αιματος αβελ του δικαιου εως του αιματος ζαχαριου υιου βαραχιου ον εφονευσατε μεταξυ του ναου και του θυσιαστηριου'),
('grc_f35', 'Mateo 23:36', 'Mateo', 23, 36, 'αμην λεγω υμιν οτι ηξει παντα ταυτα επι την γενεαν ταυτην'),
('grc_f35', 'Mateo 23:37', 'Mateo', 23, 37, 'ιερουσαλημ ιερουσαλημ η αποκτενουσα τους προφητας και λιθοβολουσα τους απεσταλμενους προς αυτην ποσακις ηθελησα επισυναγαγειν τα τεκνα σου ον τροπον επισυναγει ορνις τα νοσσια εαυτης υπο τας πτερυγας και ουκ ηθελησατε'),
('grc_f35', 'Mateo 23:38', 'Mateo', 23, 38, 'ιδου αφιεται υμιν ο οικος υμων ερημος'),
('grc_f35', 'Mateo 23:39', 'Mateo', 23, 39, 'λεγω γαρ υμιν ου μη με ιδητε απ αρτι εως αν ειπητε ευλογημενος ο ερχομενος εν ονοματι κυριου'),
('grc_f35', 'Mateo 24:1', 'Mateo', 24, 1, 'και εξελθων ο ιησους επορευετο απο του ιερου και προσηλθον αυτω οι μαθηται αυτου επιδειξαι αυτω τας οικοδομας του ιερου'),
('grc_f35', 'Mateo 24:2', 'Mateo', 24, 2, 'ο δε ιησους ειπεν αυτοις ου βλεπετε παντα ταυτα αμην λεγω υμιν ου μη αφεθη ωδε λιθος επι λιθον ος ου καταλυθησεται'),
('grc_f35', 'Mateo 24:3', 'Mateo', 24, 3, 'καθημενου δε αυτου επι του ορους των ελαιων προσηλθον αυτω οι μαθηται κατ ιδιαν λεγοντες ειπε ημιν ποτε ταυτα εσται και τι το σημειον της σης παρουσιας και της συντελειας του αιωνος'),
('grc_f35', 'Mateo 24:4', 'Mateo', 24, 4, 'και αποκριθεις ο ιησους ειπεν αυτοις βλεπετε μη τις υμας πλανηση'),
('grc_f35', 'Mateo 24:5', 'Mateo', 24, 5, 'πολλοι γαρ ελευσονται επι τω ονοματι μου λεγοντες εγω ειμι ο χριστος και πολλους πλανησουσιν'),
('grc_f35', 'Mateo 24:6', 'Mateo', 24, 6, 'μελησετε δε ακουειν πολεμους και ακοας πολεμων ορατε μη θροεισθε δει γαρ παντα γενεσθαι αλλ ουπω εστιν το τελος'),
('grc_f35', 'Mateo 24:7', 'Mateo', 24, 7, 'εγερθησεται γαρ εθνος επι εθνος και βασιλεια επι βασιλειαν και εσονται λιμοι και λοιμοι και σεισμοι κατα τοπους'),
('grc_f35', 'Mateo 24:8', 'Mateo', 24, 8, 'παντα δε ταυτα αρχη ωδινων'),
('grc_f35', 'Mateo 24:9', 'Mateo', 24, 9, 'τοτε παραδωσουσιν υμας εις θλιψιν και αποκτενουσιν υμας και εσεσθε μισουμενοι υπο παντων των εθνων δια το ονομα μου'),
('grc_f35', 'Mateo 24:10', 'Mateo', 24, 10, 'και τοτε σκανδαλισθησονται πολλοι και αλληλους παραδωσουσιν και μισησουσιν αλληλους'),
('grc_f35', 'Mateo 24:11', 'Mateo', 24, 11, 'και πολλοι ψευδοπροφηται εγερθησονται και πλανησουσιν πολλους'),
('grc_f35', 'Mateo 24:12', 'Mateo', 24, 12, 'και δια το πληθυνθηναι την ανομιαν ψυγησεται η αγαπη των πολλων'),
('grc_f35', 'Mateo 24:13', 'Mateo', 24, 13, 'ο δε υπομεινας εις τελος ουτος σωθησεται'),
('grc_f35', 'Mateo 24:14', 'Mateo', 24, 14, 'και κηρυχθησεται τουτο το ευαγγελιον της βασιλειας εν ολη τη οικουμενη εις μαρτυριον πασιν τοις εθνεσιν και τοτε ηξει το τελος'),
('grc_f35', 'Mateo 24:15', 'Mateo', 24, 15, 'οταν ουν ιδητε το βδελυγμα της ερημωσεως το ρηθεν δια δανιηλ του προφητου εστως εν τοπω αγιω ο αναγινωσκων νοειτω'),
('grc_f35', 'Mateo 24:16', 'Mateo', 24, 16, 'τοτε οι εν τη ιουδαια φευγετωσαν επι τα ορη'),
('grc_f35', 'Mateo 24:17', 'Mateo', 24, 17, 'ο επι του δωματος μη καταβαινετω αραι τα εκ της οικιας αυτου'),
('grc_f35', 'Mateo 24:18', 'Mateo', 24, 18, 'και ο εν τω αγρω μη επιστρεψατω οπισω αραι το ιματιον αυτου'),
('grc_f35', 'Mateo 24:19', 'Mateo', 24, 19, 'ουαι δε ταις εν γαστρι εχουσαις και ταις θηλαζουσαις εν εκειναις ταις ημεραις'),
('grc_f35', 'Mateo 24:20', 'Mateo', 24, 20, 'προσευχεσθε δε ινα μη γενηται η φυγη υμων χειμωνος μηδε σαββατω'),
('grc_f35', 'Mateo 24:21', 'Mateo', 24, 21, 'εσται γαρ τοτε θλιψις μεγαλη οια ου γεγονεν απ αρχης κοσμου εως του νυν ουδ ου μη γενηται'),
('grc_f35', 'Mateo 24:22', 'Mateo', 24, 22, 'και ει μη εκολοβωθησαν αι ημεραι εκειναι ουκ αν εσωθη πασα σαρξ δια δε τους εκλεκτους κολοβωθησονται αι ημεραι εκειναι'),
('grc_f35', 'Mateo 24:23', 'Mateo', 24, 23, 'τοτε εαν τις υμιν ειπη ιδου ωδε ο χριστος η ωδε μη πιστευσητε'),
('grc_f35', 'Mateo 24:24', 'Mateo', 24, 24, 'εγερθησονται γαρ ψευδοχριστοι και ψευδοπροφηται και δωσουσιν σημεια μεγαλα και τερατα ωστε πλανησαι ει δυνατον και τους εκλεκτους'),
('grc_f35', 'Mateo 24:25', 'Mateo', 24, 25, 'ιδου προειρηκα υμιν'),
('grc_f35', 'Mateo 24:26', 'Mateo', 24, 26, 'εαν ουν ειπωσιν υμιν ιδου εν τη ερημω εστιν μη εξελθητε ιδου εν τοις ταμειοις μη πιστευσητε'),
('grc_f35', 'Mateo 24:27', 'Mateo', 24, 27, 'ωσπερ γαρ η αστραπη εξερχεται απο ανατολων και φαινεται εως δυσμων ουτως εσται και η παρουσια του υιου του ανθρωπου'),
('grc_f35', 'Mateo 24:28', 'Mateo', 24, 28, 'οπου γαρ εαν η το πτωμα εκει συναχθησονται οι αετοι'),
('grc_f35', 'Mateo 24:29', 'Mateo', 24, 29, 'ευθεως δε μετα την θλιψιν των ημερων εκεινων ο ηλιος σκοτισθησεται και η σεληνη ου δωσει το φεγγος αυτης και οι αστερες πεσουνται απο του ουρανου και αι δυναμεις των ουρανων σαλευθησονται'),
('grc_f35', 'Mateo 24:30', 'Mateo', 24, 30, 'και τοτε φανησεται το σημειον του υιου του ανθρωπου εν τω ουρανω και τοτε κοψονται πασαι αι φυλαι της γης και οψονται τον υιον του ανθρωπου ερχομενον επι των νεφελων του ουρανου μετα δυναμεως και δοξης πολλης'),
('grc_f35', 'Mateo 24:31', 'Mateo', 24, 31, 'και αποστελει τους αγγελους αυτου μετα σαλπιγγος φωνης μεγαλης και επισυναξουσιν τους εκλεκτους αυτου εκ των τεσσαρων ανεμων απ ακρων ουρανων εως ακρων αυτων'),
('grc_f35', 'Mateo 24:32', 'Mateo', 24, 32, 'απο δε της συκης μαθετε την παραβολην οταν ηδη ο κλαδος αυτης γενηται απαλος και τα φυλλα εκφυη γινωσκεται οτι εγγυς το θερος'),
('grc_f35', 'Mateo 24:33', 'Mateo', 24, 33, 'ουτως και υμεις οταν ιδητε ταυτα παντα γινωσκετε οτι εγγυς εστιν επι θυραις'),
('grc_f35', 'Mateo 24:34', 'Mateo', 24, 34, 'αμην λεγω υμιν ου μη παρελθη η γενεα αυτη εως αν παντα ταυτα γενηται'),
('grc_f35', 'Mateo 24:35', 'Mateo', 24, 35, 'ο ουρανος και η γη παρελευσονται οι δε λογοι μου ου μη παρελθωσιν'),
('grc_f35', 'Mateo 24:36', 'Mateo', 24, 36, 'περι δε της ημερας εκεινης και ωρας ουδεις οιδεν ουδε οι αγγελοι των ουρανων ει μη ο πατηρ μου μονος'),
('grc_f35', 'Mateo 24:37', 'Mateo', 24, 37, 'ωσπερ δε αι ημεραι του νωε ουτως εσται και η παρουσια του υιου του ανθρωπου'),
('grc_f35', 'Mateo 24:38', 'Mateo', 24, 38, 'ωσπερ γαρ ησαν εν ταις ημεραις ταις προ του κατακλυσμου τρωγοντες και πινοντες γαμουντες και εκγαμιζοντες αχρι ης ημερας εισηλθεν νωε εις την κιβωτον'),
('grc_f35', 'Mateo 24:39', 'Mateo', 24, 39, 'και ουκ εγνωσαν εως ηλθεν ο κατακλυσμος και ηρεν απαντας ουτως εσται και η παρουσια του υιου του ανθρωπου'),
('grc_f35', 'Mateo 24:40', 'Mateo', 24, 40, 'τοτε δυο εσονται εν τω αγρω ο εις παραλαμβανεται και ο εις αφιεται'),
('grc_f35', 'Mateo 24:41', 'Mateo', 24, 41, 'δυο αληθουσαι εν τω μυλωνι μια παραλαμβανεται και μια αφιεται'),
('grc_f35', 'Mateo 24:42', 'Mateo', 24, 42, 'γρηγορειτε ουν οτι ουκ οιδατε ποια ωρα ο κυριος υμων ερχεται'),
('grc_f35', 'Mateo 24:43', 'Mateo', 24, 43, 'εκεινο δε γινωσκετε οτι ει ηδει ο οικοδεσποτης ποια φυλακη ο κλεπτης ερχεται εγρηγορησεν αν και ουκ αν ειασεν διορυγηναι την οικιαν αυτου'),
('grc_f35', 'Mateo 24:44', 'Mateo', 24, 44, 'δια τουτο και υμεις γινεσθε ετοιμοι οτι η ωρα ου δοκειτε ο υιος του ανθρωπου ερχεται'),
('grc_f35', 'Mateo 24:45', 'Mateo', 24, 45, 'τις αρα εστιν ο πιστος δουλος και φρονιμος ον κατεστησεν ο κυριος αυτου επι της θεραπειας αυτου του διδοναι αυτοις την τροφην εν καιρω'),
('grc_f35', 'Mateo 24:46', 'Mateo', 24, 46, 'μακαριος ο δουλος εκεινος ον ελθων ο κυριος αυτου ευρησει ποιουντα ουτως'),
('grc_f35', 'Mateo 24:47', 'Mateo', 24, 47, 'αμην λεγω υμιν οτι επι πασιν τοις υπαρχουσιν αυτου καταστησει αυτον'),
('grc_f35', 'Mateo 24:48', 'Mateo', 24, 48, 'εαν δε ειπη ο κακος δουλος εκεινος εν τη καρδια αυτου χρονιζει ο κυριος μου ελθειν'),
('grc_f35', 'Mateo 24:49', 'Mateo', 24, 49, 'και αρξηται τυπτειν τους συνδουλους εσθιειν τε και πινειν μετα των μεθυοντων'),
('grc_f35', 'Mateo 24:50', 'Mateo', 24, 50, 'ηξει ο κυριος του δουλου εκεινου εν ημερα η ου προσδοκα και εν ωρα η ου γινωσκει'),
('grc_f35', 'Mateo 24:51', 'Mateo', 24, 51, 'και διχοτομησει αυτον και το μερος αυτου μετα των υποκριτων θησει εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 25:1', 'Mateo', 25, 1, 'τοτε ομοιωθησεται η βασιλεια των ουρανων δεκα παρθενοις αιτινες λαβουσαι τας λαμπαδας αυτων εξηλθον εις απαντησιν του νυμφιου'),
('grc_f35', 'Mateo 25:2', 'Mateo', 25, 2, 'πεντε δε ησαν εξ αυτων φρονιμοι και αι πεντε μωραι'),
('grc_f35', 'Mateo 25:3', 'Mateo', 25, 3, 'αιτινες μωραι λαβουσαι τας λαμπαδας αυτων ουκ ελαβον μεθ εαυτων ελαιον'),
('grc_f35', 'Mateo 25:4', 'Mateo', 25, 4, 'αι δε φρονιμοι ελαβον ελαιον εν τοις αγγειοις αυτων μετα των λαμπαδων αυτων'),
('grc_f35', 'Mateo 25:5', 'Mateo', 25, 5, 'χρονιζοντος δε του νυμφιου ενυσταξαν πασαι και εκαθευδον'),
('grc_f35', 'Mateo 25:6', 'Mateo', 25, 6, 'μεσης δε νυκτος κραυγη γεγονεν ιδου ο νυμφιος ερχεται εξερχεσθε εις απαντησιν αυτου'),
('grc_f35', 'Mateo 25:7', 'Mateo', 25, 7, 'τοτε ηγερθησαν πασαι αι παρθενοι εκειναι και εκοσμησαν τας λαμπαδας αυτων'),
('grc_f35', 'Mateo 25:8', 'Mateo', 25, 8, 'αι δε μωραι ταις φρονιμοις ειπον δοτε ημιν εκ του ελαιου υμων οτι αι λαμπαδες ημων σβεννυνται'),
('grc_f35', 'Mateo 25:9', 'Mateo', 25, 9, 'απεκριθησαν δε αι φρονιμοι λεγουσαι μηποτε ουκ αρκεση ημιν και υμιν πορευεσθε δε μαλλον προς τους πωλουντας και αγορασατε εαυταις'),
('grc_f35', 'Mateo 25:10', 'Mateo', 25, 10, 'απερχομενων δε αυτων αγορασαι ηλθεν ο νυμφιος και αι ετοιμοι εισηλθον μετ αυτου εις τους γαμους και εκλεισθη η θυρα'),
('grc_f35', 'Mateo 25:11', 'Mateo', 25, 11, 'υστερον δε ερχονται και αι λοιπαι παρθενοι λεγουσαι κυριε κυριε ανοιξον ημιν'),
('grc_f35', 'Mateo 25:12', 'Mateo', 25, 12, 'ο δε αποκριθεις ειπεν αμην λεγω υμιν ουκ οιδα υμας'),
('grc_f35', 'Mateo 25:13', 'Mateo', 25, 13, 'γρηγορειτε ουν οτι ουκ οιδατε την ημεραν ουδε την ωραν εν η ο υιος του ανθρωπου ερχεται'),
('grc_f35', 'Mateo 25:14', 'Mateo', 25, 14, 'ωσπερ γαρ ανθρωπος αποδημων εκαλεσεν τους ιδιους δουλους και παρεδωκεν αυτοις τα υπαρχοντα αυτου'),
('grc_f35', 'Mateo 25:15', 'Mateo', 25, 15, 'και ω μεν εδωκεν πεντε ταλαντα ω δε δυο ω δε εν εκαστω κατα την ιδιαν δυναμιν και απεδημησεν ευθεως'),
('grc_f35', 'Mateo 25:16', 'Mateo', 25, 16, 'πορευθεις δε ο τα πεντε ταλαντα λαβων ειργασατο εν αυτοις και εποιησεν αλλα πεντε ταλαντα'),
('grc_f35', 'Mateo 25:17', 'Mateo', 25, 17, 'ωσαυτως και ο τα δυο εκερδησεν και αυτος αλλα δυο'),
('grc_f35', 'Mateo 25:18', 'Mateo', 25, 18, 'ο δε το εν λαβων απελθων ωρυξεν εν τη γη και απεκρυψεν το αργυριον του κυριου αυτου'),
('grc_f35', 'Mateo 25:19', 'Mateo', 25, 19, 'μετα δε χρονον πολυν ερχεται ο κυριος των δουλων εκεινων και συναιρει μετ αυτων λογον'),
('grc_f35', 'Mateo 25:20', 'Mateo', 25, 20, 'και προσελθων ο τα πεντε ταλαντα λαβων προσηνεγκεν αλλα πεντε ταλαντα λεγων κυριε πεντε ταλαντα μοι παρεδωκας ιδε αλλα πεντε ταλαντα εκερδησα επ αυτοις'),
('grc_f35', 'Mateo 25:21', 'Mateo', 25, 21, 'εφη δε αυτω ο κυριος αυτου ευ δουλε αγαθε και πιστε επι ολιγα ης πιστος επι πολλων σε καταστησω εισελθε εις την χαραν του κυριου σου'),
('grc_f35', 'Mateo 25:22', 'Mateo', 25, 22, 'προσελθων δε και ο τα δυο ταλαντα λαβων ειπεν κυριε δυο ταλαντα μοι παρεδωκας ιδε αλλα δυο ταλαντα εκερδησα επ αυτοις'),
('grc_f35', 'Mateo 25:23', 'Mateo', 25, 23, 'εφη αυτω ο κυριος αυτου ευ δουλε αγαθε και πιστε επι ολιγα ης πιστος επι πολλων σε καταστησω εισελθε εις την χαραν του κυριου σου'),
('grc_f35', 'Mateo 25:24', 'Mateo', 25, 24, 'προσελθων δε και ο το εν ταλαντον ειληφως ειπεν κυριε εγνων σε οτι σκληρος ει ανθρωπος θεριζων οπου ουκ εσπειρας και συναγων οθεν ου διεσκορπισας'),
('grc_f35', 'Mateo 25:25', 'Mateo', 25, 25, 'και φοβηθεις απελθων εκρυψα το ταλαντον σου εν τη γη ιδε εχεις το σον'),
('grc_f35', 'Mateo 25:26', 'Mateo', 25, 26, 'αποκριθεις δε ο κυριος αυτου ειπεν αυτω πονηρε δουλε και οκνηρε ηδεις οτι θεριζω οπου ουκ εσπειρα και συναγω οθεν ου διεσκορπισα'),
('grc_f35', 'Mateo 25:27', 'Mateo', 25, 27, 'εδει ουν σε βαλειν το αργυριον μου τοις τραπεζιταις και ελθων εγω εκομισαμην αν το εμον συν τοκω'),
('grc_f35', 'Mateo 25:28', 'Mateo', 25, 28, 'αρατε ουν απ αυτου το ταλαντον και δοτε τω εχοντι τα δεκα ταλαντα'),
('grc_f35', 'Mateo 25:29', 'Mateo', 25, 29, 'τω γαρ εχοντι παντι δοθησεται και περισσευθησεται απο δε του μη εχοντος και ο δοκει εχειν αρθησεται απ αυτου'),
('grc_f35', 'Mateo 25:30', 'Mateo', 25, 30, 'και τον αχρειον δουλον εκβαλετε εις το σκοτος το εξωτερον εκει εσται ο κλαυθμος και ο βρυγμος των οδοντων'),
('grc_f35', 'Mateo 25:31', 'Mateo', 25, 31, 'οταν δε ελθη ο υιος του ανθρωπου εν τη δοξη αυτου και παντες οι αγιοι αγγελοι μετ αυτου τοτε καθισει επι θρονου δοξης αυτου'),
('grc_f35', 'Mateo 25:32', 'Mateo', 25, 32, 'και συναχθησονται εμπροσθεν αυτου παντα τα εθνη και αφοριει αυτους απ αλληλων ωσπερ ο ποιμην αφοριζει τα προβατα απο των εριφων'),
('grc_f35', 'Mateo 25:33', 'Mateo', 25, 33, 'και στησει τα μεν προβατα εκ δεξιων αυτου τα δε εριφια εξ ευωνυμων'),
('grc_f35', 'Mateo 25:34', 'Mateo', 25, 34, 'τοτε ερει ο βασιλευς τοις εκ δεξιων αυτου δευτε οι ευλογημενοι του πατρος μου κληρονομησατε την ητοιμασμενην υμιν βασιλειαν απο καταβολης κοσμου'),
('grc_f35', 'Mateo 25:35', 'Mateo', 25, 35, 'επεινασα γαρ και εδωκατε μοι φαγειν εδιψησα και εποτισατε με ξενος ημην και συνηγαγετε με'),
('grc_f35', 'Mateo 25:36', 'Mateo', 25, 36, 'γυμνος και περιεβαλετε με ησθενησα και επεσκεψασθε με εν φυλακη ημην και ηλθετε προς με'),
('grc_f35', 'Mateo 25:37', 'Mateo', 25, 37, 'τοτε αποκριθησονται αυτω οι δικαιοι λεγοντες κυριε ποτε σε ειδομεν πεινωντα και εθρεψαμεν η διψωντα και εποτισαμεν'),
('grc_f35', 'Mateo 25:38', 'Mateo', 25, 38, 'ποτε δε σε ειδομεν ξενον και συνηγαγομεν η γυμνον και περιεβαλομεν'),
('grc_f35', 'Mateo 25:39', 'Mateo', 25, 39, 'ποτε δε σε ειδομεν ασθενη η εν φυλακη και ηλθομεν προς σε'),
('grc_f35', 'Mateo 25:40', 'Mateo', 25, 40, 'και αποκριθεις ο βασιλευς ερει αυτοις αμην λεγω υμιν εφ οσον εποιησατε ενι τουτων των αδελφων μου των ελαχιστων εμοι εποιησατε'),
('grc_f35', 'Mateo 25:41', 'Mateo', 25, 41, 'τοτε ερει και τοις εξ ευωνυμων πορευεσθε απ εμου οι κατηραμενοι εις το πυρ το αιωνιον το ητοιμασμενον τω διαβολω και τοις αγγελοις αυτου'),
('grc_f35', 'Mateo 25:42', 'Mateo', 25, 42, 'επεινασα γαρ και ουκ εδωκατε μοι φαγειν εδιψησα και ουκ εποτισατε με'),
('grc_f35', 'Mateo 25:43', 'Mateo', 25, 43, 'ξενος ημην και ου συνηγαγετε με γυμνος και ου περιεβαλετε με ασθενης και εν φυλακη και ουκ επεσκεψασθε με'),
('grc_f35', 'Mateo 25:44', 'Mateo', 25, 44, 'τοτε αποκριθησονται και αυτοι λεγοντες κυριε ποτε σε ειδομεν πεινωντα η διψωντα η ξενον η γυμνον η ασθενη η εν φυλακη και ου διηκονησαμεν σοι'),
('grc_f35', 'Mateo 25:45', 'Mateo', 25, 45, 'τοτε αποκριθησεται αυτοις λεγων αμην λεγω υμιν εφ οσον ουκ εποιησατε ενι τουτων των ελαχιστων ουδε εμοι εποιησατε'),
('grc_f35', 'Mateo 25:46', 'Mateo', 25, 46, 'και απελευσονται ουτοι εις κολασιν αιωνιον οι δε δικαιοι εις ζωην αιωνιον'),
('grc_f35', 'Mateo 26:1', 'Mateo', 26, 1, 'και εγενετο οτε ετελεσεν ο ιησους τους λογους τουτους ειπεν τοις μαθηταις αυτου'),
('grc_f35', 'Mateo 26:2', 'Mateo', 26, 2, 'οιδατε οτι μετα δυο ημερας το πασχα γινεται και ο υιος του ανθρωπου παραδιδοται εις το σταυρωθηναι'),
('grc_f35', 'Mateo 26:3', 'Mateo', 26, 3, 'τοτε συνηχθησαν οι αρχιερεις και οι γραμματεις και οι πρεσβυτεροι του λαου εις την αυλην του αρχιερεως του λεγομενου καιαφα'),
('grc_f35', 'Mateo 26:4', 'Mateo', 26, 4, 'και συνεβουλευσαντο ινα τον ιησουν δολω κρατησωσιν και αποκτεινωσιν'),
('grc_f35', 'Mateo 26:5', 'Mateo', 26, 5, 'ελεγον δε μη εν τη εορτη ινα μη θορυβος γενηται εν τω λαω'),
('grc_f35', 'Mateo 26:6', 'Mateo', 26, 6, 'του δε ιησου γενομενου εν βηθανια εν οικια σιμωνος του λεπρου'),
('grc_f35', 'Mateo 26:7', 'Mateo', 26, 7, 'προσηλθεν αυτω γυνη αλαβαστρον μυρου εχουσα βαρυτιμου και κατεχεεν επι την κεφαλην αυτου ανακειμενου'),
('grc_f35', 'Mateo 26:8', 'Mateo', 26, 8, 'ιδοντες δε οι μαθηται αυτου ηγανακτησαν λεγοντες εις τι η απωλεια αυτη'),
('grc_f35', 'Mateo 26:9', 'Mateo', 26, 9, 'ηδυνατο γαρ τουτο το μυρον πραθηναι πολλου και δοθηναι τοις πτωχοις'),
('grc_f35', 'Mateo 26:10', 'Mateo', 26, 10, 'γνους δε ο ιησους ειπεν αυτοις τι κοπους παρεχετε τη γυναικι εργον γαρ καλον ειργασατο εις εμε'),
('grc_f35', 'Mateo 26:11', 'Mateo', 26, 11, 'παντοτε γαρ τους πτωχους εχετε μεθ εαυτων εμε δε ου παντοτε εχετε'),
('grc_f35', 'Mateo 26:12', 'Mateo', 26, 12, 'βαλουσα γαρ αυτη το μυρον τουτο επι του σωματος μου προς το ενταφιασαι με εποιησεν'),
('grc_f35', 'Mateo 26:13', 'Mateo', 26, 13, 'αμην λεγω υμιν οπου εαν κηρυχθη το ευαγγελιον τουτο εν ολω τω κοσμω λαληθησεται και ο εποιησεν αυτη εις μνημοσυνον αυτης'),
('grc_f35', 'Mateo 26:14', 'Mateo', 26, 14, 'τοτε πορευθεις εις των δωδεκα ο λεγομενος ιουδας ισκαριωτης προς τους αρχιερεις'),
('grc_f35', 'Mateo 26:15', 'Mateo', 26, 15, 'ειπεν τι θελετε μοι δουναι και εγω υμιν παραδωσω αυτον οι δε εστησαν αυτω τριακοντα αργυρια'),
('grc_f35', 'Mateo 26:16', 'Mateo', 26, 16, 'και απο τοτε εζητει ευκαιριαν ινα αυτον παραδω'),
('grc_f35', 'Mateo 26:17', 'Mateo', 26, 17, 'τη δε πρωτη των αζυμων προσηλθον οι μαθηται τω ιησου λεγοντες αυτω που θελεις ετοιμασομεν σοι φαγειν το πασχα'),
('grc_f35', 'Mateo 26:18', 'Mateo', 26, 18, 'ο δε ειπεν υπαγετε εις την πολιν προς τον δεινα και ειπατε αυτω ο διδασκαλος λεγει ο καιρος μου εγγυς εστιν προς σε ποιω το πασχα μετα των μαθητων μου'),
('grc_f35', 'Mateo 26:19', 'Mateo', 26, 19, 'και εποιησαν οι μαθηται ως συνεταξεν αυτοις ο ιησους και ητοιμασαν το πασχα'),
('grc_f35', 'Mateo 26:20', 'Mateo', 26, 20, 'οψιας δε γενομενης ανεκειτο μετα των δωδεκα'),
('grc_f35', 'Mateo 26:21', 'Mateo', 26, 21, 'και εσθιοντων αυτων ειπεν αμην λεγω υμιν οτι εις εξ υμων παραδωσει με'),
('grc_f35', 'Mateo 26:22', 'Mateo', 26, 22, 'και λυπουμενοι σφοδρα ηρξαντο λεγειν αυτω εκαστος αυτων μητι εγω ειμι κυριε'),
('grc_f35', 'Mateo 26:23', 'Mateo', 26, 23, 'ο δε αποκριθεις ειπεν ο εμβαψας μετ εμου εν τω τρυβλιω την χειρα ουτος με παραδωσει'),
('grc_f35', 'Mateo 26:24', 'Mateo', 26, 24, 'ο μεν υιος του ανθρωπου υπαγει καθως γεγραπται περι αυτου ουαι δε τω ανθρωπω εκεινω δι ου ο υιος του ανθρωπου παραδιδοται καλον ην αυτω ει ουκ εγεννηθη ο ανθρωπος εκεινος'),
('grc_f35', 'Mateo 26:25', 'Mateo', 26, 25, 'αποκριθεις δε ιουδας ο παραδιδους αυτον ειπεν μητι εγω ειμι ραββι λεγει αυτω συ ειπας'),
('grc_f35', 'Mateo 26:26', 'Mateo', 26, 26, 'εσθιοντων δε αυτων λαβων ο ιησους τον αρτον και ευλογησας εκλασεν και εδιδου τοις μαθηταις και ειπεν λαβετε φαγετε τουτο εστιν το σωμα μου'),
('grc_f35', 'Mateo 26:27', 'Mateo', 26, 27, 'και λαβων το ποτηριον και ευχαριστησας εδωκεν αυτοις λεγων πιετε εξ αυτου παντες'),
('grc_f35', 'Mateo 26:28', 'Mateo', 26, 28, 'τουτο γαρ εστιν το αιμα μου το της καινης διαθηκης το περι πολλων εκχυνομενον εις αφεσιν αμαρτιων'),
('grc_f35', 'Mateo 26:29', 'Mateo', 26, 29, 'λεγω δε υμιν οτι ου μη πιω απ αρτι εκ τουτου του γενηματος της αμπελου εως της ημερας εκεινης οταν αυτο πινω μεθ υμων καινον εν τη βασιλεια του πατρος μου'),
('grc_f35', 'Mateo 26:30', 'Mateo', 26, 30, 'και υμνησαντες εξηλθον εις το ορος των ελαιων'),
('grc_f35', 'Mateo 26:31', 'Mateo', 26, 31, 'τοτε λεγει αυτοις ο ιησους παντες υμεις σκανδαλισθησεσθε εν εμοι εν τη νυκτι ταυτη γεγραπται γαρ παταξω τον ποιμενα και διασκορπισθησεται τα προβατα της ποιμνης'),
('grc_f35', 'Mateo 26:32', 'Mateo', 26, 32, 'μετα δε το εγερθηναι με προαξω υμας εις την γαλιλαιαν'),
('grc_f35', 'Mateo 26:33', 'Mateo', 26, 33, 'αποκριθεις δε ο πετρος ειπεν αυτω ει και παντες σκανδαλισθησονται εν σοι εγω ουδεποτε σκανδαλισθησομαι'),
('grc_f35', 'Mateo 26:34', 'Mateo', 26, 34, 'εφη αυτω ο ιησους αμην λεγω σοι οτι εν ταυτη τη νυκτι πριν αλεκτορα φωνησαι τρις απαρνηση με'),
('grc_f35', 'Mateo 26:35', 'Mateo', 26, 35, 'λεγει αυτω ο πετρος καν δεη με συν σοι αποθανειν ου μη σε απαρνησωμαι ομοιως δε και παντες οι μαθηται ειπον'),
('grc_f35', 'Mateo 26:36', 'Mateo', 26, 36, 'τοτε ερχεται μετ αυτων ο ιησους εις χωριον λεγομενον γεθσημανη και λεγει τοις μαθηταις καθισατε αυτου εως ου απελθων προσευξωμαι εκει'),
('grc_f35', 'Mateo 26:37', 'Mateo', 26, 37, 'και παραλαβων τον πετρον και τους δυο υιους ζεβεδαιου ηρξατο λυπεισθαι και αδημονειν'),
('grc_f35', 'Mateo 26:38', 'Mateo', 26, 38, 'τοτε λεγει αυτοις ο ιησους περιλυπος εστιν η ψυχη μου εως θανατου μεινατε ωδε και γρηγορειτε μετ εμου'),
('grc_f35', 'Mateo 26:39', 'Mateo', 26, 39, 'και προελθων μικρον επεσεν επι προσωπον αυτου προσευχομενος και λεγων πατερ μου ει δυνατον εστιν παρελθετω απ εμου το ποτηριον τουτο πλην ουχ ως εγω θελω αλλ ως συ'),
('grc_f35', 'Mateo 26:40', 'Mateo', 26, 40, 'και ερχεται προς τους μαθητας και ευρισκει αυτους καθευδοντας και λεγει τω πετρω ουτως ουκ ισχυσατε μιαν ωραν γρηγορησαι μετ εμου'),
('grc_f35', 'Mateo 26:41', 'Mateo', 26, 41, 'γρηγορειτε και προσευχεσθε ινα μη εισελθητε εις πειρασμον το μεν πνευμα προθυμον η δε σαρξ ασθενης'),
('grc_f35', 'Mateo 26:42', 'Mateo', 26, 42, 'παλιν εκ δευτερου απελθων προσηυξατο λεγων πατερ μου ει ου δυναται τουτο το ποτηριον παρελθειν απ εμου εαν μη αυτο πιω γενηθητω το θελημα σου'),
('grc_f35', 'Mateo 26:43', 'Mateo', 26, 43, 'και ελθων ευρεν αυτους παλιν καθευδοντας ησαν γαρ αυτων οι οφθαλμοι βεβαρημενοι'),
('grc_f35', 'Mateo 26:44', 'Mateo', 26, 44, 'και αφεις αυτους απελθων παλιν προσηυξατο εκ τριτου τον αυτον λογον ειπων'),
('grc_f35', 'Mateo 26:45', 'Mateo', 26, 45, 'τοτε ερχεται προς τους μαθητας αυτου και λεγει αυτοις καθευδετε το λοιπον και αναπαυεσθε ιδου ηγγικεν η ωρα και ο υιος του ανθρωπου παραδιδοται εις χειρας αμαρτωλων'),
('grc_f35', 'Mateo 26:46', 'Mateo', 26, 46, 'εγειρεσθε αγωμεν ιδου ο παραδιδους με'),
('grc_f35', 'Mateo 26:47', 'Mateo', 26, 47, 'και ετι αυτου λαλουντος ιδου ιουδας εις των δωδεκα ηλθεν και μετ αυτου οχλος πολυς μετα μαχαιρων και ξυλων απο των αρχιερεων και πρεσβυτερων του λαου'),
('grc_f35', 'Mateo 26:48', 'Mateo', 26, 48, 'ο δε παραδιδους αυτον εδωκεν αυτοις σημειον λεγων ον εαν φιλησω αυτος εστιν κρατησατε αυτον'),
('grc_f35', 'Mateo 26:49', 'Mateo', 26, 49, 'και ευθεως προσελθων τω ιησου ειπεν χαιρε ραββι και κατεφιλησεν αυτον'),
('grc_f35', 'Mateo 26:50', 'Mateo', 26, 50, 'ο δε ιησους ειπεν αυτω εταιρε εφ ω παρει τοτε προσελθοντες επεβαλον τας χειρας επι τον ιησουν και εκρατησαν αυτον'),
('grc_f35', 'Mateo 26:51', 'Mateo', 26, 51, 'και ιδου εις των μετα ιησου εκτεινας την χειρα απεσπασεν την μαχαιραν αυτου και παταξας τον δουλον του αρχιερεως αφειλεν αυτου το ωτιον'),
('grc_f35', 'Mateo 26:52', 'Mateo', 26, 52, 'τοτε λεγει αυτω ο ιησους αποστρεψον σου την μαχαιραν εις τον τοπον αυτης παντες γαρ οι λαβοντες μαχαιραν εν μαχαιρα αποθανουνται'),
('grc_f35', 'Mateo 26:53', 'Mateo', 26, 53, 'η δοκεις οτι ου δυναμαι αρτι παρακαλεσαι τον πατερα μου και παραστησει μοι πλειους η δωδεκα λεγεωνας αγγελων'),
('grc_f35', 'Mateo 26:54', 'Mateo', 26, 54, 'πως ουν πληρωθωσιν αι γραφαι οτι ουτως δει γενεσθαι'),
('grc_f35', 'Mateo 26:55', 'Mateo', 26, 55, 'εν εκεινη τη ωρα ειπεν ο ιησους τοις οχλοις ως επι ληστην εξηλθετε μετα μαχαιρων και ξυλων συλλαβειν με καθ ημεραν προς υμας εκαθεζομην εν τω ιερω διδασκων και ουκ εκρατησατε με'),
('grc_f35', 'Mateo 26:56', 'Mateo', 26, 56, 'τουτο δε ολον γεγονεν ινα πληρωθωσιν αι γραφαι των προφητων τοτε οι μαθηται παντες αφεντες αυτον εφυγον'),
('grc_f35', 'Mateo 26:57', 'Mateo', 26, 57, 'οι δε κρατησαντες τον ιησουν απηγαγον προς καιαφαν τον αρχιερεα οπου οι γραμματεις και οι πρεσβυτεροι συνηχθησαν'),
('grc_f35', 'Mateo 26:58', 'Mateo', 26, 58, 'ο δε πετρος ηκολουθει αυτω απο μακροθεν εως της αυλης του αρχιερεως και εισελθων εσω εκαθητο μετα των υπηρετων ιδειν το τελος'),
('grc_f35', 'Mateo 26:59', 'Mateo', 26, 59, 'οι δε αρχιερεις και οι πρεσβυτεροι και το συνεδριον ολον εζητουν ψευδομαρτυριαν κατα του ιησου οπως θανατωσωσιν αυτον'),
('grc_f35', 'Mateo 26:60', 'Mateo', 26, 60, 'και ουχ ευρον και πολλων ψευδομαρτυρων προσελθοντων ουχ ευρον υστερον δε προσελθοντες δυο ψευδομαρτυρες'),
('grc_f35', 'Mateo 26:61', 'Mateo', 26, 61, 'ειπον ουτος εφη δυναμαι καταλυσαι τον ναον του θεου και δια τριων ημερων οικοδομησαι αυτον'),
('grc_f35', 'Mateo 26:62', 'Mateo', 26, 62, 'και αναστας ο αρχιερευς ειπεν αυτω ουδεν αποκρινη τι ουτοι σου καταμαρτυρουσιν'),
('grc_f35', 'Mateo 26:63', 'Mateo', 26, 63, 'ο δε ιησους εσιωπα και αποκριθεις ο αρχιερευς ειπεν αυτω εξορκιζω σε κατα του θεου του ζωντος ινα ημιν ειπης ει συ ει ο χριστος ο υιος του θεου'),
('grc_f35', 'Mateo 26:64', 'Mateo', 26, 64, 'λεγει αυτω ο ιησους συ ειπας πλην λεγω υμιν απ αρτι οψεσθε τον υιον του ανθρωπου καθημενον εκ δεξιων της δυναμεως και ερχομενον επι των νεφελων του ουρανου'),
('grc_f35', 'Mateo 26:65', 'Mateo', 26, 65, 'τοτε ο αρχιερευς διερρηξεν τα ιματια αυτου λεγων οτι εβλασφημησεν τι ετι χρειαν εχομεν μαρτυρων ιδε νυν ηκουσατε την βλασφημιαν αυτου'),
('grc_f35', 'Mateo 26:66', 'Mateo', 26, 66, 'τι υμιν δοκει οι δε αποκριθεντες ειπον ενοχος θανατου εστιν'),
('grc_f35', 'Mateo 26:67', 'Mateo', 26, 67, 'τοτε ενεπτυσαν εις το προσωπον αυτου και εκολαφισαν αυτον οι δε ερραπισαν'),
('grc_f35', 'Mateo 26:68', 'Mateo', 26, 68, 'λεγοντες προφητευσον ημιν χριστε τις εστιν ο παισας σε'),
('grc_f35', 'Mateo 26:69', 'Mateo', 26, 69, 'ο δε πετρος εξω εκαθητο εν τη αυλη και προσηλθεν αυτω μια παιδισκη λεγουσα και συ ησθα μετα ιησου του γαλιλαιου'),
('grc_f35', 'Mateo 26:70', 'Mateo', 26, 70, 'ο δε ηρνησατο εμπροσθεν αυτων παντων λεγων ουκ οιδα τι λεγεις'),
('grc_f35', 'Mateo 26:71', 'Mateo', 26, 71, 'εξελθοντα δε αυτον εις τον πυλωνα ειδεν αυτον αλλη και λεγει αυτοις εκει και ουτος ην μετα ιησου του ναζωραιου'),
('grc_f35', 'Mateo 26:72', 'Mateo', 26, 72, 'και παλιν ηρνησατο μεθ ορκου οτι ουκ οιδα τον ανθρωπον'),
('grc_f35', 'Mateo 26:73', 'Mateo', 26, 73, 'μετα μικρον δε προσελθοντες οι εστωτες ειπον τω πετρω αληθως και συ εξ αυτων ει και γαρ η λαλια σου δηλον σε ποιει'),
('grc_f35', 'Mateo 26:74', 'Mateo', 26, 74, 'τοτε ηρξατο καταθεματιζειν και ομνυειν οτι ουκ οιδα τον ανθρωπον και ευθεως αλεκτωρ εφωνησεν'),
('grc_f35', 'Mateo 26:75', 'Mateo', 26, 75, 'και εμνησθη ο πετρος του ρηματος ιησου ειρηκοτος αυτω οτι πριν αλεκτορα φωνησαι τρις απαρνηση με και εξελθων εξω εκλαυσεν πικρως'),
('grc_f35', 'Mateo 27:1', 'Mateo', 27, 1, 'πρωιας δε γενομενης συμβουλιον ελαβον παντες οι αρχιερεις και οι πρεσβυτεροι κατα του ιησου ωστε θανατωσαι αυτον'),
('grc_f35', 'Mateo 27:2', 'Mateo', 27, 2, 'και δησαντες αυτον απηγαγον και παρεδωκαν αυτον ποντιω πιλατω τω ηγεμονι'),
('grc_f35', 'Mateo 27:3', 'Mateo', 27, 3, 'τοτε ιδων ιουδας ο παραδιδους αυτον οτι κατεκριθη μεταμεληθεις απεστρεψεν τα τριακοντα αργυρια τοις αρχιερευσιν και τοις πρεσβυτεροις'),
('grc_f35', 'Mateo 27:4', 'Mateo', 27, 4, 'λεγων ημαρτον παραδους αιμα αθωον οι δε ειπον τι προς ημας συ οψει'),
('grc_f35', 'Mateo 27:5', 'Mateo', 27, 5, 'και ριψας τα αργυρια εν τω ναω ανεχωρησεν και απελθων απηγξατο'),
('grc_f35', 'Mateo 27:6', 'Mateo', 27, 6, 'οι δε αρχιερεις λαβοντες τα αργυρια ειπον ουκ εξεστιν βαλειν αυτα εις τον κορβαναν επει τιμη αιματος εστιν'),
('grc_f35', 'Mateo 27:7', 'Mateo', 27, 7, 'συμβουλιον δε λαβοντες ηγορασαν εξ αυτων τον αγρον του κεραμεως εις ταφην τοις ξενοις'),
('grc_f35', 'Mateo 27:8', 'Mateo', 27, 8, 'διο εκληθη ο αγρος εκεινος αγρος αιματος εως της σημερον'),
('grc_f35', 'Mateo 27:9', 'Mateo', 27, 9, 'τοτε επληρωθη το ρηθεν δια ιερεμιου του προφητου λεγοντος και ελαβον τα τριακοντα αργυρια την τιμην του τετιμημενου ον ετιμησαντο απο υιων ισραηλ'),
('grc_f35', 'Mateo 27:10', 'Mateo', 27, 10, 'και εδωκαν αυτα εις τον αγρον του κεραμεως καθα συνεταξεν μοι κυριος'),
('grc_f35', 'Mateo 27:11', 'Mateo', 27, 11, 'ο δε ιησους εστη εμπροσθεν του ηγεμονος και επηρωτησεν αυτον ο ηγεμων λεγων συ ει ο βασιλευς των ιουδαιων ο δε ιησους εφη αυτω συ λεγεις'),
('grc_f35', 'Mateo 27:12', 'Mateo', 27, 12, 'και εν τω κατηγορεισθαι αυτον υπο των αρχιερεων και πρεσβυτερων ουδεν απεκρινατο'),
('grc_f35', 'Mateo 27:13', 'Mateo', 27, 13, 'τοτε λεγει αυτω ο πιλατος ουκ ακουεις ποσα σου καταμαρτυρουσιν'),
('grc_f35', 'Mateo 27:14', 'Mateo', 27, 14, 'και ουκ απεκριθη αυτω προς ουδε εν ρημα ωστε θαυμαζειν τον ηγεμονα λιαν'),
('grc_f35', 'Mateo 27:15', 'Mateo', 27, 15, 'κατα δε εορτην ειωθει ο ηγεμων απολυειν ενα τω οχλω δεσμιον ον ηθελον'),
('grc_f35', 'Mateo 27:16', 'Mateo', 27, 16, 'ειχον δε τοτε δεσμιον επισημον λεγομενον βαραββαν'),
('grc_f35', 'Mateo 27:17', 'Mateo', 27, 17, 'συνηγμενων ουν αυτων ειπεν αυτοις ο πιλατος τινα θελετε απολυσω υμιν βαραββαν η ιησουν τον λεγομενον χριστον'),
('grc_f35', 'Mateo 27:18', 'Mateo', 27, 18, 'ηδει γαρ οτι δια φθονον παρεδωκαν αυτον'),
('grc_f35', 'Mateo 27:19', 'Mateo', 27, 19, 'καθημενου δε αυτου επι του βηματος απεστειλεν προς αυτον η γυνη αυτου λεγουσα μηδεν σοι και τω δικαιω εκεινω πολλα γαρ επαθον σημερον κατ οναρ δι αυτον'),
('grc_f35', 'Mateo 27:20', 'Mateo', 27, 20, 'οι δε αρχιερεις και οι πρεσβυτεροι επεισαν τους οχλους ινα αιτησωνται τον βαραββαν τον δε ιησουν απολεσωσιν'),
('grc_f35', 'Mateo 27:21', 'Mateo', 27, 21, 'αποκριθεις δε ο ηγεμων ειπεν αυτοις τινα θελετε απο των δυο απολυσω υμιν οι δε ειπον βαραββαν'),
('grc_f35', 'Mateo 27:22', 'Mateo', 27, 22, 'λεγει αυτοις ο πιλατος τι ουν ποιησω ιησουν τον λεγομενον χριστον λεγουσιν αυτω παντες σταυρωθητω'),
('grc_f35', 'Mateo 27:23', 'Mateo', 27, 23, 'ο δε ηγεμων εφη τι γαρ κακον εποιησεν οι δε περισσως εκραζον λεγοντες σταυρωθητω'),
('grc_f35', 'Mateo 27:24', 'Mateo', 27, 24, 'ιδων δε ο πιλατος οτι ουδεν ωφελει αλλα μαλλον θορυβος γινεται λαβων υδωρ απενιψατο τας χειρας απεναντι του οχλου λεγων αθωος ειμι απο του αιματος του δικαιου τουτου υμεις οψεσθε'),
('grc_f35', 'Mateo 27:25', 'Mateo', 27, 25, 'και αποκριθεις πας ο λαος ειπεν το αιμα αυτου εφ ημας και επι τα τεκνα ημων'),
('grc_f35', 'Mateo 27:26', 'Mateo', 27, 26, 'τοτε απελυσεν αυτοις τον βαραββαν τον δε ιησουν φραγελλωσας παρεδωκεν ινα σταυρωθη'),
('grc_f35', 'Mateo 27:27', 'Mateo', 27, 27, 'τοτε οι στρατιωται του ηγεμονος παραλαβοντες τον ιησουν εις το πραιτωριον συνηγαγον επ αυτον ολην την σπειραν'),
('grc_f35', 'Mateo 27:28', 'Mateo', 27, 28, 'και εκδυσαντες αυτον περιεθηκαν αυτω χλαμυδα κοκκινην'),
('grc_f35', 'Mateo 27:29', 'Mateo', 27, 29, 'και πλεξαντες στεφανον εξ ακανθων επεθηκαν επι την κεφαλην αυτου και καλαμον επι την δεξιαν αυτου και γονυπετησαντες εμπροσθεν αυτου ενεπαιζον αυτω λεγοντες χαιρε ο βασιλευς των ιουδαιων'),
('grc_f35', 'Mateo 27:30', 'Mateo', 27, 30, 'και εμπτυσαντες εις αυτον ελαβον τον καλαμον και ετυπτον εις την κεφαλην αυτου'),
('grc_f35', 'Mateo 27:31', 'Mateo', 27, 31, 'και οτε ενεπαιξαν αυτω εξεδυσαν αυτον την χλαμυδα και ενεδυσαν αυτον τα ιματια αυτου και απηγαγον αυτον εις το σταυρωσαι'),
('grc_f35', 'Mateo 27:32', 'Mateo', 27, 32, 'εξερχομενοι δε ευρον ανθρωπον κυρηναιον ονοματι σιμωνα τουτον ηγγαρευσαν ινα αρη τον σταυρον αυτου'),
('grc_f35', 'Mateo 27:33', 'Mateo', 27, 33, 'και ελθοντες εις τοπον λεγομενον γολγοθα ο εστιν λεγομενον κρανιου τοπος'),
('grc_f35', 'Mateo 27:34', 'Mateo', 27, 34, 'εδωκαν αυτω πιειν οξος μετα χολης μεμιγμενον και γευσαμενος ουκ ηθελεν πιειν'),
('grc_f35', 'Mateo 27:35', 'Mateo', 27, 35, 'σταυρωσαντες δε αυτον διεμερισαντο τα ιματια αυτου βαλοντες κληρον'),
('grc_f35', 'Mateo 27:36', 'Mateo', 27, 36, 'και καθημενοι ετηρουν αυτον εκει'),
('grc_f35', 'Mateo 27:37', 'Mateo', 27, 37, 'και επεθηκαν επανω της κεφαλης αυτου την αιτιαν αυτου γεγραμμενην ουτος εστιν ιησους ο βασιλευς των ιουδαιων'),
('grc_f35', 'Mateo 27:38', 'Mateo', 27, 38, 'τοτε σταυρουνται συν αυτω δυο λησται εις εκ δεξιων και εις εξ ευωνυμων'),
('grc_f35', 'Mateo 27:39', 'Mateo', 27, 39, 'οι δε παραπορευομενοι εβλασφημουν αυτον κινουντες τας κεφαλας αυτων'),
('grc_f35', 'Mateo 27:40', 'Mateo', 27, 40, 'και λεγοντες ο καταλυων τον ναον και εν τρισιν ημεραις οικοδομων σωσον σεαυτον ει υιος ει του θεου καταβηθι απο του σταυρου'),
('grc_f35', 'Mateo 27:41', 'Mateo', 27, 41, 'ομοιως δε και οι αρχιερεις εμπαιζοντες μετα των γραμματεων και πρεσβυτερων και φαρισαιων ελεγον'),
('grc_f35', 'Mateo 27:42', 'Mateo', 27, 42, 'αλλους εσωσεν εαυτον ου δυναται σωσαι ει βασιλευς ισραηλ εστιν καταβατω νυν απο του σταυρου και πιστευσομεν επ αυτω'),
('grc_f35', 'Mateo 27:43', 'Mateo', 27, 43, 'πεποιθεν επι τον θεον ρυσασθω νυν αυτον ει θελει αυτον ειπεν γαρ οτι θεου ειμι υιος'),
('grc_f35', 'Mateo 27:44', 'Mateo', 27, 44, 'το δ αυτο και οι λησται οι συσταυρωθεντες αυτω ωνειδιζον αυτον'),
('grc_f35', 'Mateo 27:45', 'Mateo', 27, 45, 'απο δε εκτης ωρας σκοτος εγενετο επι πασαν την γην εως ωρας ενατης'),
('grc_f35', 'Mateo 27:46', 'Mateo', 27, 46, 'περι δε την ενατην ωραν ανεβοησεν ο ιησους φωνη μεγαλη λεγων ηλι ηλι λιμα σαβαχθανι τουτ εστιν θεε μου θεε μου ινα τι με εγκατελιπες'),
('grc_f35', 'Mateo 27:47', 'Mateo', 27, 47, 'τινες δε των εκει εστωτων ακουσαντες ελεγον οτι ηλιαν φωνει ουτος'),
('grc_f35', 'Mateo 27:48', 'Mateo', 27, 48, 'και ευθεως δραμων εις εξ αυτων και λαβων σπογγον πλησας τε οξους και περιθεις καλαμω εποτιζεν αυτον'),
('grc_f35', 'Mateo 27:49', 'Mateo', 27, 49, 'οι δε λοιποι ελεγον αφες ιδωμεν ει ερχεται ηλιας σωσων αυτον'),
('grc_f35', 'Mateo 27:50', 'Mateo', 27, 50, 'ο δε ιησους παλιν κραξας φωνη μεγαλη αφηκεν το πνευμα'),
('grc_f35', 'Mateo 27:51', 'Mateo', 27, 51, 'και ιδου το καταπετασμα του ναου εσχισθη εις δυο απο ανωθεν εως κατω και η γη εσεισθη και αι πετραι εσχισθησαν'),
('grc_f35', 'Mateo 27:52', 'Mateo', 27, 52, 'και τα μνημεια ανεωχθησαν και πολλα σωματα των κεκοιμημενων αγιων ηγερθη'),
('grc_f35', 'Mateo 27:53', 'Mateo', 27, 53, 'και εξελθοντες εκ των μνημειων μετα την εγερσιν αυτου εισηλθον εις την αγιαν πολιν και ενεφανισθησαν πολλοις'),
('grc_f35', 'Mateo 27:54', 'Mateo', 27, 54, 'ο δε εκατονταρχος και οι μετ αυτου τηρουντες τον ιησουν ιδοντες τον σεισμον και τα γενομενα εφοβηθησαν σφοδρα λεγοντες αληθως θεου υιος ην ουτος'),
('grc_f35', 'Mateo 27:55', 'Mateo', 27, 55, 'ησαν δε εκει και γυναικες πολλαι απο μακροθεν θεωρουσαι αιτινες ηκολουθησαν τω ιησου απο της γαλιλαιας διακονουσαι αυτω'),
('grc_f35', 'Mateo 27:56', 'Mateo', 27, 56, 'εν αις ην μαρια η μαγδαληνη και μαρια η του ιακωβου και ιωση μητηρ και η μητηρ των υιων ζεβεδαιου'),
('grc_f35', 'Mateo 27:57', 'Mateo', 27, 57, 'οψιας δε γενομενης ηλθεν ανθρωπος πλουσιος απο αριμαθαιας τουνομα ιωσηφ ος και αυτος εμαθητευσεν τω ιησου'),
('grc_f35', 'Mateo 27:58', 'Mateo', 27, 58, 'ουτος προσελθων τω πιλατω ητησατο το σωμα του ιησου τοτε ο πιλατος εκελευσεν αποδοθηναι το σωμα'),
('grc_f35', 'Mateo 27:59', 'Mateo', 27, 59, 'και λαβων το σωμα ο ιωσηφ ενετυλιξεν αυτο σινδονι καθαρα'),
('grc_f35', 'Mateo 27:60', 'Mateo', 27, 60, 'και εθηκεν αυτο εν τω καινω αυτου μνημειω ο ελατομησεν εν τη πετρα και προσκυλισας λιθον μεγαν τη θυρα του μνημειου απηλθεν'),
('grc_f35', 'Mateo 27:61', 'Mateo', 27, 61, 'ην δε εκει μαρια η μαγδαληνη και η αλλη μαρια καθημεναι απεναντι του ταφου'),
('grc_f35', 'Mateo 27:62', 'Mateo', 27, 62, 'τη δε επαυριον ητις εστιν μετα την παρασκευην συνηχθησαν οι αρχιερεις και οι φαρισαιοι προς πιλατον'),
('grc_f35', 'Mateo 27:63', 'Mateo', 27, 63, 'λεγοντες κυριε εμνησθημεν οτι εκεινος ο πλανος ειπεν ετι ζων μετα τρεις ημερας εγειρομαι'),
('grc_f35', 'Mateo 27:64', 'Mateo', 27, 64, 'κελευσον ουν ασφαλισθηναι τον ταφον εως της τριτης ημερας μηποτε ελθοντες οι μαθηται αυτου νυκτος κλεψωσιν αυτον και ειπωσιν τω λαω οτι ηγερθη απο των νεκρων και εσται η εσχατη πλανη χειρων της πρωτης'),
('grc_f35', 'Mateo 27:65', 'Mateo', 27, 65, 'εφη δε αυτοις ο πιλατος εχετε κουστωδιαν υπαγετε ασφαλισασθε ως οιδατε'),
('grc_f35', 'Mateo 27:66', 'Mateo', 27, 66, 'οι δε πορευθεντες ησφαλισαντο τον ταφον σφραγισαντες τον λιθον μετα της κουστωδιας'),
('grc_f35', 'Mateo 28:1', 'Mateo', 28, 1, 'οψε δε σαββατων τη επιφωσκουση εις μιαν σαββατων ηλθεν μαρια η μαγδαληνη και η αλλη μαρια θεωρησαι τον ταφον'),
('grc_f35', 'Mateo 28:2', 'Mateo', 28, 2, 'και ιδου σεισμος εγενετο μεγας αγγελος γαρ κυριου καταβας εξ ουρανου προσελθων απεκυλισεν τον λιθον απο της θυρας και εκαθητο επανω αυτου'),
('grc_f35', 'Mateo 28:3', 'Mateo', 28, 3, 'ην δε η ιδεα αυτου ως αστραπη και το ενδυμα αυτου λευκον ωσει χιων'),
('grc_f35', 'Mateo 28:4', 'Mateo', 28, 4, 'απο δε του φοβου αυτου εσεισθησαν οι τηρουντες και εγενοντο ωσει νεκροι'),
('grc_f35', 'Mateo 28:5', 'Mateo', 28, 5, 'αποκριθεις δε ο αγγελος ειπεν ταις γυναιξιν μη φοβεισθε υμεις οιδα γαρ οτι ιησουν τον εσταυρωμενον ζητειτε'),
('grc_f35', 'Mateo 28:6', 'Mateo', 28, 6, 'ουκ εστιν ωδε ηγερθη γαρ καθως ειπεν δευτε ιδετε τον τοπον οπου εκειτο ο κυριος'),
('grc_f35', 'Mateo 28:7', 'Mateo', 28, 7, 'και ταχυ πορευθεισαι ειπατε τοις μαθηταις αυτου οτι ηγερθη απο των νεκρων και ιδου προαγει υμας εις την γαλιλαιαν εκει αυτον οψεσθε ιδου ειπον υμιν'),
('grc_f35', 'Mateo 28:8', 'Mateo', 28, 8, 'και εξελθουσαι ταχυ απο του μνημειου μετα φοβου και χαρας μεγαλης εδραμον απαγγειλαι τοις μαθηταις αυτου'),
('grc_f35', 'Mateo 28:9', 'Mateo', 28, 9, 'ως δε επορευοντο απαγγειλαι τοις μαθηταις αυτου και ιδου ιησους απηντησεν αυταις λεγων χαιρετε αι δε προσελθουσαι εκρατησαν αυτου τους ποδας και προσεκυνησαν αυτω'),
('grc_f35', 'Mateo 28:10', 'Mateo', 28, 10, 'τοτε λεγει αυταις ο ιησους μη φοβεισθε υπαγετε απαγγειλατε τοις αδελφοις μου ινα απελθωσιν εις την γαλιλαιαν και εκει με οψονται'),
('grc_f35', 'Mateo 28:11', 'Mateo', 28, 11, 'πορευομενων δε αυτων ιδου τινες της κουστωδιας ελθοντες εις την πολιν απηγγειλαν τοις αρχιερευσιν απαντα τα γενομενα'),
('grc_f35', 'Mateo 28:12', 'Mateo', 28, 12, 'και συναχθεντες μετα των πρεσβυτερων συμβουλιον τε λαβοντες αργυρια ικανα εδωκαν τοις στρατιωταις'),
('grc_f35', 'Mateo 28:13', 'Mateo', 28, 13, 'λεγοντες ειπατε οτι οι μαθηται αυτου νυκτος ελθοντες εκλεψαν αυτον ημων κοιμωμενων'),
('grc_f35', 'Mateo 28:14', 'Mateo', 28, 14, 'και εαν ακουσθη τουτο επι του ηγεμονος ημεις πεισομεν αυτον και υμας αμεριμνους ποιησομεν'),
('grc_f35', 'Mateo 28:15', 'Mateo', 28, 15, 'οι δε λαβοντες τα αργυρια εποιησαν ως εδιδαχθησαν και διεφημισθη ο λογος ουτος παρα ιουδαιοις μεχρι της σημερον'),
('grc_f35', 'Mateo 28:16', 'Mateo', 28, 16, 'οι δε ενδεκα μαθηται επορευθησαν εις την γαλιλαιαν εις το ορος ου εταξατο αυτοις ο ιησους'),
('grc_f35', 'Mateo 28:17', 'Mateo', 28, 17, 'και ιδοντες αυτον προσεκυνησαν αυτω οι δε εδιστασαν'),
('grc_f35', 'Mateo 28:18', 'Mateo', 28, 18, 'και προσελθων ο ιησους ελαλησεν αυτοις λεγων εδοθη μοι πασα εξουσια εν ουρανω και επι γης'),
('grc_f35', 'Mateo 28:19', 'Mateo', 28, 19, 'πορευθεντες μαθητευσατε παντα τα εθνη βαπτιζοντες αυτους εις το ονομα του πατρος και του υιου και του αγιου πνευματος'),
('grc_f35', 'Mateo 28:20', 'Mateo', 28, 20, 'διδασκοντες αυτους τηρειν παντα οσα ενετειλαμην υμιν και ιδου εγω μεθ υμων ειμι πασας τας ημερας εως της συντελειας του αιωνος αμην'),
('grc_f35', 'Marcos 1:1', 'Marcos', 1, 1, 'αρχη του ευαγγελιου ιησου χριστου υιου του θεου'),
('grc_f35', 'Marcos 1:2', 'Marcos', 1, 2, 'ως γεγραπται εν τοις προφηταις ιδου εγω αποστελλω τον αγγελον μου προ προσωπου σου ος κατασκευασει την οδον σου εμπροσθεν σου'),
('grc_f35', 'Marcos 1:3', 'Marcos', 1, 3, 'φωνη βοωντος εν τη ερημω ετοιμασατε την οδον κυριου ευθειας ποιειτε τας τριβους αυτου'),
('grc_f35', 'Marcos 1:4', 'Marcos', 1, 4, 'εγενετο ιωαννης βαπτιζων εν τη ερημω και κηρυσσων βαπτισμα μετανοιας εις αφεσιν αμαρτιων'),
('grc_f35', 'Marcos 1:5', 'Marcos', 1, 5, 'και εξεπορευετο προς αυτον πασα η ιουδαια χωρα και οι ιεροσολυμιται και εβαπτιζοντο παντες εν τω ιορδανη ποταμω υπ αυτου εξομολογουμενοι τας αμαρτιας αυτων'),
('grc_f35', 'Marcos 1:6', 'Marcos', 1, 6, 'ην δε ο ιωαννης ενδεδυμενος τριχας καμηλου και ζωνην δερματινην περι την οσφυν αυτου και εσθιων ακριδας και μελι αγριον'),
('grc_f35', 'Marcos 1:7', 'Marcos', 1, 7, 'και εκηρυσσεν λεγων ερχεται ο ισχυροτερος μου οπισω μου ου ουκ ειμι ικανος κυψας λυσαι τον ιμαντα των υποδηματων αυτου'),
('grc_f35', 'Marcos 1:8', 'Marcos', 1, 8, 'εγω μεν εβαπτισα υμας εν υδατι αυτος δε βαπτισει υμας εν πνευματι αγιω'),
('grc_f35', 'Marcos 1:9', 'Marcos', 1, 9, 'και εγενετο εν εκειναις ταις ημεραις ηλθεν ο ιησους απο ναζαρετ της γαλιλαιας και εβαπτισθη υπο ιωαννου εις τον ιορδανην'),
('grc_f35', 'Marcos 1:10', 'Marcos', 1, 10, 'και ευθεως αναβαινων απο του υδατος ειδεν σχιζομενους τους ουρανους και το πνευμα ωσει περιστεραν καταβαινον επ αυτον'),
('grc_f35', 'Marcos 1:11', 'Marcos', 1, 11, 'και φωνη εγενετο εκ των ουρανων συ ει ο υιος μου ο αγαπητος εν ω ευδοκησα'),
('grc_f35', 'Marcos 1:12', 'Marcos', 1, 12, 'και ευθεως το πνευμα αυτον εκβαλλει εις την ερημον'),
('grc_f35', 'Marcos 1:13', 'Marcos', 1, 13, 'και ην εκει εν τη ερημω ημερας τεσσαρακοντα πειραζομενος υπο του σατανα και ην μετα των θηριων και οι αγγελοι διηκονουν αυτω'),
('grc_f35', 'Marcos 1:14', 'Marcos', 1, 14, 'μετα δε το παραδοθηναι τον ιωαννην ηλθεν ο ιησους εις την γαλιλαιαν κηρυσσων το ευαγγελιον της βασιλειας του θεου'),
('grc_f35', 'Marcos 1:15', 'Marcos', 1, 15, 'και λεγων οτι πεπληρωται ο καιρος και ηγγικεν η βασιλεια του θεου μετανοειτε και πιστευετε εν τω ευαγγελιω'),
('grc_f35', 'Marcos 1:16', 'Marcos', 1, 16, 'περιπατων δε παρα την θαλασσαν της γαλιλαιας ειδεν σιμωνα και ανδρεαν τον αδελφον αυτου του σιμωνος βαλλοντας αμφιβληστρον εν τη θαλασση ησαν γαρ αλιεις'),
('grc_f35', 'Marcos 1:17', 'Marcos', 1, 17, 'και ειπεν αυτοις ο ιησους δευτε οπισω μου και ποιησω υμας γενεσθαι αλιεις ανθρωπων'),
('grc_f35', 'Marcos 1:18', 'Marcos', 1, 18, 'και ευθεως αφεντες τα δικτυα αυτων ηκολουθησαν αυτω'),
('grc_f35', 'Marcos 1:19', 'Marcos', 1, 19, 'και προβας εκειθεν ολιγον ειδεν ιακωβον τον του ζεβεδαιου και ιωαννην τον αδελφον αυτου και αυτους εν τω πλοιω καταρτιζοντας τα δικτυα'),
('grc_f35', 'Marcos 1:20', 'Marcos', 1, 20, 'και ευθεως εκαλεσεν αυτους και αφεντες τον πατερα αυτων ζεβεδαιον εν τω πλοιω μετα των μισθωτων απηλθον οπισω αυτου'),
('grc_f35', 'Marcos 1:21', 'Marcos', 1, 21, 'και εισπορευονται εις καπερναουμ και ευθεως τοις σαββασιν εισελθων εις την συναγωγην εδιδασκεν'),
('grc_f35', 'Marcos 1:22', 'Marcos', 1, 22, 'και εξεπλησσοντο επι τη διδαχη αυτου ην γαρ διδασκων αυτους ως εξουσιαν εχων και ουχ ως οι γραμματεις'),
('grc_f35', 'Marcos 1:23', 'Marcos', 1, 23, 'και ην εν τη συναγωγη αυτων ανθρωπος εν πνευματι ακαθαρτω και ανεκραξεν'),
('grc_f35', 'Marcos 1:24', 'Marcos', 1, 24, 'λεγων εα τι ημιν και σοι ιησου ναζαρηνε ηλθες απολεσαι ημας οιδα σε τις ει ο αγιος του θεου'),
('grc_f35', 'Marcos 1:25', 'Marcos', 1, 25, 'και επετιμησεν αυτω ο ιησους λεγων φιμωθητι και εξελθε εξ αυτου'),
('grc_f35', 'Marcos 1:26', 'Marcos', 1, 26, 'και σπαραξαν αυτον το πνευμα το ακαθαρτον και κραξαν φωνη μεγαλη εξηλθεν εξ αυτου'),
('grc_f35', 'Marcos 1:27', 'Marcos', 1, 27, 'και εθαμβηθησαν παντες ωστε συζητειν προς εαυτους λεγοντας τι εστιν τουτο τις η διδαχη η καινη αυτη οτι κατ εξουσιαν και τοις πνευμασιν τοις ακαθαρτοις επιτασσει και υπακουουσιν αυτω'),
('grc_f35', 'Marcos 1:28', 'Marcos', 1, 28, 'εξηλθεν δε η ακοη αυτου ευθυς εις ολην την περιχωρον της γαλιλαιας'),
('grc_f35', 'Marcos 1:29', 'Marcos', 1, 29, 'και ευθεως εκ της συναγωγης εξελθοντες ηλθον εις την οικιαν σιμωνος και ανδρεου μετα ιακωβου και ιωαννου'),
('grc_f35', 'Marcos 1:30', 'Marcos', 1, 30, 'η δε πενθερα του σιμωνος κατεκειτο πυρεσσουσα και ευθεως λεγουσιν αυτω περι αυτης'),
('grc_f35', 'Marcos 1:31', 'Marcos', 1, 31, 'και προσελθων ηγειρεν αυτην κρατησας της χειρος αυτης και αφηκεν αυτην ο πυρετος ευθεως και διηκονει αυτοις'),
('grc_f35', 'Marcos 1:32', 'Marcos', 1, 32, 'οψιας δε γενομενης οτε εδυ ο ηλιος εφερον προς αυτον παντας τους κακως εχοντας και τους δαιμονιζομενους'),
('grc_f35', 'Marcos 1:33', 'Marcos', 1, 33, 'και η πολις ολη επισυνηγμενη ην προς την θυραν'),
('grc_f35', 'Marcos 1:34', 'Marcos', 1, 34, 'και εθεραπευσεν πολλους κακως εχοντας ποικιλαις νοσοις και δαιμονια πολλα εξεβαλεν και ουκ ηφιεν λαλειν τα δαιμονια οτι ηδεισαν αυτον χριστον ειναι'),
('grc_f35', 'Marcos 1:35', 'Marcos', 1, 35, 'και πρωι εννυχον λιαν αναστας εξηλθεν και απηλθεν εις ερημον τοπον κακει προσηυχετο'),
('grc_f35', 'Marcos 1:36', 'Marcos', 1, 36, 'και κατεδιωξαν αυτον ο σιμων και οι μετ αυτου'),
('grc_f35', 'Marcos 1:37', 'Marcos', 1, 37, 'και ευροντες αυτον λεγουσιν αυτω οτι παντες σε ζητουσιν'),
('grc_f35', 'Marcos 1:38', 'Marcos', 1, 38, 'και λεγει αυτοις αγωμεν εις τας εχομενας κωμοπολεις ινα και εκει κηρυξω εις τουτο γαρ εληλυθα'),
('grc_f35', 'Marcos 1:39', 'Marcos', 1, 39, 'και ην κηρυσσων εν ταις συναγωγαις αυτων εις ολην την γαλιλαιαν και τα δαιμονια εκβαλλων'),
('grc_f35', 'Marcos 1:40', 'Marcos', 1, 40, 'και ερχεται προς αυτον λεπρος παρακαλων αυτον και γονυπετων αυτον και λεγων αυτω οτι εαν θελης δυνασαι με καθαρισαι'),
('grc_f35', 'Marcos 1:41', 'Marcos', 1, 41, 'ο δε ιησους σπλαγχνισθεις εκτεινας την χειρα ηψατο αυτου και λεγει αυτω θελω καθαρισθητι'),
('grc_f35', 'Marcos 1:42', 'Marcos', 1, 42, 'και ειποντος αυτου ευθεως απηλθεν απ αυτου η λεπρα και εκαθαρισθη'),
('grc_f35', 'Marcos 1:43', 'Marcos', 1, 43, 'και εμβριμησαμενος αυτω ευθεως εξεβαλεν αυτον'),
('grc_f35', 'Marcos 1:44', 'Marcos', 1, 44, 'και λεγει αυτω ορα μηδενι μηδεν ειπης αλλ υπαγε σεαυτον δειξον τω ιερει και προσενεγκαι περι του καθαρισμου σου α προσεταξεν μωσης εις μαρτυριον αυτοις'),
('grc_f35', 'Marcos 1:45', 'Marcos', 1, 45, 'ο δε εξελθων ηρξατο κηρυσσειν πολλα και διαφημιζειν τον λογον ωστε μηκετι αυτον δυνασθαι φανερως εις πολιν εισελθειν αλλ εξω εν ερημοις τοποις ην και ηρχοντο προς αυτον πανταχοθεν'),
('grc_f35', 'Marcos 2:1', 'Marcos', 2, 1, 'και εισηλθεν παλιν εις καπερναουμ δι ημερων και ηκουσθη οτι εις οικον εστιν'),
('grc_f35', 'Marcos 2:2', 'Marcos', 2, 2, 'και ευθεως συνηχθησαν πολλοι ωστε μηκετι χωρειν μηδε τα προς την θυραν και ελαλει αυτοις τον λογον'),
('grc_f35', 'Marcos 2:3', 'Marcos', 2, 3, 'και ερχονται προς αυτον παραλυτικον φεροντες αιρομενον υπο τεσσαρων'),
('grc_f35', 'Marcos 2:4', 'Marcos', 2, 4, 'και μη δυναμενοι προσεγγισαι αυτω δια τον οχλον απεστεγασαν την στεγην οπου ην και εξορυξαντες χαλωσιν τον κραββατον εφ ω ο παραλυτικος κατεκειτο'),
('grc_f35', 'Marcos 2:5', 'Marcos', 2, 5, 'ιδων δε ο ιησους την πιστιν αυτων λεγει τω παραλυτικω τεκνον αφεωνται σοι αι αμαρτιαι σου'),
('grc_f35', 'Marcos 2:6', 'Marcos', 2, 6, 'ησαν δε τινες των γραμματεων εκει καθημενοι και διαλογιζομενοι εν ταις καρδιαις αυτων'),
('grc_f35', 'Marcos 2:7', 'Marcos', 2, 7, 'τι ουτος ουτως λαλει βλασφημιας τις δυναται αφιεναι αμαρτιας ει μη εις ο θεος'),
('grc_f35', 'Marcos 2:8', 'Marcos', 2, 8, 'και ευθεως επιγνους ο ιησους τω πνευματι αυτου οτι ουτως αυτοι διαλογιζονται εν εαυτοις ειπεν αυτοις τι ταυτα διαλογιζεσθε εν ταις καρδιαις υμων'),
('grc_f35', 'Marcos 2:9', 'Marcos', 2, 9, 'τι εστιν ευκοπωτερον ειπειν τω παραλυτικω αφεωνται σου αι αμαρτιαι η ειπειν εγειραι και αρον τον κραββατον σου και περιπατει'),
('grc_f35', 'Marcos 2:10', 'Marcos', 2, 10, 'ινα δε ειδητε οτι εξουσιαν εχει ο υιος του ανθρωπου επι της γης αφιεναι αμαρτιας λεγει τω παραλυτικω'),
('grc_f35', 'Marcos 2:11', 'Marcos', 2, 11, 'σοι λεγω εγειραι και αρον τον κραββατον σου και υπαγε εις τον οικον σου'),
('grc_f35', 'Marcos 2:12', 'Marcos', 2, 12, 'και ηγερθη ευθεως και αρας τον κραββατον εξηλθεν εναντιον παντων ωστε εξιστασθαι παντας και δοξαζειν τον θεον λεγοντας οτι ουδεποτε ουτως ειδομεν'),
('grc_f35', 'Marcos 2:13', 'Marcos', 2, 13, 'και εξηλθεν παλιν παρα την θαλασσαν και πας ο οχλος ηρχετο προς αυτον και εδιδασκεν αυτους'),
('grc_f35', 'Marcos 2:14', 'Marcos', 2, 14, 'και παραγων ειδεν λευιν τον του αλφαιου καθημενον επι το τελωνιον και λεγει αυτω ακολουθει μοι και αναστας ηκολουθησεν αυτω'),
('grc_f35', 'Marcos 2:15', 'Marcos', 2, 15, 'και εγενετο εν τω κατακεισθαι αυτον εν τη οικια αυτου και πολλοι τελωναι και αμαρτωλοι συνανεκειντο τω ιησου και τοις μαθηταις αυτου ησαν γαρ πολλοι και ηκολουθησαν αυτω'),
('grc_f35', 'Marcos 2:16', 'Marcos', 2, 16, 'και οι γραμματεις και οι φαρισαιοι ιδοντες αυτον εσθιοντα μετα των τελωνων και αμαρτωλων ελεγον τοις μαθηταις αυτου τι οτι μετα των τελωνων και αμαρτωλων εσθιει και πινει'),
('grc_f35', 'Marcos 2:17', 'Marcos', 2, 17, 'και ακουσας ο ιησους λεγει αυτοις ου χρειαν εχουσιν οι ισχυοντες ιατρου αλλ οι κακως εχοντες ουκ ηλθον καλεσαι δικαιους αλλα αμαρτωλους εις μετανοιαν'),
('grc_f35', 'Marcos 2:18', 'Marcos', 2, 18, 'και ησαν οι μαθηται ιωαννου και οι των φαρισαιων νηστευοντες και ερχονται και λεγουσιν αυτω δια τι οι μαθηται ιωαννου και οι των φαρισαιων νηστευουσιν οι δε σοι μαθηται ου νηστευουσιν'),
('grc_f35', 'Marcos 2:19', 'Marcos', 2, 19, 'και ειπεν αυτοις ο ιησους μη δυνανται οι υιοι του νυμφωνος εν ω ο νυμφιος μετ αυτων εστιν νηστευειν οσον χρονον μεθ εαυτων εχουσιν τον νυμφιον ου δυνανται νηστευειν'),
('grc_f35', 'Marcos 2:20', 'Marcos', 2, 20, 'ελευσονται δε ημεραι οταν απαρθη απ αυτων ο νυμφιος και τοτε νηστευσουσιν εν εκειναις ταις ημεραις'),
('grc_f35', 'Marcos 2:21', 'Marcos', 2, 21, 'και ουδεις επιβλημα ρακους αγναφου επιρραπτει επι ιματιω παλαιω ει δε μη αιρει το πληρωμα αυτου το καινον του παλαιου και χειρον σχισμα γινεται'),
('grc_f35', 'Marcos 2:22', 'Marcos', 2, 22, 'και ουδεις βαλλει οινον νεον εις ασκους παλαιους ει δε μη ρησσει ο οινος ο νεος τους ασκους και ο οινος εκχειται και οι ασκοι απολουνται αλλα οινον νεον εις ασκους καινους βλητεον'),
('grc_f35', 'Marcos 2:23', 'Marcos', 2, 23, 'και εγενετο παραπορευεσθαι αυτον εν τοις σαββασιν δια των σποριμων και ηρξαντο οι μαθηται αυτου οδον ποιειν τιλλοντες τους σταχυας'),
('grc_f35', 'Marcos 2:24', 'Marcos', 2, 24, 'και οι φαρισαιοι ελεγον αυτω ιδε τι ποιουσιν εν τοις σαββασιν ο ουκ εξεστιν'),
('grc_f35', 'Marcos 2:25', 'Marcos', 2, 25, 'και αυτος ελεγεν αυτοις ουδεποτε ανεγνωτε τι εποιησεν δαυιδ οτε χρειαν εσχεν και επεινασεν αυτος και οι μετ αυτου'),
('grc_f35', 'Marcos 2:26', 'Marcos', 2, 26, 'πως εισηλθεν εις τον οικον του θεου επι αβιαθαρ αρχιερεως και τους αρτους της προθεσεως εφαγεν ους ουκ εξεστιν φαγειν ει μη τοις ιερευσιν και εδωκεν και τοις συν αυτω ουσιν'),
('grc_f35', 'Marcos 2:27', 'Marcos', 2, 27, 'και ελεγεν αυτοις το σαββατον δια τον ανθρωπον εγενετο ουχ ο ανθρωπος δια το σαββατον'),
('grc_f35', 'Marcos 2:28', 'Marcos', 2, 28, 'ωστε κυριος εστιν ο υιος του ανθρωπου και του σαββατου'),
('grc_f35', 'Marcos 3:1', 'Marcos', 3, 1, 'και εισηλθεν παλιν εις την συναγωγην και ην εκει ανθρωπος εξηραμμενην εχων την χειρα'),
('grc_f35', 'Marcos 3:2', 'Marcos', 3, 2, 'και παρετηρουν αυτον ει τοις σαββασιν θεραπευσει αυτον ινα κατηγορησωσιν αυτου'),
('grc_f35', 'Marcos 3:3', 'Marcos', 3, 3, 'και λεγει τω ανθρωπω τω εξηραμμενην εχοντι την χειρα εγειραι εις το μεσον'),
('grc_f35', 'Marcos 3:4', 'Marcos', 3, 4, 'και λεγει αυτοις εξεστιν τοις σαββασιν αγαθοποιησαι η κακοποιησαι ψυχην σωσαι η αποκτειναι οι δε εσιωπων'),
('grc_f35', 'Marcos 3:5', 'Marcos', 3, 5, 'και περιβλεψαμενος αυτους μετ οργης συλλυπουμενος επι τη πωρωσει της καρδιας αυτων λεγει τω ανθρωπω εκτεινον την χειρα σου και εξετεινεν και αποκατεσταθη η χειρ αυτου υγιης ως η αλλη'),
('grc_f35', 'Marcos 3:6', 'Marcos', 3, 6, 'και εξελθοντες οι φαρισαιοι ευθεως μετα των ηρωδιανων συμβουλιον εποιουν κατ αυτου οπως αυτον απολεσωσιν'),
('grc_f35', 'Marcos 3:7', 'Marcos', 3, 7, 'και ο ιησους ανεχωρησεν μετα των μαθητων αυτου προς την θαλασσαν και πολυ πληθος απο της γαλιλαιας ηκολουθησεν αυτω και απο της ιουδαιας'),
('grc_f35', 'Marcos 3:8', 'Marcos', 3, 8, 'και απο ιεροσολυμων και απο της ιδουμαιας και περαν του ιορδανου και οι περι τυρον και σιδωνα πληθος πολυ ακουσαντες οσα εποιει ηλθον προς αυτον'),
('grc_f35', 'Marcos 3:9', 'Marcos', 3, 9, 'και ειπεν τοις μαθηταις αυτου ινα πλοιαριον προσκαρτερη αυτω δια τον οχλον ινα μη θλιβωσιν αυτον'),
('grc_f35', 'Marcos 3:10', 'Marcos', 3, 10, 'πολλους γαρ εθεραπευσεν ωστε επιπιπτειν αυτω ινα αυτου αψωνται οσοι ειχον μαστιγας'),
('grc_f35', 'Marcos 3:11', 'Marcos', 3, 11, 'και τα πνευματα τα ακαθαρτα οταν αυτον εθεωρει προσεπιπτεν αυτω και εκραζεν λεγοντα οτι συ ει ο υιος του θεου'),
('grc_f35', 'Marcos 3:12', 'Marcos', 3, 12, 'και πολλα επετιμα αυτοις ινα μη φανερον αυτον ποιησωσιν'),
('grc_f35', 'Marcos 3:13', 'Marcos', 3, 13, 'και αναβαινει εις το ορος και προσκαλειται ους ηθελεν αυτος και απηλθον προς αυτον'),
('grc_f35', 'Marcos 3:14', 'Marcos', 3, 14, 'και εποιησεν δωδεκα ινα ωσιν μετ αυτου και ινα αποστελλη αυτους κηρυσσειν'),
('grc_f35', 'Marcos 3:15', 'Marcos', 3, 15, 'και εχειν εξουσιαν θεραπευειν τας νοσους και εκβαλλειν τα δαιμονια'),
('grc_f35', 'Marcos 3:16', 'Marcos', 3, 16, 'και επεθηκεν τω σιμωνι ονομα πετρον'),
('grc_f35', 'Marcos 3:17', 'Marcos', 3, 17, 'και ιακωβον τον του ζεβεδαιου και ιωαννην τον αδελφον του ιακωβου και επεθηκεν αυτοις ονοματα βοανεργες ο εστιν υιοι βροντης'),
('grc_f35', 'Marcos 3:18', 'Marcos', 3, 18, 'και ανδρεαν και φιλιππον και βαρθολομαιον και ματθαιον και θωμαν και ιακωβον τον του αλφαιου και θαδδαιον και σιμωνα τον κανανιτην'),
('grc_f35', 'Marcos 3:19', 'Marcos', 3, 19, 'και ιουδαν ισκαριωτην ος και παρεδωκεν αυτον'),
('grc_f35', 'Marcos 3:20', 'Marcos', 3, 20, 'και ερχονται εις οικον και συνερχεται παλιν οχλος ωστε μη δυνασθαι αυτους μηδε αρτον φαγειν'),
('grc_f35', 'Marcos 3:21', 'Marcos', 3, 21, 'και ακουσαντες οι παρ αυτου εξηλθον κρατησαι αυτον ελεγον γαρ οτι εξεστη'),
('grc_f35', 'Marcos 3:22', 'Marcos', 3, 22, 'και οι γραμματεις οι απο ιεροσολυμων καταβαντες ελεγον οτι βεελζεβουλ εχει και οτι εν τω αρχοντι των δαιμονιων εκβαλλει τα δαιμονια'),
('grc_f35', 'Marcos 3:23', 'Marcos', 3, 23, 'και προσκαλεσαμενος αυτους εν παραβολαις ελεγεν αυτοις πως δυναται σατανας σαταναν εκβαλλειν'),
('grc_f35', 'Marcos 3:24', 'Marcos', 3, 24, 'και εαν βασιλεια εφ εαυτην μερισθη ου δυναται σταθηναι η βασιλεια εκεινη'),
('grc_f35', 'Marcos 3:25', 'Marcos', 3, 25, 'και εαν οικια εφ εαυτην μερισθη ου δυναται σταθηναι η οικια εκεινη'),
('grc_f35', 'Marcos 3:26', 'Marcos', 3, 26, 'και ει ο σατανας ανεστη εφ εαυτον και μεμερισται ου δυναται σταθηναι αλλα τελος εχει'),
('grc_f35', 'Marcos 3:27', 'Marcos', 3, 27, 'ουδεις δυναται τα σκευη του ισχυρου εισελθων εις την οικιαν αυτου διαρπασαι εαν μη πρωτον τον ισχυρον δηση και τοτε την οικιαν αυτου διαρπαση'),
('grc_f35', 'Marcos 3:28', 'Marcos', 3, 28, 'αμην λεγω υμιν οτι παντα αφεθησεται τα αμαρτηματα τοις υιοις των ανθρωπων και βλασφημιαι οσας αν βλασφημησωσιν'),
('grc_f35', 'Marcos 3:29', 'Marcos', 3, 29, 'ος δ αν βλασφημηση εις το πνευμα το αγιον ουκ εχει αφεσιν εις τον αιωνα αλλ ενοχος εστιν αιωνιου κρισεως'),
('grc_f35', 'Marcos 3:30', 'Marcos', 3, 30, 'οτι ελεγον πνευμα ακαθαρτον εχει'),
('grc_f35', 'Marcos 3:31', 'Marcos', 3, 31, 'ερχονται ουν οι αδελφοι και η μητηρ αυτου και εξω εστωτες απεστειλαν προς αυτον φωνουντες αυτον'),
('grc_f35', 'Marcos 3:32', 'Marcos', 3, 32, 'και εκαθητο οχλος περι αυτον ειπον δε αυτω ιδου η μητηρ σου και οι αδελφοι σου και αι αδελφαι σου εξω ζητουσιν σε'),
('grc_f35', 'Marcos 3:33', 'Marcos', 3, 33, 'και απεκριθη αυτοις λεγων τις εστιν η μητηρ μου η οι αδελφοι μου'),
('grc_f35', 'Marcos 3:34', 'Marcos', 3, 34, 'και περιβλεψαμενος κυκλω τους περι αυτον καθημενους λεγει ιδου η μητηρ μου και οι αδελφοι μου'),
('grc_f35', 'Marcos 3:35', 'Marcos', 3, 35, 'ος γαρ αν ποιηση το θελημα του θεου ουτος αδελφος μου και αδελφη μου και μητηρ μου εστιν'),
('grc_f35', 'Marcos 4:1', 'Marcos', 4, 1, 'και παλιν ηρξατο διδασκειν παρα την θαλασσαν και συνηχθη προς αυτον οχλος πολυς ωστε αυτον εμβαντα εις το πλοιον καθησθαι εν τη θαλασση και πας ο οχλος προς την θαλασσαν επι της γης ην'),
('grc_f35', 'Marcos 4:2', 'Marcos', 4, 2, 'και εδιδασκεν αυτους εν παραβολαις πολλα και ελεγεν αυτοις εν τη διδαχη αυτου'),
('grc_f35', 'Marcos 4:3', 'Marcos', 4, 3, 'ακουετε ιδου εξηλθεν ο σπειρων του σπειραι'),
('grc_f35', 'Marcos 4:4', 'Marcos', 4, 4, 'και εγενετο εν τω σπειρειν ο μεν επεσεν παρα την οδον και ηλθεν τα πετεινα και κατεφαγεν αυτο'),
('grc_f35', 'Marcos 4:5', 'Marcos', 4, 5, 'αλλο δε επεσεν επι το πετρωδες οπου ουκ ειχεν γην πολλην και ευθεως εξανετειλεν δια το μη εχειν βαθος γης'),
('grc_f35', 'Marcos 4:6', 'Marcos', 4, 6, 'ηλιου δε ανατειλαντος εκαυματισθη και δια το μη εχειν ριζαν εξηρανθη'),
('grc_f35', 'Marcos 4:7', 'Marcos', 4, 7, 'και αλλο επεσεν εις τας ακανθας και ανεβησαν αι ακανθαι και συνεπνιξαν αυτο και καρπον ουκ εδωκεν'),
('grc_f35', 'Marcos 4:8', 'Marcos', 4, 8, 'και αλλο επεσεν εις την γην την καλην και εδιδου καρπον αναβαινοντα και αυξανοντα και εφερεν εν τριακοντα και εν εξηκοντα και εν εκατον'),
('grc_f35', 'Marcos 4:9', 'Marcos', 4, 9, 'και ελεγεν ο εχων ωτα ακουειν ακουετω'),
('grc_f35', 'Marcos 4:10', 'Marcos', 4, 10, 'οτε δε εγενετο κατα μονας ηρωτησαν αυτον οι περι αυτον συν τοις δωδεκα την παραβολην'),
('grc_f35', 'Marcos 4:11', 'Marcos', 4, 11, 'και ελεγεν αυτοις υμιν δεδοται γνωναι το μυστηριον της βασιλειας του θεου εκεινοις δε τοις εξω εν παραβολαις τα παντα γινεται'),
('grc_f35', 'Marcos 4:12', 'Marcos', 4, 12, 'ινα βλεποντες βλεπωσιν και μη ιδωσιν και ακουοντες ακουωσιν και μη συνιωσιν μηποτε επιστρεψωσιν και αφεθη αυτοις τα αμαρτηματα'),
('grc_f35', 'Marcos 4:13', 'Marcos', 4, 13, 'και λεγει αυτοις ουκ οιδατε την παραβολην ταυτην και πως πασας τας παραβολας γνωσεσθε'),
('grc_f35', 'Marcos 4:14', 'Marcos', 4, 14, 'ο σπειρων τον λογον σπειρει'),
('grc_f35', 'Marcos 4:15', 'Marcos', 4, 15, 'ουτοι δε εισιν οι παρα την οδον οπου σπειρεται ο λογος και οταν ακουσωσιν ευθεως ερχεται ο σατανας και αιρει τον λογον τον εσπαρμενον εν ταις καρδιαις αυτων'),
('grc_f35', 'Marcos 4:16', 'Marcos', 4, 16, 'και ουτοι εισιν ομοιως οι επι τα πετρωδη σπειρομενοι οι οταν ακουσωσιν τον λογον ευθεως μετα χαρας λαμβανουσιν αυτον'),
('grc_f35', 'Marcos 4:17', 'Marcos', 4, 17, 'και ουκ εχουσιν ριζαν εν εαυτοις αλλα προσκαιροι εισιν ειτα γενομενης θλιψεως η διωγμου δια τον λογον ευθεως σκανδαλιζονται'),
('grc_f35', 'Marcos 4:18', 'Marcos', 4, 18, 'και ουτοι εισιν οι εις τας ακανθας σπειρομενοι οι τον λογον ακουοντες'),
('grc_f35', 'Marcos 4:19', 'Marcos', 4, 19, 'και αι μεριμναι του αιωνος τουτου και η απατη του πλουτου και αι περι τα λοιπα επιθυμιαι εισπορευομεναι συμπνιγουσιν τον λογον και ακαρπος γινεται'),
('grc_f35', 'Marcos 4:20', 'Marcos', 4, 20, 'και ουτοι εισιν οι επι την γην την καλην σπαρεντες οιτινες ακουουσιν τον λογον και παραδεχονται και καρποφορουσιν εν τριακοντα και εν εξηκοντα και εν εκατον'),
('grc_f35', 'Marcos 4:21', 'Marcos', 4, 21, 'και ελεγεν αυτοις μητι ο λυχνος ερχεται ινα υπο τον μοδιον τεθη η υπο την κλινην ουχ ινα επι την λυχνιαν επιτεθη'),
('grc_f35', 'Marcos 4:22', 'Marcos', 4, 22, 'ου γαρ εστιν κρυπτον ο εαν μη φανερωθη ουδε εγενετο αποκρυφον αλλ ινα εις φανερον ελθη'),
('grc_f35', 'Marcos 4:23', 'Marcos', 4, 23, 'ει τις εχει ωτα ακουειν ακουετω'),
('grc_f35', 'Marcos 4:24', 'Marcos', 4, 24, 'και ελεγεν αυτοις βλεπετε τι ακουετε εν ω μετρω μετρειτε αντιμετρηθησεται υμιν και προστεθησεται υμιν τοις ακουουσιν'),
('grc_f35', 'Marcos 4:25', 'Marcos', 4, 25, 'ος γαρ αν εχη δοθησεται αυτω και ος ουκ εχει και ο εχει αρθησεται απ αυτου'),
('grc_f35', 'Marcos 4:26', 'Marcos', 4, 26, 'και ελεγεν ουτως εστιν η βασιλεια του θεου ως εαν ανθρωπος βαλη τον σπορον επι της γης'),
('grc_f35', 'Marcos 4:27', 'Marcos', 4, 27, 'και καθευδη και εγειρηται νυκτα και ημεραν και ο σπορος βλαστανη και μηκυνηται ως ουκ οιδεν αυτος'),
('grc_f35', 'Marcos 4:28', 'Marcos', 4, 28, 'αυτοματη γαρ η γη καρποφορει πρωτον χορτον ειτα σταχυν ειτα πληρη σιτον εν τω σταχυι'),
('grc_f35', 'Marcos 4:29', 'Marcos', 4, 29, 'οταν δε παραδω ο καρπος ευθεως αποστελλει το δρεπανον οτι παρεστηκεν ο θερισμος'),
('grc_f35', 'Marcos 4:30', 'Marcos', 4, 30, 'και ελεγεν τινι ομοιωσομεν την βασιλειαν του θεου η εν ποια παραβολη παραβαλωμεν αυτην'),
('grc_f35', 'Marcos 4:31', 'Marcos', 4, 31, 'ως κοκκον σιναπεως ος οταν σπαρη επι της γης μικροτερος παντων των σπερματων εστιν των επι της γης'),
('grc_f35', 'Marcos 4:32', 'Marcos', 4, 32, 'και οταν σπαρη αναβαινει και γινεται παντων των λαχανων μειζων και ποιει κλαδους μεγαλους ωστε δυνασθαι υπο την σκιαν αυτου τα πετεινα του ουρανου κατασκηνουν'),
('grc_f35', 'Marcos 4:33', 'Marcos', 4, 33, 'και τοιαυταις παραβολαις πολλαις ελαλει αυτοις τον λογον καθως εδυναντο ακουειν'),
('grc_f35', 'Marcos 4:34', 'Marcos', 4, 34, 'χωρις δε παραβολης ουκ ελαλει αυτοις κατ ιδιαν δε τοις μαθηταις αυτου επελυεν παντα'),
('grc_f35', 'Marcos 4:35', 'Marcos', 4, 35, 'και λεγει αυτοις εν εκεινη τη ημερα οψιας γενομενης διελθωμεν εις το περαν'),
('grc_f35', 'Marcos 4:36', 'Marcos', 4, 36, 'και αφεντες τον οχλον παραλαμβανουσιν αυτον ως ην εν τω πλοιω και αλλα δε πλοιαρια ην μετ αυτου'),
('grc_f35', 'Marcos 4:37', 'Marcos', 4, 37, 'και γινεται λαιλαψ ανεμου μεγαλη τα δε κυματα επεβαλεν εις το πλοιον ωστε αυτο ηδη γεμιζεσθαι'),
('grc_f35', 'Marcos 4:38', 'Marcos', 4, 38, 'και ην αυτος επι τη πρυμνη επι το προσκεφαλαιον καθευδων και διεγειρουσιν αυτον και λεγουσιν αυτω διδασκαλε ου μελει σοι οτι απολλυμεθα'),
('grc_f35', 'Marcos 4:39', 'Marcos', 4, 39, 'και διεγερθεις επετιμησεν τω ανεμω και ειπεν τη θαλασση σιωπα πεφιμωσο και εκοπασεν ο ανεμος και εγενετο γαληνη μεγαλη'),
('grc_f35', 'Marcos 4:40', 'Marcos', 4, 40, 'και ειπεν αυτοις τι δειλοι εστε ουτως πως ουκ εχετε πιστιν'),
('grc_f35', 'Marcos 4:41', 'Marcos', 4, 41, 'και εφοβηθησαν φοβον μεγαν και ελεγον προς αλληλους τις αρα ουτος εστιν οτι και ο ανεμος και η θαλασσα υπακουουσιν αυτω'),
('grc_f35', 'Marcos 5:1', 'Marcos', 5, 1, 'και ηλθον εις το περαν της θαλασσης εις την χωραν των γαδαρηνων'),
('grc_f35', 'Marcos 5:2', 'Marcos', 5, 2, 'και εξελθοντι αυτω εκ του πλοιου ευθεως απηντησεν αυτω εκ των μνημειων ανθρωπος εν πνευματι ακαθαρτω'),
('grc_f35', 'Marcos 5:3', 'Marcos', 5, 3, 'ος την οικησιν ειχεν εν τοις μνημασιν και ουτε αλυσεσιν ουδεις ηδυνατο αυτον δησαι'),
('grc_f35', 'Marcos 5:4', 'Marcos', 5, 4, 'δια το αυτον πολλακις πεδαις και αλυσεσιν δεδεσθαι και διεσπασθαι υπ αυτου τας αλυσεις και τας πεδας συντετριφθαι και ουδεις αυτον ισχυσεν δαμασαι'),
('grc_f35', 'Marcos 5:5', 'Marcos', 5, 5, 'και δια παντος νυκτος και ημερας εν τοις μνημασιν και εν τοις ορεσιν ην κραζων και κατακοπτων εαυτον λιθοις'),
('grc_f35', 'Marcos 5:6', 'Marcos', 5, 6, 'ιδων δε τον ιησουν απο μακροθεν εδραμεν και προσεκυνησεν αυτω'),
('grc_f35', 'Marcos 5:7', 'Marcos', 5, 7, 'και κραξας φωνη μεγαλη ειπεν τι εμοι και σοι ιησου υιε του θεου του υψιστου ορκιζω σε τον θεον μη με βασανισης'),
('grc_f35', 'Marcos 5:8', 'Marcos', 5, 8, 'ελεγεν γαρ αυτω εξελθε το πνευμα το ακαθαρτον εκ του ανθρωπου'),
('grc_f35', 'Marcos 5:9', 'Marcos', 5, 9, 'και επηρωτα αυτον τι σοι ονομα και απεκριθη λεγων λεγεων ονομα μοι οτι πολλοι εσμεν'),
('grc_f35', 'Marcos 5:10', 'Marcos', 5, 10, 'και παρεκαλει αυτον πολλα ινα μη αυτους αποστειλη εξω της χωρας'),
('grc_f35', 'Marcos 5:11', 'Marcos', 5, 11, 'ην δε εκει προς τω ορει αγελη χοιρων μεγαλη βοσκομενη'),
('grc_f35', 'Marcos 5:12', 'Marcos', 5, 12, 'και παρεκαλεσαν αυτον παντες οι δαιμονες λεγοντες πεμψον ημας εις τους χοιρους ινα εις αυτους εισελθωμεν'),
('grc_f35', 'Marcos 5:13', 'Marcos', 5, 13, 'και επετρεψεν αυτοις ευθεως ο ιησους και εξελθοντα τα πνευματα τα ακαθαρτα εισηλθον εις τους χοιρους και ωρμησεν η αγελη κατα του κρημνου εις την θαλασσαν ησαν δε ως δισχιλιοι και επνιγοντο εν τη θαλασση'),
('grc_f35', 'Marcos 5:14', 'Marcos', 5, 14, 'οι δε βοσκοντες τους χοιρους εφυγον και ανηγγειλαν εις την πολιν και εις τους αγρους και εξηλθον ιδειν τι εστιν το γεγονος'),
('grc_f35', 'Marcos 5:15', 'Marcos', 5, 15, 'και ερχονται προς τον ιησουν και θεωρουσιν τον δαιμονιζομενον καθημενον και ιματισμενον και σωφρονουντα τον εσχηκοτα τον λεγεωνα και εφοβηθησαν'),
('grc_f35', 'Marcos 5:16', 'Marcos', 5, 16, 'διηγησαντο δε αυτοις οι ιδοντες πως εγενετο τω δαιμονιζομενω και περι των χοιρων'),
('grc_f35', 'Marcos 5:17', 'Marcos', 5, 17, 'και ηρξαντο παρακαλειν αυτον απελθειν απο των οριων αυτων'),
('grc_f35', 'Marcos 5:18', 'Marcos', 5, 18, 'και εμβαντος αυτου εις το πλοιον παρεκαλει αυτον ο δαιμονισθεις ινα η μετ αυτου'),
('grc_f35', 'Marcos 5:19', 'Marcos', 5, 19, 'ο δε ιησους ουκ αφηκεν αυτον αλλα λεγει αυτω υπαγε εις τον οικον σου προς τους σους και αναγγειλον αυτοις οσα σοι ο κυριος πεποιηκεν και ηλεησεν σε'),
('grc_f35', 'Marcos 5:20', 'Marcos', 5, 20, 'και απηλθεν και ηρξατο κηρυσσειν εν τη δεκαπολει οσα εποιησεν αυτω ο ιησους και παντες εθαυμαζον'),
('grc_f35', 'Marcos 5:21', 'Marcos', 5, 21, 'και διαπερασαντος του ιησου εν τω πλοιω παλιν εις το περαν συνηχθη οχλος πολυς επ αυτον και ην παρα την θαλασσαν'),
('grc_f35', 'Marcos 5:22', 'Marcos', 5, 22, 'και ιδου ερχεται εις των αρχισυναγωγων ονοματι ιαειρος και ιδων αυτον πιπτει προς τους ποδας αυτου'),
('grc_f35', 'Marcos 5:23', 'Marcos', 5, 23, 'και παρεκαλει αυτον πολλα λεγων οτι το θυγατριον μου εσχατως εχει ινα ελθων επιθης αυτη τας χειρας οπως σωθη και ζησεται'),
('grc_f35', 'Marcos 5:24', 'Marcos', 5, 24, 'και απηλθεν μετ αυτου και ηκολουθει αυτω οχλος πολυς και συνεθλιβον αυτον'),
('grc_f35', 'Marcos 5:25', 'Marcos', 5, 25, 'και γυνη τις ουσα εν ρυσει αιματος ετη δωδεκα'),
('grc_f35', 'Marcos 5:26', 'Marcos', 5, 26, 'και πολλα παθουσα υπο πολλων ιατρων και δαπανησασα τα παρ αυτης παντα και μηδεν ωφεληθεισα αλλα μαλλον εις το χειρον ελθουσα'),
('grc_f35', 'Marcos 5:27', 'Marcos', 5, 27, 'ακουσασα περι του ιησου ελθουσα εν τω οχλω οπισθεν ηψατο του ιματιου αυτου'),
('grc_f35', 'Marcos 5:28', 'Marcos', 5, 28, 'ελεγεν γαρ οτι καν των ιματιων αυτου αψωμαι σωθησομαι'),
('grc_f35', 'Marcos 5:29', 'Marcos', 5, 29, 'και ευθεως εξηρανθη η πηγη του αιματος αυτης και εγνω τω σωματι οτι ιαται απο της μαστιγος'),
('grc_f35', 'Marcos 5:30', 'Marcos', 5, 30, 'και ευθεως ο ιησους επιγνους εν εαυτω την εξ αυτου δυναμιν εξελθουσαν επιστραφεις εν τω οχλω ελεγεν τις μου ηψατο των ιματιων'),
('grc_f35', 'Marcos 5:31', 'Marcos', 5, 31, 'και ελεγον αυτω οι μαθηται αυτου βλεπεις τον οχλον συνθλιβοντα σε και λεγεις τις μου ηψατο'),
('grc_f35', 'Marcos 5:32', 'Marcos', 5, 32, 'και περιεβλεπετο ιδειν την τουτο ποιησασαν'),
('grc_f35', 'Marcos 5:33', 'Marcos', 5, 33, 'η δε γυνη φοβηθεισα και τρεμουσα ειδυια ο γεγονεν επ αυτη ηλθεν και προσεπεσεν αυτω και ειπεν αυτω πασαν την αληθειαν'),
('grc_f35', 'Marcos 5:34', 'Marcos', 5, 34, 'ο δε ειπεν αυτη θυγατερ η πιστις σου σεσωκεν σε υπαγε εις ειρηνην και ισθι υγιης απο της μαστιγος σου'),
('grc_f35', 'Marcos 5:35', 'Marcos', 5, 35, 'ετι αυτου λαλουντος ερχονται απο του αρχισυναγωγου λεγοντες οτι η θυγατηρ σου απεθανεν τι ετι σκυλλεις τον διδασκαλον'),
('grc_f35', 'Marcos 5:36', 'Marcos', 5, 36, 'ο δε ιησους ευθεως ακουσας τον λογον λαλουμενον λεγει τω αρχισυναγωγω μη φοβου μονον πιστευε'),
('grc_f35', 'Marcos 5:37', 'Marcos', 5, 37, 'και ουκ αφηκεν ουδενα αυτω συνακολουθησαι ει μη πετρον και ιακωβον και ιωαννην τον αδελφον ιακωβου'),
('grc_f35', 'Marcos 5:38', 'Marcos', 5, 38, 'και ερχεται εις τον οικον του αρχισυναγωγου και θεωρει θορυβον κλαιοντας και αλαλαζοντας πολλα'),
('grc_f35', 'Marcos 5:39', 'Marcos', 5, 39, 'και εισελθων λεγει αυτοις τι θορυβεισθε και κλαιετε το παιδιον ουκ απεθανεν αλλα καθευδει'),
('grc_f35', 'Marcos 5:40', 'Marcos', 5, 40, 'και κατεγελων αυτου ο δε εκβαλων παντας παραλαμβανει τον πατερα του παιδιου και την μητερα και τους μετ αυτου και εισπορευεται οπου ην το παιδιον ανακειμενον'),
('grc_f35', 'Marcos 5:41', 'Marcos', 5, 41, 'και κρατησας της χειρος του παιδιου λεγει αυτη ταλιθα κουμι ο εστιν μεθερμηνευομενον το κορασιον σοι λεγω εγειραι'),
('grc_f35', 'Marcos 5:42', 'Marcos', 5, 42, 'και ευθεως ανεστη το κορασιον και περιεπατει ην γαρ ετων δωδεκα και εξεστησαν εκστασει μεγαλη'),
('grc_f35', 'Marcos 5:43', 'Marcos', 5, 43, 'και διεστειλατο αυτοις πολλα ινα μηδεις γνω τουτο και ειπεν δοθηναι αυτη φαγειν'),
('grc_f35', 'Marcos 6:1', 'Marcos', 6, 1, 'και εξηλθεν εκειθεν και ηλθεν εις την πατριδα αυτου και ακολουθουσιν αυτω οι μαθηται αυτου'),
('grc_f35', 'Marcos 6:2', 'Marcos', 6, 2, 'και γενομενου σαββατου ηρξατο εν τη συναγωγη διδασκειν και πολλοι ακουοντες εξεπλησσοντο λεγοντες ποθεν τουτω ταυτα και τις η σοφια η δοθεισα αυτω και δυναμεις τοιαυται δια των χειρων αυτου γινονται'),
('grc_f35', 'Marcos 6:3', 'Marcos', 6, 3, 'ουχ ουτος εστιν ο τεκτων ο υιος μαριας αδελφος δε ιακωβου και ιωση και ιουδα και σιμωνος και ουκ εισιν αι αδελφαι αυτου ωδε προς ημας και εσκανδαλιζοντο εν αυτω'),
('grc_f35', 'Marcos 6:4', 'Marcos', 6, 4, 'ελεγεν δε αυτοις ο ιησους οτι ουκ εστιν προφητης ατιμος ει μη εν τη πατριδι αυτου και εν τοις συγγενεσιν και εν τη οικια αυτου'),
('grc_f35', 'Marcos 6:5', 'Marcos', 6, 5, 'και ουκ ηδυνατο εκει ουδεμιαν δυναμιν ποιησαι ει μη ολιγοις αρρωστοις επιθεις τας χειρας εθεραπευσεν'),
('grc_f35', 'Marcos 6:6', 'Marcos', 6, 6, 'και εθαυμαζεν δια την απιστιαν αυτων και περιηγεν τας κωμας κυκλω διδασκων'),
('grc_f35', 'Marcos 6:7', 'Marcos', 6, 7, 'και προσκαλειται τους δωδεκα και ηρξατο αυτους αποστελλειν δυο δυο και εδιδου αυτοις εξουσιαν των πνευματων των ακαθαρτων'),
('grc_f35', 'Marcos 6:8', 'Marcos', 6, 8, 'και παρηγγειλεν αυτοις ινα μηδεν αιρωσιν εις οδον ει μη ραβδον μονον μη πηραν μη αρτον μη εις την ζωνην χαλκον'),
('grc_f35', 'Marcos 6:9', 'Marcos', 6, 9, 'αλλ υποδεδεμενους σανδαλια και μη ενδυσησθε δυο χιτωνας'),
('grc_f35', 'Marcos 6:10', 'Marcos', 6, 10, 'και ελεγεν αυτοις οπου εαν εισελθητε εις οικιαν εκει μενετε εως αν εξελθητε εκειθεν'),
('grc_f35', 'Marcos 6:11', 'Marcos', 6, 11, 'και οσοι εαν μη δεξωνται υμας μηδε ακουσωσιν υμων εκπορευομενοι εκειθεν εκτιναξατε τον χουν τον υποκατω των ποδων υμων εις μαρτυριον αυτοις αμην λεγω υμιν ανεκτοτερον εσται σοδομοις η γομορροις εν ημερα κρισεως η τη πολει εκεινη'),
('grc_f35', 'Marcos 6:12', 'Marcos', 6, 12, 'και εξελθοντες εκηρυσσον ινα μετανοησωσιν'),
('grc_f35', 'Marcos 6:13', 'Marcos', 6, 13, 'και δαιμονια πολλα εξεβαλλον και ηλειφον ελαιω πολλους αρρωστους και εθεραπευον'),
('grc_f35', 'Marcos 6:14', 'Marcos', 6, 14, 'και ηκουσεν ο βασιλευς ηρωδης φανερον γαρ εγενετο το ονομα αυτου και ελεγεν οτι ιωαννης ο βαπτιζων εκ νεκρων ηγερθη και δια τουτο ενεργουσιν αι δυναμεις εν αυτω'),
('grc_f35', 'Marcos 6:15', 'Marcos', 6, 15, 'αλλοι ελεγον οτι ηλιας εστιν αλλοι δε ελεγον οτι προφητης εστιν ως εις των προφητων'),
('grc_f35', 'Marcos 6:16', 'Marcos', 6, 16, 'ακουσας δε ο ηρωδης ειπεν οτι ον εγω απεκεφαλισα ιωαννην ουτος εστιν αυτος ηγερθη εκ νεκρων'),
('grc_f35', 'Marcos 6:17', 'Marcos', 6, 17, 'αυτος γαρ ο ηρωδης αποστειλας εκρατησεν τον ιωαννην και εδησεν αυτον εν φυλακη δια ηρωδιαδα την γυναικα φιλιππου του αδελφου αυτου οτι αυτην εγαμησεν'),
('grc_f35', 'Marcos 6:18', 'Marcos', 6, 18, 'ελεγεν γαρ ο ιωαννης τω ηρωδη οτι ουκ εξεστιν σοι εχειν την γυναικα του αδελφου σου'),
('grc_f35', 'Marcos 6:19', 'Marcos', 6, 19, 'η δε ηρωδιας ενειχεν αυτω και ηθελεν αυτον αποκτειναι και ουκ ηδυνατο'),
('grc_f35', 'Marcos 6:20', 'Marcos', 6, 20, 'ο γαρ ηρωδης εφοβειτο τον ιωαννην ειδως αυτον ανδρα δικαιον και αγιον και συνετηρει αυτον και ακουων αυτου πολλα εποιει και ηδεως αυτου ηκουεν'),
('grc_f35', 'Marcos 6:21', 'Marcos', 6, 21, 'και γενομενης ημερας ευκαιρου οτε ηρωδης τοις γενεσιοις αυτου δειπνον εποιει τοις μεγιστασιν αυτου και τοις χιλιαρχοις και τοις πρωτοις της γαλιλαιας'),
('grc_f35', 'Marcos 6:22', 'Marcos', 6, 22, 'και εισελθουσης της θυγατρος αυτης της ηρωδιαδος και ορχησαμενης και αρεσασης τω ηρωδη και τοις συνανακειμενοις ειπεν ο βασιλευς τω κορασιω αιτησον με ο εαν θελης και δωσω σοι'),
('grc_f35', 'Marcos 6:23', 'Marcos', 6, 23, 'και ωμοσεν αυτη οτι ο εαν με αιτησης δωσω σοι εως ημισους της βασιλειας μου'),
('grc_f35', 'Marcos 6:24', 'Marcos', 6, 24, 'η δε εξελθουσα ειπεν τη μητρι αυτης τι αιτησομαι η δε ειπεν την κεφαλην ιωαννου του βαπτιστου'),
('grc_f35', 'Marcos 6:25', 'Marcos', 6, 25, 'και εισελθουσα ευθεως μετα σπουδης προς τον βασιλεα ητησατο λεγουσα θελω ινα μοι δως εξ αυτης επι πινακι την κεφαλην ιωαννου του βαπτιστου'),
('grc_f35', 'Marcos 6:26', 'Marcos', 6, 26, 'και περιλυπος γενομενος ο βασιλευς δια τους ορκους και τους συνανακειμενους ουκ ηθελησεν αυτην αθετησαι'),
('grc_f35', 'Marcos 6:27', 'Marcos', 6, 27, 'και ευθεως αποστειλας ο βασιλευς σπεκουλατωρα επεταξεν ενεχθηναι την κεφαλην αυτου ο δε απελθων απεκεφαλισεν αυτον εν τη φυλακη'),
('grc_f35', 'Marcos 6:28', 'Marcos', 6, 28, 'και ηνεγκεν την κεφαλην αυτου επι πινακι και εδωκεν αυτην τω κορασιω και το κορασιον εδωκεν αυτην τη μητρι αυτης'),
('grc_f35', 'Marcos 6:29', 'Marcos', 6, 29, 'και ακουσαντες οι μαθηται αυτου ηλθον και ηραν το πτωμα αυτου και εθηκαν αυτο εν μνημειω'),
('grc_f35', 'Marcos 6:30', 'Marcos', 6, 30, 'και συναγονται οι αποστολοι προς τον ιησουν και απηγγειλαν αυτω παντα και οσα εποιησαν και οσα εδιδαξαν'),
('grc_f35', 'Marcos 6:31', 'Marcos', 6, 31, 'και ειπεν αυτοις δευτε υμεις αυτοι κατ ιδιαν εις ερημον τοπον και αναπαυεσθε ολιγον ησαν γαρ οι ερχομενοι και οι υπαγοντες πολλοι και ουδε φαγειν ευκαιρουν'),
('grc_f35', 'Marcos 6:32', 'Marcos', 6, 32, 'και απηλθον εις ερημον τοπον τω πλοιω κατ ιδιαν'),
('grc_f35', 'Marcos 6:33', 'Marcos', 6, 33, 'και ειδον αυτους υπαγοντας και επεγνωσαν αυτους πολλοι και πεζη απο πασων των πολεων συνεδραμον εκει και προηλθον αυτους και συνηλθον προς αυτον'),
('grc_f35', 'Marcos 6:34', 'Marcos', 6, 34, 'και εξελθων ειδεν ο ιησους πολυν οχλον και εσπλαγχνισθη επ αυτοις οτι ησαν ως προβατα μη εχοντα ποιμενα και ηρξατο διδασκειν αυτους πολλα'),
('grc_f35', 'Marcos 6:35', 'Marcos', 6, 35, 'και ηδη ωρας πολλης γενομενης προσελθοντες αυτω οι μαθηται αυτου λεγουσιν οτι ερημος εστιν ο τοπος και ηδη ωρα πολλη'),
('grc_f35', 'Marcos 6:36', 'Marcos', 6, 36, 'απολυσον αυτους ινα απελθοντες εις τους κυκλω αγρους και κωμας αγορασωσιν εαυτοις αρτους τι γαρ φαγωσιν ουκ εχουσιν'),
('grc_f35', 'Marcos 6:37', 'Marcos', 6, 37, 'ο δε αποκριθεις ειπεν αυτοις δοτε αυτοις υμεις φαγειν και λεγουσιν αυτω απελθοντες αγορασωμεν δηναριων διακοσιων αρτους και δωμεν αυτοις φαγειν'),
('grc_f35', 'Marcos 6:38', 'Marcos', 6, 38, 'ο δε λεγει αυτοις ποσους αρτους εχετε υπαγετε και ιδετε και γνοντες λεγουσιν πεντε και δυο ιχθυας'),
('grc_f35', 'Marcos 6:39', 'Marcos', 6, 39, 'και επεταξεν αυτοις ανακλιναι παντας συμποσια συμποσια επι τω χλωρω χορτω'),
('grc_f35', 'Marcos 6:40', 'Marcos', 6, 40, 'και ανεπεσον πρασιαι πρασιαι ανα εκατον και ανα πεντηκοντα'),
('grc_f35', 'Marcos 6:41', 'Marcos', 6, 41, 'και λαβων τους πεντε αρτους και τους δυο ιχθυας αναβλεψας εις τον ουρανον ευλογησεν και κατεκλασεν τους αρτους και εδιδου τοις μαθηταις αυτου ινα παραθωσιν αυτοις και τους δυο ιχθυας εμερισεν πασιν'),
('grc_f35', 'Marcos 6:42', 'Marcos', 6, 42, 'και εφαγον παντες και εχορτασθησαν'),
('grc_f35', 'Marcos 6:43', 'Marcos', 6, 43, 'και ηραν κλασματων δωδεκα κοφινους πληρεις και απο των ιχθυων'),
('grc_f35', 'Marcos 6:44', 'Marcos', 6, 44, 'και ησαν οι φαγοντες τους αρτους πεντακισχιλιοι ανδρες'),
('grc_f35', 'Marcos 6:45', 'Marcos', 6, 45, 'και ευθεως ηναγκασεν τους μαθητας αυτου εμβηναι εις το πλοιον και προαγειν εις το περαν προς βηθσαιδαν εως αυτος απολυσει τον οχλον'),
('grc_f35', 'Marcos 6:46', 'Marcos', 6, 46, 'και αποταξαμενος αυτοις απηλθεν εις το ορος προσευξασθαι'),
('grc_f35', 'Marcos 6:47', 'Marcos', 6, 47, 'και οψιας γενομενης ην το πλοιον εν μεσω της θαλασσης και αυτος μονος επι της γης'),
('grc_f35', 'Marcos 6:48', 'Marcos', 6, 48, 'και ειδεν αυτους βασανιζομενους εν τω ελαυνειν ην γαρ ο ανεμος εναντιος αυτοις και περι τεταρτην φυλακην της νυκτος ερχεται προς αυτους περιπατων επι της θαλασσης και ηθελεν παρελθειν αυτους'),
('grc_f35', 'Marcos 6:49', 'Marcos', 6, 49, 'οι δε ιδοντες αυτον περιπατουντα επι της θαλασσης εδοξαν φαντασμα ειναι και ανεκραξαν'),
('grc_f35', 'Marcos 6:50', 'Marcos', 6, 50, 'παντες γαρ αυτον ειδον και εταραχθησαν και ευθεως ελαλησεν μετ αυτων και λεγει αυτοις θαρσειτε εγω ειμι μη φοβεισθε'),
('grc_f35', 'Marcos 6:51', 'Marcos', 6, 51, 'και ανεβη προς αυτους εις το πλοιον και εκοπασεν ο ανεμος και λιαν εκ περισσου εν εαυτοις εξισταντο και εθαυμαζον'),
('grc_f35', 'Marcos 6:52', 'Marcos', 6, 52, 'ου γαρ συνηκαν επι τοις αρτοις ην γαρ αυτων η καρδια πεπωρωμενη'),
('grc_f35', 'Marcos 6:53', 'Marcos', 6, 53, 'και διαπερασαντες ηλθον επι την γην γενησαρετ και προσωρμισθησαν'),
('grc_f35', 'Marcos 6:54', 'Marcos', 6, 54, 'και εξελθοντων αυτων εκ του πλοιου ευθεως επιγνοντες αυτον'),
('grc_f35', 'Marcos 6:55', 'Marcos', 6, 55, 'περιδραμοντες ολην την περιχωρον εκεινην ηρξαντο επι τοις κραββατοις τους κακως εχοντας περιφερειν οπου ηκουον οτι εκει εστιν'),
('grc_f35', 'Marcos 6:56', 'Marcos', 6, 56, 'και οπου αν εισεπορευετο εις κωμας η πολεις η αγρους εν ταις αγοραις ετιθουν τους ασθενουντας και παρεκαλουν αυτον ινα καν του κρασπεδου του ιματιου αυτου αψωνται και οσοι αν ηπτοντο αυτου εσωζοντο'),
('grc_f35', 'Marcos 7:1', 'Marcos', 7, 1, 'και συναγονται προς αυτον οι φαρισαιοι και τινες των γραμματεων ελθοντες απο ιεροσολυμων'),
('grc_f35', 'Marcos 7:2', 'Marcos', 7, 2, 'και ιδοντες τινας των μαθητων αυτου κοιναις χερσιν τουτ εστιν ανιπτοις εσθιοντας αρτους εμεμψαντο'),
('grc_f35', 'Marcos 7:3', 'Marcos', 7, 3, 'οι γαρ φαρισαιοι και παντες οι ιουδαιοι εαν μη πυγμη νιψωνται τας χειρας ουκ εσθιουσιν κρατουντες την παραδοσιν των πρεσβυτερων'),
('grc_f35', 'Marcos 7:4', 'Marcos', 7, 4, 'και απο αγορας εαν μη βαπτισωνται ουκ εσθιουσιν και αλλα πολλα εστιν α παρελαβον κρατειν βαπτισμους ποτηριων και ξεστων και χαλκειων και κλινων'),
('grc_f35', 'Marcos 7:5', 'Marcos', 7, 5, 'επειτα επερωτωσιν αυτον οι φαρισαιοι και οι γραμματεις δια τι οι μαθηται σου ου περιπατουσιν κατα την παραδοσιν των πρεσβυτερων αλλα ανιπτοις χερσιν εσθιουσιν τον αρτον'),
('grc_f35', 'Marcos 7:6', 'Marcos', 7, 6, 'ο δε αποκριθεις ειπεν αυτοις οτι καλως προεφητευσεν ησαιας περι υμων των υποκριτων ως γεγραπται ουτος ο λαος τοις χειλεσιν με τιμα η δε καρδια αυτων πορρω απεχει απ εμου'),
('grc_f35', 'Marcos 7:7', 'Marcos', 7, 7, 'ματην δε σεβονται με διδασκοντες διδασκαλιας ενταλματα ανθρωπων'),
('grc_f35', 'Marcos 7:8', 'Marcos', 7, 8, 'αφεντες γαρ την εντολην του θεου κρατειτε την παραδοσιν των ανθρωπων βαπτισμους ξεστων και ποτηριων και αλλα παρομοια τοιαυτα πολλα ποιειτε'),
('grc_f35', 'Marcos 7:9', 'Marcos', 7, 9, 'και ελεγεν αυτοις καλως αθετειτε την εντολην του θεου ινα την παραδοσιν υμων τηρησητε'),
('grc_f35', 'Marcos 7:10', 'Marcos', 7, 10, 'μωσης γαρ ειπεν τιμα τον πατερα σου και την μητερα σου και ο κακολογων πατερα η μητερα θανατω τελευτατω'),
('grc_f35', 'Marcos 7:11', 'Marcos', 7, 11, 'υμεις δε λεγετε εαν ειπη ανθρωπος τω πατρι η τη μητρι κορβαν ο εστιν δωρον ο εαν εξ εμου ωφεληθης'),
('grc_f35', 'Marcos 7:12', 'Marcos', 7, 12, 'και ουκετι αφιετε αυτον ουδεν ποιησαι τω πατρι αυτου η τη μητρι αυτου'),
('grc_f35', 'Marcos 7:13', 'Marcos', 7, 13, 'ακυρουντες τον λογον του θεου τη παραδοσει υμων η παρεδωκατε και παρομοια τοιαυτα πολλα ποιειτε'),
('grc_f35', 'Marcos 7:14', 'Marcos', 7, 14, 'και προσκαλεσαμενος παντα τον οχλον ελεγεν αυτοις ακουετε μου παντες και συνιετε'),
('grc_f35', 'Marcos 7:15', 'Marcos', 7, 15, 'ουδεν εστιν εξωθεν του ανθρωπου εισπορευομενον εις αυτον ο δυναται αυτον κοινωσαι αλλα τα εκπορευομενα απ αυτου εκεινα εστιν τα κοινουντα τον ανθρωπον'),
('grc_f35', 'Marcos 7:16', 'Marcos', 7, 16, 'ει τις εχει ωτα ακουειν ακουετω'),
('grc_f35', 'Marcos 7:17', 'Marcos', 7, 17, 'και οτε εισηλθεν εις οικον απο του οχλου επηρωτων αυτον οι μαθηται αυτου περι της παραβολης'),
('grc_f35', 'Marcos 7:18', 'Marcos', 7, 18, 'και λεγει αυτοις ουτως και υμεις ασυνετοι εστε ου νοειτε οτι παν το εξωθεν εισπορευομενον εις τον ανθρωπον ου δυναται αυτον κοινωσαι'),
('grc_f35', 'Marcos 7:19', 'Marcos', 7, 19, 'οτι ουκ εισπορευεται αυτου εις την καρδιαν αλλ εις την κοιλιαν και εις τον αφεδρωνα εκπορευεται καθαριζον παντα τα βρωματα'),
('grc_f35', 'Marcos 7:20', 'Marcos', 7, 20, 'ελεγεν δε οτι το εκ του ανθρωπου εκπορευομενον εκεινο κοινοι τον ανθρωπον'),
('grc_f35', 'Marcos 7:21', 'Marcos', 7, 21, 'εσωθεν γαρ εκ της καρδιας των ανθρωπων οι διαλογισμοι οι κακοι εκπορευονται μοιχειαι πορνειαι φονοι'),
('grc_f35', 'Marcos 7:22', 'Marcos', 7, 22, 'κλοπαι πλεονεξιαι πονηριαι δολος ασελγεια οφθαλμος πονηρος βλασφημια υπερηφανια αφροσυνη'),
('grc_f35', 'Marcos 7:23', 'Marcos', 7, 23, 'παντα ταυτα τα πονηρα εσωθεν εκπορευεται και κοινοι τον ανθρωπον'),
('grc_f35', 'Marcos 7:24', 'Marcos', 7, 24, 'και εκειθεν αναστας απηλθεν εις τα μεθορια τυρου και σιδωνος και εισελθων εις οικιαν ουδενα ηθελεν γνωναι και ουκ ηδυνηθη λαθειν'),
('grc_f35', 'Marcos 7:25', 'Marcos', 7, 25, 'ακουσασα γαρ γυνη περι αυτου ης ειχεν το θυγατριον αυτης πνευμα ακαθαρτον ελθουσα προσεπεσεν προς τους ποδας αυτου'),
('grc_f35', 'Marcos 7:26', 'Marcos', 7, 26, 'ην δε η γυνη ελληνις συραφοινικισσα τω γενει και ηρωτα αυτον ινα το δαιμονιον εκβαλη εκ της θυγατρος αυτης'),
('grc_f35', 'Marcos 7:27', 'Marcos', 7, 27, 'ο δε ιησους ειπεν αυτη αφες πρωτον χορτασθηναι τα τεκνα ου γαρ καλον εστιν λαβειν τον αρτον των τεκνων και βαλειν τοις κυναριοις'),
('grc_f35', 'Marcos 7:28', 'Marcos', 7, 28, 'η δε απεκριθη και λεγει αυτω ναι κυριε και γαρ τα κυναρια υποκατω της τραπεζης εσθιει απο των ψιχιων των παιδιων'),
('grc_f35', 'Marcos 7:29', 'Marcos', 7, 29, 'και ειπεν αυτη δια τουτον τον λογον υπαγε εξεληλυθεν το δαιμονιον εκ της θυγατρος σου'),
('grc_f35', 'Marcos 7:30', 'Marcos', 7, 30, 'και απελθουσα εις τον οικον αυτης ευρεν το δαιμονιον εξεληλυθος και την θυγατερα βεβλημενην επι της κλινης'),
('grc_f35', 'Marcos 7:31', 'Marcos', 7, 31, 'και παλιν εξελθων ο ιησους εκ των οριων τυρου και σιδωνος ηλθεν προς την θαλασσαν της γαλιλαιας ανα μεσον των οριων δεκαπολεως'),
('grc_f35', 'Marcos 7:32', 'Marcos', 7, 32, 'και φερουσιν αυτω κωφον μογγιλαλον και παρακαλουσιν αυτον ινα επιθη αυτω την χειρα'),
('grc_f35', 'Marcos 7:33', 'Marcos', 7, 33, 'και απολαβομενος αυτον απο του οχλου κατ ιδιαν εβαλεν τους δακτυλους αυτου εις τα ωτα αυτου και πτυσας ηψατο της γλωσσης αυτου'),
('grc_f35', 'Marcos 7:34', 'Marcos', 7, 34, 'και αναβλεψας εις τον ουρανον εστεναξεν και λεγει αυτω εφφαθα ο εστιν διανοιχθητι'),
('grc_f35', 'Marcos 7:35', 'Marcos', 7, 35, 'και ευθεως διηνοιχθησαν αυτου αι ακοαι και ελυθη ο δεσμος της γλωσσης αυτου και ελαλει ορθως'),
('grc_f35', 'Marcos 7:36', 'Marcos', 7, 36, 'και διεστειλατο αυτοις ινα μηδενι ειπωσιν οσον δε αυτος αυτοις διεστελλετο μαλλον περισσοτερον εκηρυσσον'),
('grc_f35', 'Marcos 7:37', 'Marcos', 7, 37, 'και υπερπερισσως εξεπλησσοντο λεγοντες καλως παντα πεποιηκεν και τους κωφους ποιει ακουειν και τους αλαλους λαλειν'),
('grc_f35', 'Marcos 8:1', 'Marcos', 8, 1, 'εν εκειναις ταις ημεραις παμπολλου οχλου οντος και μη εχοντων τι φαγωσιν προσκαλεσαμενος ο ιησους τους μαθητας αυτου λεγει αυτοις'),
('grc_f35', 'Marcos 8:2', 'Marcos', 8, 2, 'σπλαγχνιζομαι επι τον οχλον οτι ηδη ημερας τρεις προσμενουσιν μοι και ουκ εχουσιν τι φαγωσιν'),
('grc_f35', 'Marcos 8:3', 'Marcos', 8, 3, 'και εαν απολυσω αυτους νηστις εις οικον αυτων εκλυθησονται εν τη οδω τινες γαρ αυτων μακροθεν ηκουσιν'),
('grc_f35', 'Marcos 8:4', 'Marcos', 8, 4, 'και απεκριθησαν αυτω οι μαθηται αυτου ποθεν τουτους δυνησεται τις ωδε χορτασαι αρτων επ ερημιας'),
('grc_f35', 'Marcos 8:5', 'Marcos', 8, 5, 'και επηρωτα αυτους ποσους εχετε αρτους οι δε ειπον επτα'),
('grc_f35', 'Marcos 8:6', 'Marcos', 8, 6, 'και παρηγγειλεν τω οχλω αναπεσειν επι της γης και λαβων τους επτα αρτους και ευχαριστησας εκλασεν και εδιδου τοις μαθηταις αυτου ινα παραθωσιν και παρεθηκαν τω οχλω'),
('grc_f35', 'Marcos 8:7', 'Marcos', 8, 7, 'και ειχον ιχθυδια ολιγα και ευλογησας ειπεν παραθειναι και αυτα'),
('grc_f35', 'Marcos 8:8', 'Marcos', 8, 8, 'εφαγον δε και εχορτασθησαν και ηραν περισσευματα κλασματων επτα σπυριδας'),
('grc_f35', 'Marcos 8:9', 'Marcos', 8, 9, 'ησαν δε οι φαγοντες ως τετρακισχιλιοι και απελυσεν αυτους'),
('grc_f35', 'Marcos 8:10', 'Marcos', 8, 10, 'και ευθεως εμβας εις το πλοιον μετα των μαθητων αυτου ηλθεν εις τα μερη δαλμανουθα'),
('grc_f35', 'Marcos 8:11', 'Marcos', 8, 11, 'και εξηλθον οι φαρισαιοι και ηρξαντο συζητειν αυτω ζητουντες παρ αυτου σημειον απο του ουρανου πειραζοντες αυτον'),
('grc_f35', 'Marcos 8:12', 'Marcos', 8, 12, 'και αναστεναξας τω πνευματι αυτου λεγει τι η γενεα αυτη σημειον επιζητει αμην λεγω υμιν ει δοθησεται τη γενεα ταυτη σημειον'),
('grc_f35', 'Marcos 8:13', 'Marcos', 8, 13, 'και αφεις αυτους εμβας παλιν εις πλοιον απηλθεν εις το περαν'),
('grc_f35', 'Marcos 8:14', 'Marcos', 8, 14, 'και επελαθοντο οι μαθηται αυτου λαβειν αρτους και ει μη ενα αρτον ουκ ειχον μεθ εαυτων εν τω πλοιω'),
('grc_f35', 'Marcos 8:15', 'Marcos', 8, 15, 'και διεστελλετο αυτοις λεγων ορατε βλεπετε απο της ζυμης των φαρισαιων και της ζυμης ηρωδου'),
('grc_f35', 'Marcos 8:16', 'Marcos', 8, 16, 'και διελογιζοντο προς αλληλους λεγοντες οτι αρτους ουκ εχομεν'),
('grc_f35', 'Marcos 8:17', 'Marcos', 8, 17, 'και γνους ο ιησους λεγει αυτοις τι διαλογιζεσθε οτι αρτους ουκ εχετε ουπω νοειτε ουδε συνιετε ετι πεπωρωμενην εχετε την καρδιαν υμων'),
('grc_f35', 'Marcos 8:18', 'Marcos', 8, 18, 'οφθαλμους εχοντες ου βλεπετε και ωτα εχοντες ουκ ακουετε και ου μνημονευετε'),
('grc_f35', 'Marcos 8:19', 'Marcos', 8, 19, 'οτε τους πεντε αρτους εκλασα εις τους πεντακισχιλιους ποσους κοφινους πληρεις κλασματων ηρατε λεγουσιν αυτω δωδεκα'),
('grc_f35', 'Marcos 8:20', 'Marcos', 8, 20, 'οτε δε τους επτα εις τους τετρακισχιλιους ποσων σπυριδων πληρωματα κλασματων ηρατε οι δε ειπον επτα'),
('grc_f35', 'Marcos 8:21', 'Marcos', 8, 21, 'και λεγει αυτοις πως ουπω συνιετε'),
('grc_f35', 'Marcos 8:22', 'Marcos', 8, 22, 'και ερχεται εις βηθσαιδαν και φερουσιν αυτω τυφλον και παρακαλουσιν αυτον ινα αυτου αψηται'),
('grc_f35', 'Marcos 8:23', 'Marcos', 8, 23, 'και επιλαβομενος της χειρος του τυφλου εξηγαγεν αυτον εξω της κωμης και πτυσας εις τα ομματα αυτου επιθεις τας χειρας αυτω επηρωτα αυτον ει τι βλεπει'),
('grc_f35', 'Marcos 8:24', 'Marcos', 8, 24, 'και αναβλεψας ελεγεν βλεπω τους ανθρωπους οτι ως δενδρα ορω περιπατουντας'),
('grc_f35', 'Marcos 8:25', 'Marcos', 8, 25, 'ειτα παλιν επεθηκεν τας χειρας επι τους οφθαλμους αυτου και εποιησεν αυτον αναβλεψαι και αποκατεσταθη και ενεβλεψεν τηλαυγως απαντας'),
('grc_f35', 'Marcos 8:26', 'Marcos', 8, 26, 'και απεστειλεν αυτον εις τον οικον αυτου λεγων μηδε εις την κωμην εισελθης μηδε ειπης τινι εν τη κωμη'),
('grc_f35', 'Marcos 8:27', 'Marcos', 8, 27, 'και εξηλθεν ο ιησους και οι μαθηται αυτου εις τας κωμας καισαρειας της φιλιππου και εν τη οδω επηρωτα τους μαθητας αυτου λεγων αυτοις τινα με λεγουσιν οι ανθρωποι ειναι'),
('grc_f35', 'Marcos 8:28', 'Marcos', 8, 28, 'οι δε απεκριθησαν ιωαννην τον βαπτιστην και αλλοι ηλιαν αλλοι δε ενα των προφητων'),
('grc_f35', 'Marcos 8:29', 'Marcos', 8, 29, 'και αυτος λεγει αυτοις υμεις δε τινα με λεγετε ειναι αποκριθεις δε ο πετρος λεγει αυτω συ ει ο χριστος'),
('grc_f35', 'Marcos 8:30', 'Marcos', 8, 30, 'και επετιμησεν αυτοις ινα μηδενι λεγωσιν περι αυτου'),
('grc_f35', 'Marcos 8:31', 'Marcos', 8, 31, 'και ηρξατο διδασκειν αυτους οτι δει τον υιον του ανθρωπου πολλα παθειν και αποδοκιμασθηναι απο των πρεσβυτερων και των αρχιερεων και των γραμματεων και αποκτανθηναι και μετα τρεις ημερας αναστηναι'),
('grc_f35', 'Marcos 8:32', 'Marcos', 8, 32, 'και παρρησια τον λογον ελαλει και προσλαβομενος αυτον ο πετρος ηρξατο επιτιμαν αυτω'),
('grc_f35', 'Marcos 8:33', 'Marcos', 8, 33, 'ο δε επιστραφεις και ιδων τους μαθητας αυτου επετιμησεν τω πετρω λεγων υπαγε οπισω μου σατανα οτι ου φρονεις τα του θεου αλλα τα των ανθρωπων'),
('grc_f35', 'Marcos 8:34', 'Marcos', 8, 34, 'και προσκαλεσαμενος τον οχλον συν τοις μαθηταις αυτου ειπεν αυτοις οστις θελει οπισω μου ακολουθειν απαρνησασθω εαυτον και αρατω τον σταυρον αυτου και ακολουθειτω μοι'),
('grc_f35', 'Marcos 8:35', 'Marcos', 8, 35, 'ος γαρ αν θελη την ψυχην αυτου σωσαι απολεσει αυτην ος δ αν απολεση την ψυχην αυτου ενεκεν εμου και του ευαγγελιου ουτος σωσει αυτην'),
('grc_f35', 'Marcos 8:36', 'Marcos', 8, 36, 'τι γαρ ωφελησει ανθρωπον εαν κερδηση τον κοσμον ολον και ζημιωθη την ψυχην αυτου'),
('grc_f35', 'Marcos 8:37', 'Marcos', 8, 37, 'η τι δωσει ανθρωπος ανταλλαγμα της ψυχης αυτου'),
('grc_f35', 'Marcos 8:38', 'Marcos', 8, 38, 'ος γαρ εαν επαισχυνθη με και τους εμους λογους εν τη γενεα ταυτη τη μοιχαλιδι και αμαρτωλω και ο υιος του ανθρωπου επαισχυνθησεται αυτον οταν ελθη εν τη δοξη του πατρος αυτου μετα των αγγελων των αγιων'),
('grc_f35', 'Marcos 9:1', 'Marcos', 9, 1, 'και ελεγεν αυτοις αμην λεγω υμιν οτι εισιν τινες των ωδε εστηκοτων οιτινες ου μη γευσωνται θανατου εως αν ιδωσιν την βασιλειαν του θεου εληλυθυιαν εν δυναμει'),
('grc_f35', 'Marcos 9:2', 'Marcos', 9, 2, 'και μεθ ημερας εξ παραλαμβανει ο ιησους τον πετρον και τον ιακωβον και τον ιωαννην και αναφερει αυτους εις ορος υψηλον κατ ιδιαν μονους και μετεμορφωθη εμπροσθεν αυτων'),
('grc_f35', 'Marcos 9:3', 'Marcos', 9, 3, 'και τα ιματια αυτου εγενετο στιλβοντα λευκα λιαν ως χιων οια κναφευς επι της γης ου δυναται λευκαναι'),
('grc_f35', 'Marcos 9:4', 'Marcos', 9, 4, 'και ωφθη αυτοις ηλιας συν μωυση και ησαν συλλαλουντες τω ιησου'),
('grc_f35', 'Marcos 9:5', 'Marcos', 9, 5, 'και αποκριθεις ο πετρος λεγει τω ιησου ραββι καλον εστιν ημας ωδε ειναι και ποιησωμεν σκηνας τρεις σοι μιαν και μωσει μιαν και ηλια μιαν'),
('grc_f35', 'Marcos 9:6', 'Marcos', 9, 6, 'ου γαρ ηδει τι λαλησει ησαν γαρ εκφοβοι'),
('grc_f35', 'Marcos 9:7', 'Marcos', 9, 7, 'και εγενετο νεφελη επισκιαζουσα αυτοις και ηλθεν φωνη εκ της νεφελης ουτος εστιν ο υιος μου ο αγαπητος αυτου ακουετε'),
('grc_f35', 'Marcos 9:8', 'Marcos', 9, 8, 'και εξαπινα περιβλεψαμενοι ουκετι ουδενα ειδον αλλα τον ιησουν μονον μεθ εαυτων'),
('grc_f35', 'Marcos 9:9', 'Marcos', 9, 9, 'καταβαινοντων δε αυτων απο του ορους διεστειλατο αυτοις ινα μηδενι διηγησωνται α ειδον ει μη οταν ο υιος του ανθρωπου εκ νεκρων αναστη'),
('grc_f35', 'Marcos 9:10', 'Marcos', 9, 10, 'και τον λογον εκρατησαν προς εαυτους συζητουντες τι εστιν το εκ νεκρων αναστηναι'),
('grc_f35', 'Marcos 9:11', 'Marcos', 9, 11, 'και επηρωτων αυτον λεγοντες οτι λεγουσιν οι γραμματεις οτι ηλιαν δει ελθειν πρωτον'),
('grc_f35', 'Marcos 9:12', 'Marcos', 9, 12, 'ο δε αποκριθεις ειπεν αυτοις ηλιας μεν ελθων πρωτον αποκαθιστα παντα και πως γεγραπται επι τον υιον του ανθρωπου ινα πολλα παθη και εξουδενωθη'),
('grc_f35', 'Marcos 9:13', 'Marcos', 9, 13, 'αλλα λεγω υμιν οτι και ηλιας εληλυθεν και εποιησαν αυτω οσα ηθελησαν καθως γεγραπται επ αυτον'),
('grc_f35', 'Marcos 9:14', 'Marcos', 9, 14, 'και ελθων προς τους μαθητας ειδεν οχλον πολυν περι αυτους και γραμματεις συζητουντας αυτοις'),
('grc_f35', 'Marcos 9:15', 'Marcos', 9, 15, 'και ευθεως πας ο οχλος ιδων αυτον εξεθαμβηθη και προστρεχοντες ησπαζοντο αυτον'),
('grc_f35', 'Marcos 9:16', 'Marcos', 9, 16, 'και επηρωτησεν τους γραμματεις τι συζητειτε προς αυτους'),
('grc_f35', 'Marcos 9:17', 'Marcos', 9, 17, 'και αποκριθεις εις εκ του οχλου ειπεν διδασκαλε ηνεγκα τον υιον μου προς σε εχοντα πνευμα αλαλον'),
('grc_f35', 'Marcos 9:18', 'Marcos', 9, 18, 'και οπου αν αυτον καταλαβη ρησσει αυτον και αφριζει και τριζει τους οδοντας αυτου και ξηραινεται και ειπον τοις μαθηταις σου ινα αυτο εκβαλωσιν και ουκ ισχυσαν'),
('grc_f35', 'Marcos 9:19', 'Marcos', 9, 19, 'ο δε αποκριθεις αυτω λεγει ω γενεα απιστος εως ποτε προς υμας εσομαι εως ποτε ανεξομαι υμων φερετε αυτον προς με'),
('grc_f35', 'Marcos 9:20', 'Marcos', 9, 20, 'και ηνεγκαν αυτον προς αυτον και ιδον αυτον ευθεως το πνευμα εσπαραξεν αυτον και πεσων επι της γης εκυλιετο αφριζων'),
('grc_f35', 'Marcos 9:21', 'Marcos', 9, 21, 'και επηρωτησεν τον πατερα αυτου ποσος χρονος εστιν ως τουτο γεγονεν αυτω ο δε ειπεν παιδιοθεν'),
('grc_f35', 'Marcos 9:22', 'Marcos', 9, 22, 'και πολλακις αυτον και εις πυρ εβαλεν και εις υδατα ινα απολεση αυτον αλλ ει τι δυνασαι βοηθησον ημιν σπλαγχνισθεις εφ ημας'),
('grc_f35', 'Marcos 9:23', 'Marcos', 9, 23, 'ο δε ιησους ειπεν αυτω το ει δυνασαι πιστευσαι παντα δυνατα τω πιστευοντι'),
('grc_f35', 'Marcos 9:24', 'Marcos', 9, 24, 'και ευθεως κραξας ο πατηρ του παιδιου μετα δακρυων ελεγεν πιστευω κυριε βοηθει μου τη απιστια'),
('grc_f35', 'Marcos 9:25', 'Marcos', 9, 25, 'ιδων δε ο ιησους οτι επισυντρεχει ο οχλος επετιμησεν τω πνευματι τω ακαθαρτω λεγων αυτω το πνευμα το αλαλον και κωφον εγω σοι επιτασσω εξελθε εξ αυτου και μηκετι εισελθης εις αυτον'),
('grc_f35', 'Marcos 9:26', 'Marcos', 9, 26, 'και κραξαν και πολλα σπαραξαν αυτον εξηλθεν και εγενετο ωσει νεκρος ωστε πολλους λεγειν οτι απεθανεν'),
('grc_f35', 'Marcos 9:27', 'Marcos', 9, 27, 'ο δε ιησους κρατησας αυτον της χειρος ηγειρεν αυτον και ανεστη'),
('grc_f35', 'Marcos 9:28', 'Marcos', 9, 28, 'και εισελθοντα αυτον εις οικον οι μαθηται αυτου επηρωτων αυτον κατ ιδιαν οτι ημεις ουκ ηδυνηθημεν εκβαλειν αυτο'),
('grc_f35', 'Marcos 9:29', 'Marcos', 9, 29, 'και ειπεν αυτοις τουτο το γενος εν ουδενι δυναται εξελθειν ει μη εν προσευχη και νηστεια'),
('grc_f35', 'Marcos 9:30', 'Marcos', 9, 30, 'και εκειθεν εξελθοντες παρεπορευοντο δια της γαλιλαιας και ουκ ηθελεν ινα τις γνω'),
('grc_f35', 'Marcos 9:31', 'Marcos', 9, 31, 'εδιδασκεν γαρ τους μαθητας αυτου και ελεγεν αυτοις οτι ο υιος του ανθρωπου παραδιδοται εις χειρας ανθρωπων και αποκτενουσιν αυτον και αποκτανθεις τη τριτη ημερα αναστησεται'),
('grc_f35', 'Marcos 9:32', 'Marcos', 9, 32, 'οι δε ηγνοουν το ρημα και εφοβουντο αυτον επερωτησαι'),
('grc_f35', 'Marcos 9:33', 'Marcos', 9, 33, 'και ηλθεν εις καπερναουμ και εν τη οικια γενομενος επηρωτα αυτους τι εν τη οδω προς εαυτους διελογιζεσθε'),
('grc_f35', 'Marcos 9:34', 'Marcos', 9, 34, 'οι δε εσιωπων προς αλληλους γαρ διελεχθησαν εν τη οδω τις μειζων'),
('grc_f35', 'Marcos 9:35', 'Marcos', 9, 35, 'και καθισας εφωνησεν τους δωδεκα και λεγει αυτοις ει τις θελει πρωτος ειναι εσται παντων εσχατος και παντων διακονος'),
('grc_f35', 'Marcos 9:36', 'Marcos', 9, 36, 'και λαβων παιδιον εστησεν αυτο εν μεσω αυτων και εναγκαλισαμενος αυτο ειπεν αυτοις'),
('grc_f35', 'Marcos 9:37', 'Marcos', 9, 37, 'ος εαν εν των τοιουτων παιδιων δεξηται επι τω ονοματι μου εμε δεχεται και ος εαν εμε δεξηται ουκ εμε δεχεται αλλα τον αποστειλαντα με'),
('grc_f35', 'Marcos 9:38', 'Marcos', 9, 38, 'απεκριθη δε αυτω ο ιωαννης λεγων διδασκαλε ειδομεν τινα τω ονοματι σου εκβαλλοντα δαιμονια ος ουκ ακολουθει ημιν και εκωλυσαμεν αυτον οτι ουκ ακολουθει ημιν'),
('grc_f35', 'Marcos 9:39', 'Marcos', 9, 39, 'ο δε ιησους ειπεν μη κωλυετε αυτον ουδεις γαρ εστιν ος ποιησει δυναμιν επι τω ονοματι μου και δυνησεται ταχυ κακολογησαι με'),
('grc_f35', 'Marcos 9:40', 'Marcos', 9, 40, 'ος γαρ ουκ εστιν καθ υμων υπερ υμων εστιν'),
('grc_f35', 'Marcos 9:41', 'Marcos', 9, 41, 'ος γαρ αν ποτιση υμας ποτηριον υδατος εν ονοματι μου οτι χριστου εστε αμην λεγω υμιν ου μη απολεση τον μισθον αυτου'),
('grc_f35', 'Marcos 9:42', 'Marcos', 9, 42, 'και ος εαν σκανδαλιση ενα των μικρων των πιστευοντων εις εμε καλον εστιν αυτω μαλλον ει περικειται λιθος μυλικος περι τον τραχηλον αυτου και βεβληται εις την θαλασσαν'),
('grc_f35', 'Marcos 9:43', 'Marcos', 9, 43, 'και εαν σκανδαλιζη σε η χειρ σου αποκοψον αυτην καλον σοι εστιν κυλλον εις την ζωην εισελθειν η τας δυο χειρας εχοντα απελθειν εις την γεενναν εις το πυρ το ασβεστον'),
('grc_f35', 'Marcos 9:44', 'Marcos', 9, 44, 'οπου ο σκωληξ αυτων ου τελευτα και το πυρ ου σβεννυται'),
('grc_f35', 'Marcos 9:45', 'Marcos', 9, 45, 'και εαν ο πους σου σκανδαλιζη σε αποκοψον αυτον καλον εστιν σοι εισελθειν εις την ζωην χωλον η τους δυο ποδας εχοντα βληθηναι εις την γεενναν εις το πυρ το ασβεστον'),
('grc_f35', 'Marcos 9:46', 'Marcos', 9, 46, 'οπου ο σκωληξ αυτων ου τελευτα και το πυρ ου σβεννυται'),
('grc_f35', 'Marcos 9:47', 'Marcos', 9, 47, 'και εαν ο οφθαλμος σου σκανδαλιζη σε εκβαλε αυτον καλον σοι εστιν μονοφθαλμον εισελθειν εις την βασιλειαν του θεου η δυο οφθαλμους εχοντα βληθηναι εις την γεενναν του πυρος'),
('grc_f35', 'Marcos 9:48', 'Marcos', 9, 48, 'οπου ο σκωληξ ου τελευτα και το πυρ ου σβεννυται'),
('grc_f35', 'Marcos 9:49', 'Marcos', 9, 49, 'πας γαρ πυρι αλισθησεται και πασα θυσια αλι αλισθησεται'),
('grc_f35', 'Marcos 9:50', 'Marcos', 9, 50, 'καλον το αλας εαν δε το αλας αναλον γενηται εν τινι αυτο αρτυσετε εχετε εν εαυτοις αλας και ειρηνευετε εν αλληλοις'),
('grc_f35', 'Marcos 10:1', 'Marcos', 10, 1, 'κακειθεν αναστας ερχεται εις τα ορια της ιουδαιας δια του περαν του ιορδανου και συμπορευονται παλιν οχλοι προς αυτον και ως ειωθει παλιν εδιδασκεν αυτους'),
('grc_f35', 'Marcos 10:2', 'Marcos', 10, 2, 'και προσελθοντες φαρισαιοι επηρωτησαν αυτον ει εξεστιν ανδρι γυναικα απολυσαι πειραζοντες αυτον'),
('grc_f35', 'Marcos 10:3', 'Marcos', 10, 3, 'ο δε αποκριθεις ειπεν αυτοις τι υμιν ενετειλατο μωσης'),
('grc_f35', 'Marcos 10:4', 'Marcos', 10, 4, 'οι δε ειπον μωσης επετρεψεν βιβλιον αποστασιου γραψαι και απολυσαι'),
('grc_f35', 'Marcos 10:5', 'Marcos', 10, 5, 'και αποκριθεις ο ιησους ειπεν αυτοις προς την σκληροκαρδιαν υμων εγραψεν υμιν την εντολην ταυτην'),
('grc_f35', 'Marcos 10:6', 'Marcos', 10, 6, 'απο δε αρχης κτισεως αρσεν και θηλυ εποιησεν αυτους ο θεος'),
